package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Curated Geography Live Exam Hall Bank — Domain 5:
 * ජනගහන භූගෝල විද්‍යාව හා ජනාවාස (Population & Settlement Geography)
 */
internal object GeographyLiveExamPopulationBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun populationAndSettlementQuestions(): List<QSpec> {
    val t = "ජනගහන භූගෝල විද්‍යාව හා ජනාවාස"
    return listOf(
      q(t, "යම් රටක හෝ කලාපයක වර්ග කිලෝමීටරයක් තුළ ජීවත් වන සාමාන්‍ය ජන සංඛ්‍යාව හඳුන්වනු ලබන්නේ කුමන නමින්ද?",
        "භූමි ප්‍රමාණයට සාපේක්ෂව ගණනය කරන ජන ඝනත්වය", "වසරක් තුළ සිදුවන ජනගහන වර්ධන වේගය", "වැඩ කරන පිරිසට සාපේක්ෂ යැපුම් අනුපාතය", "දහසකට සිදුවන සජීවී උපත් අනුපාතය",
        "ජන ඝනත්වය යනු මුළු ජනගහනය මුළු භූමි ප්‍රමාණයෙන් (වර්ග කි.මී.) බෙදා ලබා ගන්නා අගයයි."),
      q(t, "සාමාන්‍ය ජන ඝනත්වයට වඩා 'කෘෂිකාර්මික ඉඩම් මත ජන ඝනත්වය' (Physiological Density) ගණනය කිරීම වැදගත් වන්නේ ඇයි?",
        "වගා කළ හැකි කෘෂිකාර්මික බිම් ඒකකයක් මත ජනගහනය ඇති කරන ආහාර පීඩනය නිවැරදිව පෙන්වන බැවින්", "කාන්තාර සහ කඳුකර බිම්වල වෙසෙන මුළු ජනගහනය පමණක් වෙන්කර ගණන් බලා දක්වන බැවින්", "වෙරළබඩ තැනිතලා හා ගංගා මෝය ආශ්‍රිත ධීවර ප්‍රජාවගේ ව්‍යාප්තිය පමණක් මැන බලන බැවින්", "වයස් කාණ්ඩ සහ ස්ත්‍රී පුරුෂ සංයුතිය අනුව නාගරික ශ්‍රම බලකාය බෙදා දක්වන බැවින්",
        "මුළු ජනගහනය වගා කළ හැකි ඉඩම් ප්‍රමාණයෙන් බෙදීමෙන් ඉඩම් හා ආහාර සැපයුම මත ඇති සැබෑ තෙරපුම මනිනු ලැබේ."),
      q(t, "'කෘෂිකාර්මික ජන ඝනත්වය' මගින් ප්‍රකාශ කෙරෙන්නේ කුමන ප්‍රමාණයන් දෙක අතර අනුපාතයද?",
        "කෘෂිකර්මාන්තයේ නියැලෙන ගොවි ජනගහනය සහ වගා කළ හැකි මුළු ඉඩම් ප්‍රමාණය අතර අනුපාතය", "නාගරික ප්‍රදේශවල වෙසෙන ජනගහනය සහ රක්ෂිත වනාන්තර ප්‍රමාණය අතර අනුපාතය", "වෙරළබඩ ධීවර කාර්මිකයන් සහ රටට අයත් සාගර කලාප ප්‍රමාණය අතර අනුපාතය", "රටේ මුළු ජනගහනය සහ ප්‍රධාන කර්මාන්තශාලා සංඛ්‍යාව අතර පවතින සෘජු අනුපාතය",
        "මෙය යම් රටක කෘෂිකර්මාන්තයේ යාන්ත්‍රිකරණ මට්ටම හා ගොවි ශ්‍රමය මත රඳා පැවැත්ම පෙන්නුම් කරයි."),
      q(t, "ජනගහන භූගෝල විද්‍යාවේ 'අශුද්ධ උපත් අනුපාතය' නිවැරදිව නිර්වචනය කරනු ලබන්නේ කෙසේද?",
        "නිශ්චිත වසරක් තුළ සාමාන්‍ය ජනගහනයේ සෑම පුද්ගලයන් 1,000 කටම සිදුවන සජීවී උපත් සංඛ්‍යාව", "සෑම පුද්ගලයන් 100 කටම එක් මසක් තුළ රෝහල්වල වාර්තා වන මුළු උපත් සංඛ්‍යාව", "වසර දහයක සංගණන කාලයක් තුළ කලාපයක අලුතින් එකතු වන මුළු දරු උපත් සංඛ්‍යාව", "ප්‍රජනක වයසේ පසුවන එක් කාන්තාවකට සිය ජීවිත කාලයේදී ලැබෙන සාමාන්‍ය දරුවන් ගණන",
        "අශුද්ධ උපත් අනුපාතය යනු (වසරේ සජීවී උපත් ÷ මධ්‍ය වාර්ෂික ජනගහනය) × 1,000 වේ."),
      q(t, "රටක මරණ අනුපාතය පහළ වැටී උපත් අනුපාතය තවදුරටත් ඉහළ මට්ටමක පවතින විට සිදුවන ජනගහන වෙනස කුමක්ද?",
        "ස්වාභාවික ජනගහන වර්ධන වේගය සීඝ්‍රයෙන් ඉහළ ගොස් ජනගහනය කඩිනමින් විශාල වීම", "උපත් හා මරණ එකිනෙක සමතුලිත වී ජනගහන වර්ධනය සම්පූර්ණයෙන්ම නතර වීම", "රටේ සමස්ත ජනගහනය කෙටි කලක් තුළ සෘණ අගයක් ගනිමින් ශීඝ්‍රයෙන් අඩු වීම", "වයස්ගත ජනගහනය පමණක් ඉහළ ගොස් තරුණ ශ්‍රම බලකාය ක්‍රමයෙන් හැකිලී යාම",
        "ස්වාභාවික වර්ධනය = උපත් අනුපාතය − මරණ අනුපාතය වන බැවින් උපත් වැඩි වී මරණ අඩු වන විට ජනගහනය වේගයෙන් වැඩි වේ."),
      q(t, "'ළදරු මරණ අනුපාතය' මගින් රටක සෞඛ්‍ය තත්ත්වය පිළිබඳව මනිනු ලබන්නේ කුමක්ද?",
        "වසරක් තුළ සජීවී උපත් 1,000 කින් වයස අවුරුදු 1 සම්පූර්ණ වීමට පෙර මියයන ළදරුවන් සංඛ්‍යාව", "වයස අවුරුදු 5 සිට 14 දක්වා පාසල් වයසේ දරුවන් අතර සිදුවන වාර්ෂික මරණ සංඛ්‍යාව", "ප්‍රසව කාලයේදී සංකූලතා හේතුවෙන් මියයන ගර්භණී මව්වරුන්ගේ සාමාන්‍ය වාර්ෂික සංඛ්‍යාව", "සමස්ත ජනගහනයෙන් පුද්ගලයන් 1,000 කට වසරකදී සිදුවන සියලුම වැඩිහිටි මරණ සංඛ්‍යාව",
        "ළදරු මරණ අනුපාතය රටක මාතෘ හා ළමා සෞඛ්‍ය සේවා, පෝෂණය හා සනීපාරක්ෂාව මැනීමේ ප්‍රධාන දර්ශකයකි."),
      q(t, "ජනගහනය ස්ථාවරව පවත්වා ගැනීමේ 'ප්‍රතිස්ථාපන සාඵල්‍යතා මට්ටම' ලෙස සැලකෙන්නේ කාන්තාවකට සාමාන්‍යයෙන් දරුවන් කී දෙනෙකු සිටින විටද?",
        "දරුවන් 2.1 ක් පමණ වන විට", "දරුවන් 4.8 ක් පමණ වන විට", "දරුවන් 1.2 ක් පමණ වන විට", "දරුවන් 6.0 ක් පමණ වන විට",
        "දෙමාපියන් දෙදෙනා ප්‍රතිස්ථාපනය වී ජනගහනය දිගුකාලීනව ස්ථාවරව පැවතීමට සාඵල්‍යතා අනුපාතය ~2.1 අවශ්‍ය වේ."),
      q(t, "ජන විකාශන සංක්‍රාන්ති ආකෘතියේ 'පළමු අදියරේ' ප්‍රධාන ජනගහන ලක්ෂණය කුමක්ද?",
        "උපත් අනුපාතය සහ මරණ අනුපාතය යන දෙකම ඉහළ මට්ටමක පැවතීම නිසා ජනගහන වර්ධනය මන්දගාමී වීම", "උපත් අනුපාතය සහ මරණ අනුපාතය යන දෙකම ඉතා පහළ මට්ටමක පැවතී ජනගහනය ස්ථාවර වීම", "මරණ අනුපාතය ශීඝ්‍රයෙන් පහත වැටී උපත් අනුපාතය ඉහළ මට්ටමක රැඳීමෙන් පිපිරුමක් ඇතිවීම", "උපත් අනුපාතය මරණ අනුපාතයට වඩා පහළ බැස සමස්ත ජනගහනය ස්වාභාවිකව අඩු වීමට පටන් ගැනීම",
        "වසංගත, සාගත හා ප්‍රාථමික සෞඛ්‍ය පහසුකම් නිසා පූර්ව කාර්මික සමාජ මෙම අදියරේ පැවතුණි."),
      q(t, "ජන විකාශන සංක්‍රාන්ති ආකෘතියේ 'දෙවන අදියරේදී' ජනගහනය ශීඝ්‍රයෙන් වැඩි වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "සෞඛ්‍ය, සනීපාරක්ෂාව හා ආහාර සැපයුම දියුණු වී මරණ අනුපාතය අඩු වුවද උපත් අනුපාතය ඉහළව පැවතීම", "නාගරීකරණය හා කාන්තා රැකියා නියුක්තිය නිසා උපත් අනුපාතය වහාම පහළ මට්ටමකට වැටීම", "වෙනත් මහාද්වීපවලින් විශාල සංක්‍රමණිකයන් පිරිසක් කෙටි කලකින් රට තුළට පැමිණ පදිංචි වීම", "වෛද්‍ය පහසුකම් දුර්වල වීම හේතුවෙන් වැඩිහිටියන්ගේ ආයු අපේක්ෂාව ක්‍රමයෙන් අඩු වී යාම",
        "මරණ අනුපාතය වේගයෙන් පහත වැටුණද සමාජීය හා සංස්කෘතික හේතු මත උපත් අනුපාතය ඉහළ මට්ටමක රැඳේ."),
      q(t, "ජන විකාශන සංක්‍රාන්ති ආකෘතියේ 'තෙවන අදියරේදී' ජනගහන වර්ධනය මන්දගාමී වීමට බලපාන ප්‍රධාන වෙනස්කම කුමක්ද?",
        "කාන්තා අධ්‍යාපනය, නාගරීකරණය හා පවුල් සැලසුම් ප්‍රවර්ධනය නිසා උපත් අනුපාතය ක්‍රමයෙන් පහත වැටීම", "බෝවන රෝග හා සාගත යළි පැතිරී යාම නිසා මරණ අනුපාතය නැවත ඉහළ මට්ටමකට පැමිණීම", "නාගරික ජනගහනය සිය රැකියා අතහැර ග්‍රාමීය කෘෂිකාර්මික ප්‍රදේශ වෙත ආපසු සංක්‍රමණය වීම", "සංවර්ධනය හේතුවෙන් ආයු අපේක්ෂාව අඩු වී ළදරු මරණ අනුපාතය නැවත වරක් ඉහළ නැගීම",
        "ළදරු මරණ අඩු වීමත් සමඟ දෙමාපියන් කුඩා පවුල් වෙත යොමු වන බැවින් උපත් අනුපාතය පහළ බසී."),
      q(t, "ජන විකාශන සංක්‍රාන්ති ආකෘතියේ අවසන් අදියරවල (සිව්වන හා පස්වන අදියර) ස්ථාවර හෝ වයස්ගත ජනගහන ලක්ෂණ පෙන්වන රටවල් කවරේද?",
        "ජපානය, ජර්මනිය, ඉතාලිය සහ ස්වීඩනය වැනි සංවර්ධිත රටවල්", "නයිජර්, චැඩ්, මාලි සහ සෝමාලියාව වැනි අප්‍රිකානු රටවල්", "ඇෆ්ගනිස්ථානය, යේමනය සහ නේපාලය වැනි ආසියානු රටවල්", "කොංගෝ, උගන්ඩාව සහ බුරුන්ඩි වැනි සමකාසන්න රටවල්",
        "මෙම සංවර්ධිත රටවල උපත් හා මරණ අනුපාත දෙකම අඩු අතර ජපානයේ ස්වාභාවික ජනගහන අඩුවීමක්ද දක්නට ලැබේ."),
      q(t, "'ජනගහන පිරමීඩයක්' (වයස්-ස්ත්‍රී පුරුෂ සටහනක්) මගින් ප්‍රධාන වශයෙන් නිරූපණය කරනු ලබන්නේ කුමන දත්තද?",
        "රටක ජනගහනයේ වයස් කාණ්ඩ අනුව ව්‍යාප්තිය සහ ස්ත්‍රී-පුරුෂ සංයුතිය", "රටේ පවුල් අතර ඒක පුද්ගල ආදායම හා ධනය බෙදී යන සමාජ ස්තර රටාව", "රට තුළ වෙසෙන විවිධ ජනවාර්ගික හා ආගමික කණ්ඩායම්වල ප්‍රතිශත ව්‍යාප්තිය", "රටේ ප්‍රාථමික, ද්විතීයික හා සේවා අංශවල රැකියා නියුක්තිය බෙදී යන ආකාරය",
        "පිරමීඩයේ පාදම, මැද හා මුදුන උපත්, මරණ, ආයු අපේක්ෂාව හා යැපුම් අනුපාතය පිළිබිඹු කරයි."),
      q(t, "පුළුල් පාදමක් සහ ඉතා පටු මුදුනක් සහිත ත්‍රිකෝණාකාර ජනගහන පිරමීඩයක් පෙන්නුම් කරන්නේ කුමන තත්ත්වයක්ද?",
        "ඉහළ උපත් අනුපාතයක්, වේගවත් ජනගහන වර්ධනයක්, ඉහළ ළමා ප්‍රතිශතයක් සහ අඩු ආයු අපේක්ෂාවක්", "පහළ උපත් අනුපාතයක්, මන්දගාමී වර්ධනයක් සහ වැඩිහිටි ජනගහනය ඉහළ යාමේ ප්‍රවණතාවක්", "උපත් අනුපාතය මරණ අනුපාතයට වඩා අඩු වීමෙන් ඇති වූ සෘණ ජනගහන වර්ධන තත්ත්වයක්", "විශාල විදේශීය තරුණ ශ්‍රමිකයන් පිරිසක් ආගමනය වීම නිසා ඇති වූ පිරිමි බහුතර තත්ත්වයක්",
        "සංවර්ධනය වෙමින් පවතින බොහෝ රටවල මෙවැනි පුළුල් පාදමක් සහිත ප්‍රසාරණ පිරමීඩ දක්නට ලැබේ."),
      q(t, "පටු පාදමක් සහ ඉහළ කොටස පුළුල් වූ සීනුවක හැඩැති ජනගහන පිරමීඩයක් ඇති රටක් මුහුණ දෙන ප්‍රධාන සමාජ-ආර්ථික අභියෝගය කුමක්ද?",
        "තරුණ ශ්‍රම බලකාය හැකිලීමත් සමඟ වයස්ගත ජනගහනය ඉහළ ගොස් විශ්‍රාම වැටුප් හා සෞඛ්‍ය වියදම් වැඩි වීම", "ළමා ජනගහනය අධික ලෙස වැඩි වීම නිසා ප්‍රාථමික පාසල් හා ළමා සෞඛ්‍ය පහසුකම් හිඟ වීම", "වැඩ කරන වයසේ තරුණ පිරිස අධික වීමෙන් කෘෂිකාර්මික ඉඩම් සඳහා දැඩි තදබදයක් ඇති වීම", "ආයු අපේක්ෂාව පහළ වැටීම නිසා වැඩිහිටි පුරවැසියන්ගේ සංඛ්‍යාව සීඝ්‍රයෙන් අඩු වී යාම",
        "ජපානය, දකුණු කොරියාව හා යුරෝපීය රටවල් මෙම වයස්ගත වීමේ අභියෝගයට මුහුණ දෙයි."),
      q(t, "ජන විකාශන විද්‍යාවේ 'ජනගහන ලාභාංශය' (Demographic Dividend) යනුවෙන් හඳුන්වන්නේ කුමක්ද?",
        "උපත් අඩු වී යැපෙන ළමුන් ගණන අඩු වන විට වැඩ කරන වයසේ ශ්‍රම බලකාය ඉහළ ගොස් ආර්ථික වර්ධනයට ලැබෙන වාසිය", "වයස්ගත පුරවැසියන් වැඩි වීම නිසා රජය විසින් සියලු දෙනාට විශ්‍රාම වැටුප් ලබා දීමෙන් ලැබෙන වාසිය", "උගත් වෘත්තිකයන් විදේශ රටවල සේවයට යැවීමෙන් ජනගහන ඝනත්වය අඩු කර ගැනීමෙන් ලැබෙන ආර්ථික වාසිය", "රටේ සියලුම වැසියන්ට රජය මගින් සහනාධාර ආහාර හා නිවාස නොමිලේ බෙදා හැරීමෙන් ලැබෙන ප්‍රතිලාභය",
        "නැගෙනහිර ආසියානු රටවල් සිය ආර්ථික සංවර්ධනය වේගවත් කිරීමට මෙම කාල පරිච්ඡේදය සාර්ථකව භාවිත කළේය."),
      q(t, "'යැපුම් අනුපාතය' ගණනය කිරීමේදී 'යැපෙන ජනගහනය' ලෙස සාමාන්‍යයෙන් සලකනු ලබන වයස් කාණ්ඩ මොනවාද?",
        "වයස අවුරුදු 0–14 අතර ළමා ජනගහනය සහ අවුරුදු 65 ට වැඩි වැඩිහිටි ජනගහනය", "වයස අවුරුදු 15–34 අතර තරුණ ජනගහනය සහ වයස අවුරුදු 35–54 අතර මැදි වයස් කාණ්ඩය", "රාජ්‍ය හා පෞද්ගලික අංශයේ ස්ථිර රැකියාවල නිරත වයස අවුරුදු 20–60 අතර සමස්ත ශ්‍රම බලකාය", "උසස් අධ්‍යාපන ආයතනවල හා වෘත්තීය පුහුණු මධ්‍යස්ථානවල ඉගෙනුම ලබන 18–25 වයස් කාණ්ඩය",
        "ළමා හා වැඩිහිටි යැපෙන්නන්ගේ එකතුව වැඩ කරන වයසේ (15–64) ජනගහනයෙන් බෙදා 100 න් ගුණ කරනු ලැබේ."),
      q(t, "මැදපෙරදිග ගල්ෆ් කලාපයේ රටවල (කටාර්, එක්සත් අරාබි එමීර් රාජ්‍යය) ජනගහනයේ පිරිමි ප්‍රතිශතය අසාමාන්‍ය ලෙස ඉහළ වීමට හේතුව කුමක්ද?",
        "ඉදිකිරීම් හා ඛනිජ තෙල් කර්මාන්ත සඳහා විශාල වශයෙන් තරුණ පිරිමි විදේශීය ශ්‍රමිකයන් සංක්‍රමණය වීම", "කලාපයේ උෂ්ණත්වය හා කාන්තාර දේශගුණය හේතුවෙන් කාන්තා ආයු අපේක්ෂාව ඉතා පහළ මට්ටමක පැවතීම", "ස්වාභාවික උපත් අනුපාතය තුළ පිරිමි දරු උපත් සංඛ්‍යාව ගැහැනු උපත්වලට වඩා දෙගුණයක් වීම", "කලාපීය යුද ගැටුම් හේතුවෙන් කාන්තාවන් හා දරුවන් විශාල වශයෙන් වෙනත් මහාද්වීපවලට පලා යාම",
        "රැකියා සඳහා පැමිණෙන විදේශීය ශ්‍රමිකයන් නිසා මෙම රටවල ජනගහන පිරමීඩයේ වැඩ කරන පිරිමි පැත්ත ඉදිරියට නෙරා ඇත."),
      q(t, "'ජනගහනය දෙගුණ වීමේ කාලය' '70 රීතිය' අනුව ආසන්න වශයෙන් ගණනය කරන්නේ කෙසේද?",
        "70 යන අගය වාර්ෂික ජනගහන වර්ධන ප්‍රතිශතයෙන් බෙදීමෙන්", "100 යන අගය වාර්ෂික උපත් අනුපාතයෙන් වැඩි කිරීමෙන්", "365 යන අගය අශුද්ධ මරණ අනුපාතයෙන් බෙදා ලැබෙන අගයෙන්", "රටේ මුළු ජනගහනය මුළු භූමි වර්ගඵලයෙන් බෙදා ගැනීමෙන්",
        "උදාහරණයක් ලෙස වාර්ෂික වර්ධන වේගය 2% නම් ජනගහනය දෙගුණ වීමට ආසන්න වශයෙන් 70 ÷ 2 = වසර 35 ක් ගතවේ."),
      q(t, "ජනගහනය හා සම්පත් පිළිබඳව තෝමස් මැල්තස් (1798) ඉදිරිපත් කළ ප්‍රධාන අදහස කුමක්ද?",
        "ජනගහනය වේගයෙන් වැඩි වන විට ආහාර නිෂ්පාදනය ඊට සමානුපාතිකව නොවැඩෙන බැවින් අනාගතයේදී සාගත හා අර්බුද ඇති වන බව", "තාක්ෂණික දියුණුව මගින් ආහාර නිෂ්පාදනය ජනගහනයට වඩා කිහිප ගුණයකින් ඉක්මනින් ඉහළ යන බව", "සියලුම සමාජ කාර්මීකරණය වූ පසු ජනගහනය ස්වාභාවිකව අඩු වී ආහාර සංචිත අතිරික්තයක් ඇති වන බව", "සාගර මත පාවෙන ගොවිපළවල් තැනීමෙන් ලෝකයේ ඕනෑම ජනගහනයක් පහසුවෙන් පෝෂණය කළ හැකි බව",
        "ජනගහන පීඩනය කෘෂි නවෝත්පාදන ඇති කරන බව පසුව එස්තර් බොස්රප් පෙන්වා දුන්නාය."),
      q(t, "ජනගහන විද්‍යාවේ 'ප්‍රශස්ත ජනගහනය' (Optimum Population) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "පවතින සම්පත් හා තාක්ෂණය උපරිමයෙන් යොදාගෙන ඒක පුද්ගල ආදායම හා ජීවන තත්ත්වය ඉහළම මට්ටමක තබා ගත හැකි ජන සංඛ්‍යාව", "රටක ඉඩම් සියල්ල නිවාසවලින් පිරී ගොස් වර්ග කිලෝමීටරයට වැඩිම ජන ඝනත්වයක් පවතින උපරිම සීමාව", "රටක උපත් හා මරණ සම්පූර්ණයෙන්ම සමාන වී නව ශ්‍රමිකයන් එකතු නොවන ස්ථිතික ජනගහන තත්ත්වය", "රැකියා වියුක්තිය ශුන්‍ය වුවද කෘෂිකාර්මික සම්පත් ප්‍රයෝජනයට ගැනීමට ශ්‍රමය ප්‍රමාණවත් නොවන තත්ත්වය",
        "මීට වඩා ජනගහනය අඩු වීම ඌන ජනගහනය ලෙසත් වැඩි වීම අධි ජනගහනය ලෙසත් හැඳින්වේ."),
      q(t, "සංක්‍රමණ භූගෝල විද්‍යාවේදී මිනිසුන් තම මුල් පදිංචි ස්ථානය අතහැර යාමට පොළඹවන 'තල්ලු සාධක' මොනවාද?",
        "රැකියා හිඟය, දිළිඳුකම, යුද ගැටුම්, නියඟ හා ගංවතුර වැනි ආපදා තත්ත්වයන්", "ඉහළ වැටුප්, ආරක්ෂිත පරිසරය හා උසස් අධ්‍යාපන පහසුකම් ලැබීමේ අවස්ථා", "සාමකාමී දේශපාලන වාතාවරණය හා නවීන පොදු ප්‍රවාහන පහසුකම් පැවතීම", "නවීන රෝහල් සේවා, විනෝදාස්වාදය හා ආකර්ෂණීය වෙළඳ මධ්‍යස්ථාන පිහිටීම",
        "නව ස්ථානයකට ආකර්ෂණය කරගන්නා වාසිදායක සාධක ඇදගැනීමේ සාධක ලෙස හැඳින්වේ."),
      q(t, "සංක්‍රමණය පිළිබඳ 'බුද්ධි ගලනය' (Brain Drain) යන්නෙන් විස්තර කෙරෙන ක්‍රියාවලිය කුමක්ද?",
        "වෛද්‍යවරුන්, ඉංජිනේරුවන් හා විද්‍යාඥයන් වැනි උසස් නිපුණතා ලත් වෘත්තිකයන් වඩා හොඳ පහසුකම් සොයා විදේශගත වීම", "නුපුහුණු කෘෂිකාර්මික කම්කරුවන් කාලීන අස්වනු නෙළීමේ රැකියා අවසන් කර නැවත ගමට පැමිණීම", "විදේශීය සංචාරකයන් කෙටි නිවාඩු සඳහා නිවර්තන දූපත් හා ඓතිහාසික නගර වෙත පැමිණීම", "විශ්‍රාම ලැබූ වැඩිහිටි පුරවැසියන් මහා නගරවල තදබදයෙන් මිදී ග්‍රාමීය වෙරළ තීරවල පදිංචි වීම",
        "බුද්ධි ගලනය මව් රටට පුහුණු මානව සම්පත අහිමි කළද, විදේශ ප්‍රේෂණ මගින් විදේශ විනිමය ගෙන එයි."),
      q(t, "'අභ්‍යන්තර අවතැන් වූවන්' සහ 'සරණාගතයන්' අතර ඇති ප්‍රධාන භූගෝලීය වෙනස කුමක්ද?",
        "සරණාගතයන් ජාත්‍යන්තර දේශසීමාවක් පසු කර වෙනත් රටකට පලා යන අතර අභ්‍යන්තර අවතැන් වූවන් තම රට ඇතුළතම ආරක්ෂිත පෙදෙසකට යයි", "සරණාගතයන් තම රටේ දේශසීමාව ඇතුළතම රැඳෙන අතර අභ්‍යන්තර අවතැන් වූවන් අසල්වැසි රටකට සංක්‍රමණය වේ", "දෙපිරිසම ස්වේච්ඡාවෙන් ඉහළ වැටුප් සහිත රැකියා සොයා තාවකාලික වීසා මත විදේශගත වන සංක්‍රමණිකයන් වේ", "ජාත්‍යන්තර නීතිය යටතේ මෙම කණ්ඩායම් දෙකම සමාන ලෙස අර්ථ දක්වා ඇති අතර භූගෝලීය පිහිටීම අනුව වෙනසක් නොපෙන්වයි",
        "එක්සත් ජාතීන්ගේ සරණාගත කොමසාරිස් කාර්යාලය (UNHCR) මොවුන්ගේ සුබසාධනය පිළිබඳ කටයුතු කරයි."),
      q(t, "කාලීන රැකියා හෝ සත්ත්ව පාලනය සඳහා වසරේ එක් කාලයකදී වෙනත් ප්‍රදේශයකට ගොස් නැවත පැමිණීම හඳුන්වන්නේ කෙසේද?",
        "සෘතුමය කාලීන සංක්‍රමණය", "ස්ථිර අන්තර් මහාද්වීපික විගමනය", "බලහත්කාර යුද අවතැන් වීම", "දෛනික නාගරික ගමනාගමනය",
        "කඳුකරයේ ගොපල්ලන් ගිම්හානයේ උස් තණබිම්වලට හා ශීත ඍතුවේ නිම්නවලට සතුන් ගෙන යාම මීට නිදසුනකි."),
      q(t, "ග්‍රාමීය ප්‍රදේශයක පුද්ගලයෙකු එකවර විශාල අගනුවරට නොගොස් කුඩා නගරයක සිට ප්‍රාදේශීය නගරය හරහා පියවරෙන් පියවර මහා නගරයට යාම කුමන නමින් හැඳින්වේද?",
        "පියවර සංක්‍රමණය (Step Migration)", "චක්‍රීය සංක්‍රමණය (Circular Migration)", "ප්‍රති-නාගරීකරණය (Counter-urbanization)", "බලහත්කාර සංක්‍රමණය (Forced Migration)",
        "බොහෝ අභ්‍යන්තර සංක්‍රමණ කෙටි දුරවලින් ආරම්භ වී පියවරෙන් පියවර විශාල නගර වෙත යොමු වේ."),
      q(t, "ස්ථිරව පදිංචිය වෙනස් නොකර රැකියා හෝ අධ්‍යාපනය සඳහා දිනපතා උදේ නගරයට පැමිණ සවස නිවසට යන ජන චලනය කුමක්ද?",
        "දෛනික ගමනාගමනය / සංචරණය (Commuting)", "ස්ථිර අන්තර්ජාතික සංක්‍රමණය", "නාගරික ප්‍රතිජීවනය හා පුනරුත්ථාපනය", "සෘතුමය කෘෂිකාර්මික සංක්‍රමණය",
        "තදාසන්න නේවාසික ප්‍රදේශ දියුණු වීමත් සමඟ දෛනික ගමනාගමනය විශාල ලෙස ඉහළ ගොස් ඇත."),
      q(t, "ලෝක ජනගහන ව්‍යාප්තිය ඉතා අසමතුලිත වීමට බලපාන ප්‍රධාන භෞතික භූගෝලීය සාධක මොනවාද?",
        "පැතලි තැනිතලා භූ විෂමතාව, මධ්‍යස්ථ දේශගුණය, සාරවත් පස සහ මිරිදිය ජල සැපයුම", "රටවල පරිපාලන දිස්ත්‍රික්ක සංඛ්‍යාව, ජාතික කොඩියේ සංකේත හා ප්‍රාදේශීය භාෂා ව්‍යවහාරය", "ප්‍රධාන වශයෙන් ගිනිකඳු පිපිරීම් සංඛ්‍යාව, උල්කාපාත වැටීම් හා භූ චුම්බක ධ්‍රැව පිහිටීම", "මහාද්වීපවල නාමකරණය, සාගර ගැඹුර හා ධ්‍රැවීය හිම කඳු සෑදීමේ වේගය",
        "ලෝක ජනගහනයෙන් ~90% ක් උතුරු අර්ධගෝලයේ වෙරළබඩ තැනිතලා හා ගංගා නිම්න ආශ්‍රිතව වෙසේ."),
      q(t, "ලෝකයේ ප්‍රධානතම ජනගහන සංකේන්ද්‍රණ කලාප හතර නිවැරදිව දැක්වෙන වරණය කුමක්ද?",
        "නැගෙනහිර ආසියාව, දකුණු ආසියාව, ගිනිකොණදිග ආසියාව සහ බටහිර යුරෝපය", "ඇන්ටාක්ටිකාව, ග්‍රීන්ලන්තය, සහරා කාන්තාරය සහ මධ්‍යම ඇමසන් වනාන්තරය", "මධ්‍යම ඔස්ට්‍රේලියාව, ඇලස්කාව, උතුරු සයිබීරියාව සහ ගෝබි කාන්තාරය", "අයිස්ලන්තය, උතුරු කැනඩාව, පැටගෝනියාව සහ නැමීබියා වෙරළ තීරය",
        "නැගෙනහිර හා දකුණු ආසියාවේ පමණක් ලෝක ජනගහනයෙන් අඩකට ආසන්න ප්‍රමාණයක් ජීවත් වේ."),
      q(t, "දකුණු හා නැගෙනහිර ආසියාවේ ඉන්දු-ගංගා, යැංසි හා හොවැංහෝ ගංගා නිම්නවල අධික ජන ඝනත්වයක් බිහිවීමට පදනම් වූ ප්‍රධාන සාධකය කුමක්ද?",
        "සාරවත් දියළු පස, මෝසම් ජල සැපයුම සහ දැඩි තෙත් වී වගාව සඳහා ඇති යෝග්‍යතාව", "කඳුකර ප්‍රදේශවල විශාල රන් ආකර හා දියමන්ති පතල් බහුල වශයෙන් පැවතීම", "වසර පුරාම පවතින අධික ශීතල හිම කඳු සහිත දේශගුණය හා ග්ලැසියර දියවීම", "විශාල කාන්තාර ආශ්‍රිතව ඛනිජ තෙල් හා ස්වාභාවික වායු නිධි කැණීමේ කර්මාන්ත",
        "තෙත් වී වගාව කුඩා බිම් ප්‍රමාණයකින් විශාල ජනගහනයක් පෝෂණය කිරීමට සමත් විය."),
      q(t, "බටහිර යුරෝපයේ අධික ජන ඝනත්වයක් බිහිවීමට බලපෑ ඓතිහාසික සාධකය ආසියාවට වඩා වෙනස් වන්නේ කෙසේද?",
        "කෘෂිකාර්මික සාධකවලට වඩා කාර්මික විප්ලවය, ගල් අඟුරු හා යපස් නිධි, කර්මාන්ත හා වෙළඳ නගර බිහිවීම", "තෙත් වී වගාව සහ මෝසම් වැසි මත පදනම් වූ ග්‍රාමීය වැව් ජනාවාස පැතිරී යාම", "සමස්ත ජනගහනයම සංචාරක එඬේර ජීවිතයකට හා කාන්තාර වෙළඳාමට යොමු වීම", "විශාල නිවර්තන වැසි වනාන්තර එළිපෙහෙළි කර තේ හා රබර් වතු ආරම්භ කිරීම",
        "බටහිර යුරෝපයේ ජනගහනයෙන් 75%–85% කට වඩා නාගරික කාර්මික හා සේවා අංශවල ජීවත් වේ."),
      q(t, "කැනඩාවේ උතුරු පෙදෙස්, සයිබීරියාව සහ ග්‍රීන්ලන්තය වැනි ඉහළ අක්ෂාංශ ප්‍රදේශ 'විරල ජනගහන කලාප' වීමට හේතුව කුමක්ද?",
        "අධික ශීතල දේශගුණය, කෙටි වගා කාලය සහ පස නිත්‍ය තුහින තත්ත්වයේ පැවතීම", "වසර පුරාම පවතින අධික උණුසුම, දැඩි වාෂ්පීකරණය සහ ජල උල්පත් සිඳී යාම", "සක්‍රීය ගිනිකඳු පිපිරීම් හා ලාවා ගලා යාම් නිරන්තරයෙන් සිදුවීම නිසා පදිංචියට නුසුදුසු වීම", "ඝන නිවර්තන වැසි වනාන්තර හා වගුරු බිම් නිසා ප්‍රවාහන මාර්ග ඉදිකිරීමට නොහැකි වීම",
        "ලෝක භූමි ප්‍රමාණයෙන් විශාල කොටසක් වසාගෙන සිටියද මෙම ධ්‍රැව ආසන්න පෙදෙස්වල වෙසෙන්නේ සුළු පිරිසකි."),
      q(t, "'ජනගහන මධ්‍යස්ථානය' (Center of Population) යන භූගෝලීය සංකල්පයෙන් අදහස් කරන්නේ කුමක්ද?",
        "රටක සියලුම පදිංචිකරුවන්ගේ ව්‍යාප්තිය අනුව ජනගහන බර සමතුලිත වන භූගෝලීය ලක්ෂ්‍යය", "රටේ පාර්ලිමේන්තුව හා අමාත්‍යාංශ පිහිටුවා ඇති ඓතිහාසික පරිපාලන අගනුවර පමණි", "රටේ භූමි ප්‍රමාණය හරි අඩකින් බෙදෙන හරියටම මධ්‍යයේ පිහිටි උසම කඳු මුදුන", "වැඩිම රෝහල්, පාසල් හා වෙළඳ සංකීර්ණ සංඛ්‍යාවක් පිහිටි ප්‍රධාන වරාය නගරය",
        "ජනගහනය වෙනත් කලාපයකට සංක්‍රමණය වන විට මෙම සමතුලිත ලක්ෂ්‍යය එම දිශාවට මාරු වේ."),
      q(t, "වර්තමාන ලෝක ජනගහන ප්‍රවණතා අනුව ඉන්දියාව චීනය අභිබවා ලොව වැඩිම ජනගහනය සිටින රට බවට පත්වූයේ ඇයි?",
        "චීනයේ උපත් පාලන ප්‍රතිපත්ති නිසා උපත් අඩු වීමත් ඉන්දියාවේ විශාල තරුණ ජනගහන ගම්‍යතාවත් නිසා", "චීනයේ මුළු ජනගහනයෙන් අඩකට වඩා වෙනත් මහාද්වීපවලට ස්ථිරව සංක්‍රමණය වී යාම නිසා", "ඉන්දියාවේ භූගෝලීය භූමි ප්‍රමාණය හා කෘෂි ඉඩම් ප්‍රමාණය පසුගිය දශකයේදී දෙගුණ වූ නිසා", "චීනයේ සියලුම කෘෂිකාර්මික හා කාර්මික නිෂ්පාදන ක්‍රියාවලීන් සම්පූර්ණයෙන් නතර වූ නිසා",
        "තරුණ පරපුර විශාල වීම නිසා සාඵල්‍යතාව අඩු වුවද තවත් දශක කිහිපයක් ජනගහනය වැඩි වීම ජනගහන ගම්‍යතාවයි."),
      q(t, "ජනාවාසයක් පිහිටුවීමේ 'ස්ථානය' (Site) සහ 'පිහිටුම් සම්බන්ධතාව' (Situation) අතර වෙනස කුමක්ද?",
        "Site යනු ජනාවාසය ඉදි කළ භෞතික භූමි ස්වභාවය වන අතර Situation යනු අවට නගර හා මාර්ගවලට ඇති සාපේක්ෂ පිහිටීමයි", "Site සහ Situation යන දෙකම ජනාවාසයක ජන ඝනත්වය මැනීමට යොදා ගන්නා එකම සංඛ්‍යාත්මක දර්ශක වේ", "Site යනු නගරයේ මුළු ජනගහනය වන අතර Situation යනු නගරයේ වෙළඳසැල් හා බැංකු සංඛ්‍යාවයි", "Site යනු ප්‍රදේශයේ වාර්ෂික වර්ෂාපතනය වන අතර Situation යනු සාමාන්‍ය දෛනික උෂ්ණත්ව අගයයි",
        "සිංගප්පූරුව කුඩා දූපතක් වුවද (Site), මලක්කා සමුද්‍ර සන්ධියේ පිහිටීම (Situation) එහි දියුණුවට හේතු විය."),
      q(t, "නිවාස එකිනෙකට ඉතා සමීපව ගොනු වී පොකුරක් ලෙස පිහිටි ජනාවාස රටාව හඳුන්වනු ලබන්නේ කුමන නමින්ද?",
        "ගොනු වූ හෙවත් කේන්ද්‍රගත ජනාවාස රටාව (Nucleated)", "විසිරුණු හෙවත් ඒකාකාර නොවන ජනාවාස රටාව (Dispersed)", "රේඛීය හෙවත් දිගටි ජනාවාස රටාව (Linear)", "තාරකා හෙවත් රේඩියල් ජනාවාස රටාව (Radial)",
        "ජල මූලාශ්‍රයක් (වැවක්), පොදු ආරක්ෂාවක් හෝ සාරවත් ගොවි බිම් මධ්‍යයේ ගොනු වූ ජනාවාස බහුලව බිහිවේ."),
      q(t, "මහාමාර්ගයක්, ගංගා ඉවුරක්, ඇළක් හෝ වෙරළ තීරයක් දිගේ දිගට විහිදී ඇති ජනාවාස රටාව කුමක්ද?",
        "රේඛීය ජනාවාස රටාව (Linear Settlement)", "ගොනු වූ ජනාවාස රටාව (Nucleated Settlement)", "විසිරුණු ජනාවාස රටාව (Dispersed Settlement)", "වෘත්තාකාර ජනාවාස රටාව (Circular Settlement)",
        "ප්‍රවාහන පහසුව හා ජල පහසුව ලබා ගැනීමට මිනිසුන් මාර්ග හා ගංගා දෙපස නිවාස ඉදිකරන විට රේඛීය රටාව ඇතිවේ."),
      q(t, "විශාල කඳුකර ප්‍රදේශවල, වතුයායවල හෝ විශාල තනි ගොවිපළවල නිවාස එකිනෙකින් දුරින් පිහිටන ජනාවාස රටාව කුමක්ද?",
        "විසිරුණු ජනාවාස රටාව (Dispersed Settlement)", "රේඛීය ජනාවාස රටාව (Linear Settlement)", "ගොනු වූ ජනාවාස රටාව (Nucleated Settlement)", "මංසන්ධි ජනාවාස රටාව (Crossroads Settlement)",
        "විශාල තනි ගොවිපළවල් හා උස් කඳු බෑවුම් පවතින පෙදෙස්වල විසිරුණු ජනාවාස දක්නට ලැබේ."),
      q(t, "ග්‍රාමීය ජනාවාසයක් සහ නාගරික ජනාවාසයක් අතර ඇති ප්‍රධාන ආර්ථික ක්‍රියාකාරකම් වෙනස කුමක්ද?",
        "ග්‍රාමීය ජනාවාස ප්‍රාථමික අංශ මත රඳා පවතින අතර නාගරික ජනාවාස ද්විතීයික හා සේවා අංශ මත රඳා පවතී", "නාගරික ජනාවාස ප්‍රධාන වශයෙන් තෙත් වී ගොවිතැන මත රඳා පවතින අතර ග්‍රාමීය ජනාවාස බැංකු සේවා මත පදනම් වේ", "ග්‍රාමීය ජනාවාසවල මහා පරිමාණ වානේ කර්මාන්ත පමණක් ඇති අතර නගරවල වන වගාව පමණක් සිදු කෙරේ", "දෙවර්ගයේම ජනාවාස සම්පූර්ණයෙන්ම එකම කෘෂිකාර්මික වෘත්තීන් මත රඳා පවතින අතර වෙනසක් නොපෙන්වයි",
        "එමෙන්ම නගරවල ජන ඝනත්වය හා ගොඩනැගිලි ඝනත්වය ගමට වඩා බෙහෙවින් වැඩිය."),
      q(t, "'නාගරීකරණය' (Urbanization) යනුවෙන් භූගෝල විද්‍යාවේදී නිවැරදිව අර්ථ දක්වන්නේ කුමක්ද?",
        "රටක මුළු ජනගහනයෙන් නාගරික ප්‍රදේශවල ජීවත් වන ජනගහන ප්‍රතිශතය ඉහළ යාමේ ක්‍රියාවලිය", "නාගරික මහාමාර්ග දෙපස උද්‍යාන ඉදි කර වෘක්ෂලතා ආවරණය වැඩි දියුණු කිරීමේ පාරිසරික වැඩසටහන", "නගරවල වෙසෙන ජනගහනය අඩු වී ග්‍රාමීය කෘෂිකාර්මික ජනගහන ප්‍රතිශතය සීඝ්‍රයෙන් ඉහළ යාම", "පැරණි ඓතිහාසික නගර කඩා බිඳ දමා ඒවා නැවත ස්වාභාවික වනාන්තර බවට පත් කිරීමේ ක්‍රියාවලිය",
        "1950 දී ලෝක ජනගහනයෙන් ~30% ක් නාගරික වූ අතර වර්තමානයේ එය 56% කට වඩා ඉහළ ගොස් ඇත."),
      q(t, "ජනගහනය මිලියන 10 කට (කෝටියකට) වඩා වැඩි අතිවිශාල නගරයක් හඳුන්වනු ලබන්නේ කුමන නමින්ද?",
        "මෙගා නගරය (Megacity)", "කුඩා නගරය (Small Town)", "ග්‍රාමීය සේවා මධ්‍යස්ථානය (Hamlet)", "වෙළඳ ගම්මානය (Market Village)",
        "ටෝකියෝ, දිල්ලි, ෂැංහයි, සාඕ පාවුලෝ, මෙක්සිකෝ සිටි හා කයිරෝ ලොව ප්‍රධාන මෙගා නගර අතර වේ."),
      q(t, "'ප්‍රමුඛ නගරය' (Primate City) යන සංකල්පය මගින් විස්තර කෙරෙන්නේ කුමන ආකාරයේ නගරයක්ද?",
        "රටේ දෙවන විශාලතම නගරය මෙන් දෙගුණයකටත් වඩා විශාල, ආර්ථික හා පරිපාලන බලය ඒකරාශී වූ ප්‍රධාන නගරය", "රටේ පිහිටි සියලුම නගර අතරින් අඩුම ජනගහනයක් හා අඩුම වෙළඳ සේවා ප්‍රමාණයක් සහිත කුඩා නගරය", "ග්‍රාමීය ප්‍රදේශයක ගොවිපළවල් කිහිපයකට පමණක් අත්‍යවශ්‍ය භාණ්ඩ සපයන කුඩා සතිපොළ ගම්මානය", "ජාත්‍යන්තර දේශසීමාවක හමුදා ආරක්ෂාව සඳහා පමණක් පිහිටුවා ඇති හුදකලා මුරපොළ නගරය",
        "බැංකොක්, ලන්ඩන් හෝ පැරිස් ප්‍රමුඛ නගර සඳහා සම්භාව්‍ය උදාහරණ වේ."),
      q(t, "නාගරික භූමි පරිභෝජන ආකෘති අනුව නගරයක හරි මැදම පිහිටි ප්‍රධාන වාණිජ කලාපය කුමක්ද?",
        "මධ්‍යම ව්‍යාපාරික දිස්ත්‍රික්කය (CBD)", "නගරයෙන් පිටත පිහිටි ගොවිපළ කලාපය", "අඩු ඝනත්ව නේවාසික තදාසන්න කලාපය", "පාරිසරික රක්ෂිත වනාන්තර කලාපය",
        "මධ්‍යම ව්‍යාපාරික දිස්ත්‍රික්කයේ බැංකු, ප්‍රධාන කාර්යාල, වෙළඳ සංකීර්ණ සහ ප්‍රවාහන මධ්‍යස්ථාන පිහිටයි."),
      q(t, "නගරයක මධ්‍යම ව්‍යාපාරික දිස්ත්‍රික්කයේ අහස උසට නැගුණු බහුමහල් ගොඩනැගිලි ඉදි වීමට ප්‍රධාන ආර්ථික හේතුව කුමක්ද?",
        "ඉඩම් ඉල්ලුම හා ඉඩම් මිල ඉතා ඉහළ වීම නිසා සීමිත බිම් කැබැල්ලකින් උපරිම මහල් ඉඩක් ලබා ගැනීම", "සාගර සුළං ප්‍රවාහවලින් ගොඩනැගිලි සම්පූර්ණයෙන්ම ආරක්ෂා කර ගැනීමට පහසු බැවින්", "නාගරික ප්‍රදේශවල වැසි ජලය වහල මත රැස් කර ගංගාවලට බැස යාම පාලනය කිරීම සඳහා", "නගර මධ්‍යයේ ඉඩම් මිල අවට ග්‍රාමීය ප්‍රදේශවලට වඩා ඉතා අඩු අගයක පවතින බැවින්",
        "නගර මධ්‍යයේ ඉඩම් සඳහා ඇති දැඩි තරගය නිසා ගොඩනැගිලි සිරස් අතට උස්ව ඉදි කෙරේ."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවල විශාල නගරවල අනවසර හා පැල්පත් ජනාවාස බිහිවීමට ප්‍රධාන හේතුව කුමක්ද?",
        "වේගවත් ග්‍රාමීය-නාගරික සංක්‍රමණයට සරිලන පරිදි දැරිය හැකි නිවාස හා යටිතල පහසුකම් නගරයේ නොමැති වීම", "නගර මධ්‍යයේ ඉඩම් මිල අතිශයින් අඩු වී විශාල හිස් භූමි ප්‍රමාණයක් ඉතිරි වීම නිසා", "නාගරික ජනගහනය ක්‍රමයෙන් අඩු වී සියලුම ස්ථිර නිවාස හිස්ව පැවතීම නිසා", "කඳුකර වනාන්තරවල සිටින වන සතුන්ගෙන් ආරක්ෂා වීමට මිනිසුන් ගං ඉවුරුවලට යාම නිසා",
        "මෙවැනි ජනාවාසවල පිරිසිදු පානීය ජලය, සනීපාරක්ෂාව හා ගංවතුර ආරක්ෂාව අවම මට්ටමක පවතී."),
      q(t, "'නාගරික තාප දූපත' (Urban Heat Island) යනු නගරාශ්‍රිතව ඇතිවන කුමන පාරිසරික සංසිද්ධියද?",
        "කොන්ක්‍රීට්, තාර, වාහන දුම සහ ගස් කොළන් අඩුවීම නිසා නගර මධ්‍යයේ උෂ්ණත්වය අවට ග්‍රාමීය පෙදෙස්වලට වඩා ඉහළ යාම", "මහා නගරයක් සම්පූර්ණයෙන්ම සාගරයෙන් වට වූ කුඩා ගිනිකඳු දූපතක් මධ්‍යයේ පිහිටා තිබීම", "ශීත ඍතුවේදී නගර මධ්‍යයට පමණක් හිම පතනය වී අවට ග්‍රාමීය පෙදෙස් වියළිව පැවතීම", "නගර මධ්‍යයේ වායු උෂ්ණත්වය අවට ග්‍රාමීය කෘෂිකාර්මික පෙදෙස්වලට වඩා සැමවිටම අඩුවෙන් පැවතීම",
        "නාගරික හරිත උද්‍යාන, සෙවණ දෙන ගස් හා ජල මූලාශ්‍ර මගින් මෙම තාප බලපෑම අවම කළ හැකිය."),
      q(t, "'නාගරික පැතිරීම' (Urban Sprawl) නිසා නගරය අවට ප්‍රදේශවලට ඇතිවන ප්‍රධාන පාරිසරික හා ප්‍රවාහන ගැටලුව කුමක්ද?",
        "අවට කෘෂිකාර්මික හා වනාන්තර ඉඩම් විනාශ වීම, මාර්ග තදබදය වැඩි වීම සහ සේවා සැපයීමේ පිරිවැය ඉහළ යාම", "නගරයේ සමස්ත ජනගහනය වර්ධනය වීම සම්පූර්ණයෙන්ම නැවතී නගරය ජනශූන්‍ය බවට පත් වීම", "අවට පරිසරයේ වැව් හා භූගත පානීය ජල සංචිත ක්ෂණිකව දෙගුණයකින් ඉහළ යාම", "නගරවාසීන්ට ප්‍රවාහන පහසුකම් හා මහාමාර්ග කිසිසේත් අවශ්‍ය නොවන තත්ත්වයක් උදා වීම",
        "සැලසුම් රහිතව අඩු ඝනත්වයකින් නගරය පිටතට පැතිරීම තිරසාර නොවන බව සැලසුම්කරුවන් පෙන්වා දෙයි."),
      q(t, "'ප්‍රති-නාගරීකරණය' (Counter-urbanization) යන්නෙන් විස්තර කෙරෙන්නේ කුමන ජන චලන ක්‍රියාවලියද?",
        "මහා නගරවල තදබදය, දූෂණය හා ඉහළ ජීවන වියදම නිසා ජනතාව නගර හැර ග්‍රාමීය හෝ කුඩා නගර වෙත පදිංචියට යාම", "ග්‍රාමීය කෘෂිකාර්මික ප්‍රදේශවලින් තරුණ පිරිස රැකියා සොයා ප්‍රධාන මහා නගර වෙත සංක්‍රමණය වීම", "දේශපාලන හේතු මත පුරවැසියන් සිය මව් රට අතහැර වෙනත් විදේශීය රටක ස්ථිර පදිංචියට යාම", "සියලුම ග්‍රාමීය ගම්මාන කඩිනමින් කාර්මික හා වාණිජ නගර බවට පරිවර්තනය කිරීමේ රාජ්‍ය වැඩපිළිවෙළ",
        "අන්තර්ජාලය හා දුරස්ථ රැකියා පහසුකම් නිසා සංවර්ධිත රටවල මෙම ප්‍රවණතාව දක්නට ලැබේ."),
      q(t, "නගරවල පැරණි හා පරිහානියට පත් නේවාසික ප්‍රදේශ නවීකරණය කිරීමේදී මුල් අඩු ආදායම්ලාභීන්ට මුහුණ දීමට සිදුවන ගැටලුව කුමක්ද?",
        "දේපළ මිල හා නිවාස කුලී ඉහළ යාම නිසා මුල් අඩු ආදායම්ලාභී පදිංචිකරුවන්ට එම ප්‍රදේශයෙන් ඉවත් වීමට සිදුවීම", "නවීකරණය කරන ලද සමස්ත නාගරික ප්‍රදේශයම යළි කෘෂිකාර්මික වී ගොවි බිමක් බවට පත් වීම", "නගරයේ පවතින සියලුම පැරණි හා නව ගොඩනැගිලි කඩා දමා ජනශූන්‍ය වනාන්තරයක් ඇති වීම", "නව ව්‍යාපාර ආරම්භ වුවද නගරයේ පොදු ප්‍රවාහන හා වෙළඳ සේවා සම්පූර්ණයෙන්ම නැති වී යාම",
        "නාගරික පුනර්ජීවන ක්‍රියාවලීන්හිදී පැරණි පදිංචිකරුවන්ගේ නිවාස සුරක්ෂිතතාව ගැනද අවධානය යොමු කළ යුතුය."),
      q(t, "ජනාවාසයක ප්‍රමාණය අනුව එහි පවතින සේවා විවිධත්වය වෙනස් වන්නේ කෙසේද?",
        "විශාල නගරවල විශේෂිත රෝහල් හා විශ්වවිද්‍යාල පවතින අතර කුඩා ගම්මානවල දෛනික මූලික සේවා පමණක් පවතී", "කුඩා ගම්මාන සෑම එකකම ජාත්‍යන්තර ගුවන්තොටුපළ හා විශ්වවිද්‍යාල පවතින අතර නගරවල ඒවා නොමැත", "නගරයේ ප්‍රමාණය හා ජනගහනය කුමක් වුවත් සියලුම ජනාවාසවල පවතින සේවා ප්‍රමාණය සම්පූර්ණයෙන්ම සමාන වේ", "ප්‍රමාණයෙන් කුඩාම හුදකලා නිවාස පොකුරුවල වැඩිම වාණිජ බැංකු හා සුපිරි වෙළඳ සංකීර්ණ සංඛ්‍යාවක් පිහිටයි",
        "ජනාවාස ධුරාවලියේ ඉහළට යත්ම විශේෂිත සේවා ප්‍රමාණය හා වෙළඳපොළ පරාසය ඉහළ යයි."),
      q(t, "ප්‍රසාරණය වෙමින් එකිනෙකට යා වී පොදු විශාල නාගරික කලාපයක් සාදන නගර කිහිපයක එකතුව හඳුන්වන්නේ කුමන නමින්ද?",
        "සමූහ නගරය (Conurbation)", "හුදකලා කඳුකර ගම්මානය (Hamlet)", "වැව් බැඳි කෘෂි ගම්මානය (Rural Village)", "කුඩා ධීවර තොටුපළ (Fishing Port)",
        "ලන්ඩන්, ටෝකියෝ හා ජර්මනියේ රුර් කලාපය මෙවැනි සමූහ නගර සඳහා ප්‍රධාන උදාහරණ වේ."),
      q(t, "ජනගහන වර්ධනය පාලනය කිරීම සඳහා චීනය අතීතයේ ක්‍රියාත්මක කළ 'එක් දරු ප්‍රතිපත්තිය' කුමන වර්ගයේ ප්‍රතිපත්තියක්ද?",
        "උපත් සංඛ්‍යාව සීමා කරන උපත් විරෝධී (Anti-natalist) ප්‍රතිපත්තියක්", "වැඩි දරු උපත් සංඛ්‍යාවක් දිරිමත් කරන ප්‍රවර්ධන (Pro-natalist) ප්‍රතිපත්තියක්", "නාගරික තදබදය අඩු කිරීමේ ග්‍රාමීය සංක්‍රමණ (Migration) ප්‍රතිපත්තියක්", "කෘෂිකාර්මික අස්වැන්න වැඩි කිරීමේ ආහාර ආනයන (Food Policy) ප්‍රතිපත්තියක්",
        "ඊට ප්‍රතිවිරුද්ධව උපත් අඩු ප්‍රංශය, සිංගප්පූරුව හා ජපානය දරු ප්‍රසූති දිරිමත් කරන ප්‍රතිපත්ති ක්‍රියාත්මක කරයි."),
      q(t, "ජනගහනය වේගයෙන් වයස්ගත වන සංවර්ධිත රටවල් ශ්‍රම හිඟය පියවා ගැනීමට ගන්නා ප්‍රධාන පියවර මොනවාද?",
        "විශ්‍රාම යන වයස ඉහළ දැමීම, ස්වයංක්‍රීයකරණය භාවිතය සහ පුහුණු විදේශීය ශ්‍රමිකයන් බඳවා ගැනීම", "ප්‍රාථමික හා ද්විතීයික පාසල් පද්ධතිය සම්පූර්ණයෙන්ම වසා දමා අධ්‍යාපන වියදම් කපා හැරීම", "රජයේ රෝහල් හා වැඩිහිටි රැකවරණ මධ්‍යස්ථාන සංඛ්‍යාව අඩු කර සෞඛ්‍ය සේවා සීමා කිරීම", "නාගරික කර්මාන්තශාලා සියල්ල නවතා දමා නැවත සම්ප්‍රදායික කෘෂිකර්මයට පමණක් යොමු වීම",
        "කැනඩාව, ජර්මනිය සහ ඔස්ට්‍රේලියාව කුසලතා පදනම් කරගත් සංක්‍රමණ ක්‍රම මගින් ශ්‍රම බලකාය පවත්වා ගනී."),
      q(t, "ශ්‍රී ලංකාවේ දිස්ත්‍රික්ක අතරින් වර්ග කිලෝමීටරයට ඉහළම ජන ඝනත්වය වාර්තා වන දිස්ත්‍රික්කය කුමක්ද?",
        "කොළඹ දිස්ත්‍රික්කය", "මුලතිව් දිස්ත්‍රික්කය", "මොණරාගල දිස්ත්‍රික්කය", "වවුනියාව දිස්ත්‍රික්කය",
        "ශ්‍රී ලංකාවේ බස්නාහිර පළාතේ පමණක් රටේ මුළු ජනගහනයෙන් හතරෙන් පංගුවකට වඩා ජීවත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ අඩුම ජන ඝනත්වයක් දක්නට ලැබෙන දිස්ත්‍රික්ක කාණ්ඩය නිවැරදිව දැක්වෙන්නේ කුමන වරණයේද?",
        "මුලතිව්, මන්නාරම, වවුනියාව සහ මොණරාගල", "කොළඹ, ගම්පහ, කළුතර සහ මහනුවර", "ගාල්ල, මාතර, කෑගල්ල සහ කුරුණෑගල", "මාතලේ, නුවරඑළිය, බදුල්ල සහ රත්නපුර",
        "මුලතිව් දිස්ත්‍රික්කයේ විශාල වන රක්ෂිත පැවතීම හා සීමිත නාගරීකරණය නිසා ජන ඝනත්වය ඉතා අවම අගයක පවතී."),
      q(t, "ශ්‍රී ලංකාවේ සමස්ත ජනගහනයෙන් වැඩිම ප්‍රතිශතයක් (77% ක් පමණ) ජීවත් වන 'ජනාවාස අංශය' කුමක්ද?",
        "ග්‍රාමීය අංශය (Rural Sector)", "නාගරික අංශය (Urban Sector)", "වතු අංශය (Estate Sector)", "වෙරළබඩ ධීවර අංශය (Coastal Sector)",
        "ශ්‍රී ලංකාවේ නිල නාගරික අංශයේ ~18% ක් ද වතු අංශයේ ~4.4% ක් ද වාසය කරති."),
      q(t, "ශ්‍රී ලංකාවේ 'වතු ජනාවාස' (Estate Settlements) වලට ආවේණික භූගෝලීය පිහිටීම හා නිවාස ව්‍යුහය කෙබඳුද?",
        "මධ්‍යම කඳුකරයේ හා තෙත් කලාපීය තේ හෝ රබර් වතු තුළ පිහිටි පේළි නිවාස හා නවීන ගම්මාන", "වියළි කලාපයේ පුරාණ වාරි වැව් බැමි ආශ්‍රිතව ගොනු වූ සාම්ප්‍රදායික ගම්ගොඩ ජනාවාස", "උතුරු මුහුදේ හුණුගල් දූපත් හා කලපු තීර ආශ්‍රිතව විසිරී ඇති ධීවර ජනාවාස", "මහාමාර්ග දෙපස වාණිජ වෙළඳසැල් හා රාජ්‍ය ආයතන වටා ඉදි වූ අධි ඝනත්ව නගර",
        "මෙම ජනාවාසවල පානීය ජලය, සෞඛ්‍ය හා ප්‍රවාහන යටිතල පහසුකම් වැඩිදියුණු කිරීම කෙරෙහි අවධානය යොමු කෙරේ."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයේ පුරාණ ග්‍රාමීය 'ගම්ගොඩ - වැව - කුඹුර' සැකැස්මේ පිහිටීම කුමක්ද?",
        "වැව් බැම්මට පහළින් කුඹුරු යායත්, ඉහළ උස් බිමේ ගංවතුරෙන් ආරක්ෂිතව නිවාස සහිත ගම්ගොඩත් පිහිටීම", "වැව් ජලාශය ඇතුළත කණු මත නිවාස ඉදිකර වැව් බැම්ම මත ප්‍රධාන වී ගොවිතැන සිදු කිරීම", "කඳු මුදුනේ උස් බිම්වල කුඹුරු වගා කර ගංවතුරට යටවන පහත් නිම්නයේ නිවාස ඉදිකිරීම", "මුහුදු වෙරළ තීරය අසල ලවණ ජලය රඳවන වැව් බැඳ ඒ වටා වාණිජ නගර පමණක් පිහිටුවීම",
        "මෙම සාම්ප්‍රදායික පාරිසරික සැලැස්ම මගින් ජලය, පස හා ප්‍රජා සෞඛ්‍යාරක්ෂාව සුරැකිණි."),
      q(t, "'ස්මාර්ට් නගර' (Smart Cities) සංකල්පයේ ප්‍රධාන නාගරික සැලසුම් අරමුණ කුමක්ද?",
        "තොරතුරු තාක්ෂණය හා හරිත බලශක්තිය යොදා ගනිමින් ප්‍රවාහනය, ජලය හා කසළ කාර්යක්ෂමව කළමනාකරණය කිරීම", "නගර මධ්‍යයේ ඇති සියලුම උද්‍යාන හා ගස් ඉවත් කර ඒ වෙනුවට අධිවේගී මාර්ග පමණක් ඉදිකිරීම", "පොදු බස් හා දුම්රිය ප්‍රවාහන සේවා සම්පූර්ණයෙන් නතර කර පෞද්ගලික වාහන පමණක් භාවිත කිරීම", "නගරයේ පරිපාලන හා සේවා කටයුතු සඳහා ඩිජිටල් තාක්ෂණය අතහැර කඩදාසි ලිපිගොනු පමණක් යොදා ගැනීම",
        "සිංගප්පූරුව, සෝල්, බාසිලෝනා හා ආම්ස්ටර්ඩෑම් ප්‍රමුඛ ස්මාර්ට් නගර සඳහා උදාහරණ වේ."),
      q(t, "එක්සත් ජාතීන්ගේ තිරසාර සංවර්ධන ඉලක්ක අතර 'SDG 11' මගින් ප්‍රධාන වශයෙන් අවධාරණය කරන්නේ කුමක්ද?",
        "නගර සහ මානව ජනාවාස සැමට ආරක්ෂිත, ඔරොත්තු දෙන සහ තිරසාර ස්ථාන බවට පත් කිරීම", "ගෝලීය කාර්මික නිෂ්පාදන වැඩි කිරීම සඳහා සියලුම ග්‍රාමීය ගොවි ගම්මාන මහා නගර බවට පත් කිරීම", "මහා නගර ආසන්නයේ ඉදිකිරීම් සඳහා ඉඩම් ලබා ගැනීමට ස්වාභාවික වනාන්තර හා තෙත් බිම් ඉවත් කිරීම", "වෙරළබඩ ජනාවාස ව්‍යාප්ත කිරීම සඳහා සාගර මතුපිට ජල මට්ටම කෘත්‍රිමව ඉහළ දැමීමට පියවර ගැනීම",
        "තිරසාර නාගරික සැලසුම්කරණය සඳහා පොදු ප්‍රවාහනය, හරිත අවකාශයන් හා ආරක්ෂිත නිවාස අත්‍යවශ්‍ය වේ."),
      q(t, "ශ්‍රී ලංකාව ඇතුළු බොහෝ රටවල ජාතික ජනගහන හා නිවාස සංගණනයක් සාමාන්‍යයෙන් පවත්වනු ලබන්නේ කොපමණ කලකට වරක්ද?",
        "සෑම වසර 10 කට වරක්", "සෑම මාස 6 කට වරක්", "සෑම වසර 50 කට වරක්", "සෑම සති 2 කට වරක්",
        "ජාතික සැලසුම්, පාසල්, රෝහල් හා මැතිවරණ කොට්ඨාස අවශ්‍යතා තීරණය කිරීමට සංගණන දත්ත අත්‍යවශ්‍ය වේ."),
      q(t, "ජන සංගණනයකදී පුද්ගලයෙකු ඔහුගේ ස්ථිර පදිංචි ස්ථානය අනුව නොව, සංගණන දින රාත්‍රියේ සිටින ස්ථානය අනුව ගණන් ගැනීම කුමක්ද?",
        "භෞතික පැවැත්ම පදනම් කරගත් සංගණන ක්‍රමය (De Facto)", "සාමාන්‍ය පදිංචිය පදනම් කරගත් සංගණන ක්‍රමය (De Jure)", "දෛනික රැකියා ස්ථානය පදනම් කරගත් ලේඛනගත කිරීමේ ක්‍රමය", "උපන් දිස්ත්‍රික්කය පදනම් කරගත් ජනගහන ගණනය කිරීමේ ක්‍රමය",
        "පුද්ගලයාගේ සාමාන්‍ය පදිංචි ස්ථානය අනුව ගණන් ගැනීම De Jure ක්‍රමය ලෙස හැඳින්වේ."),
      q(t, "රටක මුළු ජනගහන වෙනස්වීම ගණනය කිරීමේදී ස්වාභාවික වර්ධනයට අමතරව සැලකිල්ලට ගත යුතු අනෙක් සාධකය කුමක්ද?",
        "ශුද්ධ සංක්‍රමණය (ආගමනය සහ විගමනය අතර වෙනස)", "වාර්ෂික සාමාන්‍ය වර්ෂාපතනය සහ සුළං වේගය", "නිරිතදිග හා ඊසානදිග මෝසම් වැසි රටාවන්", "රට තුළ පවතින ඛනිජ සම්පත් හා බලශක්ති සංචිත",
        "ජනගහන වෙනස්වීම = (උපත් − මරණ) + (ආගමන − විගමන) යන සමීකරණයෙන් ගණනය කෙරේ."),
      q(t, "වෙනත් රටක සිට රට තුළට පැමිණීම 'ආගමනය' වන අතර තම රටෙන් පිටවී වෙනත් රටක පදිංචියට යාම හඳුන්වන්නේ කුමන නමින්ද?",
        "විගමනය (Emigration)", "නාගරීකරණය (Urbanization)", "විසරණය (Dispersion)", "සංකේන්ද්‍රණය (Concentration)",
        "ආගමන සංඛ්‍යාව විගමන සංඛ්‍යාවට වඩා වැඩි නම් ශුද්ධ සංක්‍රමණය ධන අගයක් ගනී."),
      q(t, "'බලහත්කාර සංක්‍රමණය' (Forced Migration) සඳහා නිවැරදි උදාහරණයක් දැක්වෙන වරණය කුමක්ද?",
        "යුද ගැටුම්, ජනවාර්ගික පීඩන හෝ දරුණු ආපදා නිසා ජනතාවට අකමැත්තෙන් නිජබිම් අතහැරීමට සිදුවීම", "උසස් විශ්වවිද්‍යාල අධ්‍යාපනය හා පර්යේෂණ අවස්ථා ලබා ගැනීම සඳහා ස්වේච්ඡාවෙන් විදේශගත වීම", "විවේක කාලය ගත කිරීම හා සංස්කෘතික ස්ථාන නැරඹීම සඳහා කෙටි කාලීන විනෝද සංචාරවල නිරත වීම", "රැකියාවෙන් විශ්‍රාම ගැනීමෙන් පසු සෞම්‍ය වෙරළබඩ නගරයක ස්ථිර පදිංචිය සඳහා කැමැත්තෙන් යාම",
        "සිය කැමැත්තෙන් රැකියා හෝ අධ්‍යාපනය සඳහා යාම ස්වේච්ඡා සංක්‍රමණය ලෙස හැඳින්වේ."),
      q(t, "නගරයක වාණිජ කලාපයේ සිට ප්‍රධාන මහාමාර්ග හා දුම්රිය මාර්ග ඔස්සේ කර්මාන්ත හා නේවාසික කලාප පිටතට විහිදෙන්නේ කෙසේද?",
        "ප්‍රවාහන මාර්ග දෙපස ආකර්ෂණය ඉහළ නිසා කර්මාන්ත හා නිවාස මාර්ග ඔස්සේ තීරු ලෙස පිටතට විහිදේ", "නගරයේ සියලුම කර්මාන්ත හා නිවාස මධ්‍යයේ එකම ගොඩනැගිලි සංකීර්ණයක පමණක් ගොනු වී පවතී", "ප්‍රවාහන මාර්ගවලින් දුරස්ථ වනාන්තර මැද කර්මාන්ත හා වාණිජ බැංකු සංකීර්ණ පිහිටුවනු ලැබේ", "ගංගා මෝයෙන් ඇතුළත ජලාශය මැද පමණක් නවීන නිවාස හා කර්මාන්තශාලා ඉදි කෙරේ",
        "ප්‍රවාහන මාර්ග දිගේ කර්මාන්ත හා විවිධ නේවාසික කලාප පිටතට විහිදෙන ආකාරය නගර ව්‍යාප්තියේදී දැකිය හැකිය."),
      q(t, "නූතන මහා නගරයක් තනි මධ්‍යස්ථානයක් වටා පමණක් නොව උප-මධ්‍යස්ථාන කිහිපයක් වටා වර්ධනය වන්නේ කුමන ආකාරයටද?",
        "වරාය, ගුවන්තොටුපළ, විශ්වවිද්‍යාල හා ව්‍යාපාර උද්‍යාන වැනි විශේෂිත කේන්ද්‍ර කිහිපයක් වටා වර්ධනය වීම", "එකම ප්‍රධාන වෙළඳ වීදියක් දිගේ පමණක් දෙපසට විහිදී පටු රේඛීය ජනාවාසයක් ලෙස වර්ධනය වීම", "කෘෂිකාර්මික වී ගොවිපළවල් මැද විසිරුණු තනි ගොවි නිවාස කිහිපයක් ලෙස පමණක් පැතිරී යාම", "වෙරළ තීරයේ ධීවර තොටුපළක් වටා පමණක් රැඳී රට අභ්‍යන්තරයට කිසිසේත් ව්‍යාප්ත නොවී පැවතීම",
        "නූතන මහා නගරවල වාණිජ, අධ්‍යාපනික හා කාර්මික කටයුතු සඳහා විවිධ උප-මධ්‍යස්ථාන බිහි වේ."),
      q(t, "නගර මධ්‍යයේ සිට නගර සීමාව දෙසට දුර වැඩි වන විට ඉඩම් වටිනාකම හා භූමි පරිභෝජනය වෙනස් වන්නේ කෙසේද?",
        "ඉඩම් මිල හා ගොඩනැගිලි ඝනත්වය අඩු වන අතර වාණිජ කලාපය සිට නිවාස හා ගොවි බිම් දක්වා වෙනස් වේ", "ඉඩම් මිල හා ගොඩනැගිලි උස නගර මධ්‍යයේ සිට පිටතට යත්ම අඛණ්ඩව ඉහළ මට්ටමකට වැඩි වේ", "නගර මධ්‍යයේ විශාල තේ හා වී වගා බිම් පිහිටන අතර පිටත තදාසන්නයේ බැංකු සංකීර්ණ පිහිටයි", "මුළු නගරය පුරාම ඉඩම් කුලිය හා ගොඩනැගිලි ඝනත්වය එකම සමාන අගයක නොවෙනස්ව පවතී",
        "ප්‍රවේශ්‍යතාව වැඩිම නගර මධ්‍යය සඳහා වාණිජ ආයතන වැඩිම මිලක් ගෙවීමට සූදානම් වේ."),
      q(t, "පුද්ගලයෙකු වෙනත් ප්‍රදේශයකට සංක්‍රමණය වීමේදී මුහුණ දීමට සිදුවන 'අතරමැදි බාධක' ලෙස සැලකෙන්නේ මොනවාද?",
        "ගමන් දුර, සංක්‍රමණ වියදම, වීසා නීති, කඳු හා සාගර වැනි භෞතික බාධක සහ භාෂා වෙනස්කම්", "ආකර්ෂණීය ඉහළ වැටුප්, ස්ථිර රැකියා අවස්ථා සහ වෘත්තීය උසස්වීම් ලැබීමේ පහසුකම්", "දරුවන්ට ලැබෙන උසස් පාසල් අධ්‍යාපනය සහ නවීන රෝහල් සෞඛ්‍ය සේවා පහසුකම් පැවතීම", "සාමකාමී පරිසරය, ස්ථාවර දේශපාලන වාතාවරණය සහ ආරක්ෂිත නේවාසික පහසුකම් තිබීම",
        "තල්ලු හා ඇදගැනීමේ සාධක පැවතියද සංක්‍රමණිකයන්ට මෙම බාධක ජය ගැනීමට සිදුවේ."),
      q(t, "ස්ථාන දෙකක් අතර සංක්‍රමණ හා වෙළඳ ගමනාගමනය වැඩි වශයෙන් සිදු වන්නේ කුමන භූගෝලීය තත්ත්ව යටතේද?",
        "ස්ථාන දෙකේ ජනගහනය විශාල වන තරමට සහ ඒවා අතර භූගෝලීය දුර අඩු වන තරමට", "ස්ථාන දෙක අතර භූගෝලීය දුර ප්‍රමාණය ඉතා විශාල වී ප්‍රවාහන මාර්ග අවම වන තරමට", "ස්ථාන දෙකේම ජනගහනය ඉතා කුඩා වී ග්‍රාමීය හුදකලා බව ඉහළ මට්ටමක පවතින තරමට", "ස්ථාන දෙක අතර සාගර කලාපයක් හා උස් කඳු වැටියක් පිහිටා ගමනාගමනය සීමා වන තරමට",
        "නගරවල ජනගහන විශාලත්වය ආකර්ෂණය වැඩි කරන අතර දුර ප්‍රමාණය ගමනාගමනය අඩු කරයි."),
      q(t, "විශාල නගරයක් වටා 'හරිත තීරය' (Green Belt) නමින් වනාන්තර හා කෘෂි ඉඩම් වළල්ලක් තැබීමේ ප්‍රධාන අරමුණ කුමක්ද?",
        "ගොඩනැගිලි ඉදිකිරීම සීමා කර පාලනයකින් තොරව නගරය පිටතට පැතිරීම වැළැක්වීම", "නගරය අවට ඇති සියලුම ගස් කපා දමා නව කර්මාන්ත උද්‍යාන ඉදිකිරීම සඳහා ඉඩම් සැකසීම", "නගරය වටා උස් කොන්ක්‍රීට් තාප්පයක් බැඳ ග්‍රාමීය ජනතාව නගරයට පැමිණීම සම්පූර්ණයෙන් වැළැක්වීම", "නගරයේ පිහිටි සියලුම වැව් හා තෙත් බිම් පස් දමා ගොඩකර නිවාස සංකීර්ණ ඉදිකිරීම",
        "ලන්ඩන් හා ඔටාවා වැනි නගර වටා නාගරික පැතිරීම පාලනය කිරීමට හරිත තීර ප්‍රතිපත්තිය සාර්ථකව යොදා ගෙන ඇත."),
      q(t, "නගරය තුළ අතහැර දමා ඇති පැරණි කාර්මික භූමි නැවත සංවර්ධනය කිරීම අලුතින් වනාන්තර හෙළි කිරීමට වඩා පරිසර හිතකාමී වන්නේ ඇයි?",
        "ස්වාභාවික වනාන්තර හා කෘෂි ඉඩම් විනාශ නොකර නගරයේ පවතින යටිතල පහසුකම් ඵලදායීව යොදා ගන්නා බැවින්", "කොළ පැහැති තීන්ත ආලේප කළ ගොඩනැගිලි ඉදි කරන නිසා නාගරික උෂ්ණත්වය ක්ෂණිකව පහත වැටෙන බැවින්", "කාන්තාර හා හිම කඳු ප්‍රදේශවල නව නගර ඉදි කර මුහුදු වෙරළබඩ ඉඩම් ඉතිරි කර ගන්නා බැවින්", "ගංගා ඉවුරු හා කලපු ගොඩකර වාණිජ ගොඩනැගිලි තැනීමෙන් නාගරික ජල බැස්ම පහසු කරන බැවින්",
        "පැරණි භූමි ප්‍රතිසංවර්ධනය නගර මධ්‍යය පණ ගන්වමින් නාගරික පැතිරීම අවම කරයි."),
      q(t, "ජපානයේ වර්තමාන ජනගහනය තුළ ළමා අනුපාතය අඩු වී වැඩිහිටි අනුපාතය අධික ලෙස ඉහළ යාමට බලපෑ ප්‍රධාන සාධක මොනවාද?",
        "විවාහ වන වයස පමා වීම, අඩු දරු උපත් සංඛ්‍යාව සහ ඉතා ඉහළ ආයු අපේක්ෂාව", "බෝවන වසංගත රෝග පැතිරී යාම නිසා තරුණ පරපුර අකාලයේ මියයාම සහ සෞඛ්‍ය සේවා බිඳ වැටීම", "කෘෂිකාර්මික රැකියා පමණක් පැවතීම නිසා පවුල් ආදායම අඩු වී ආහාර සැපයුම හිඟ වීම", "වයස අවුරුදු 18 ට අඩු සියලුම ළමුන් අනිවාර්යයෙන්ම වෙනත් රටවල පදිංචියට යැවීමේ නීතිය",
        "ජපානයේ ජනගහනයෙන් 29% කට වඩා වයස අවුරුදු 65 ඉක්මවූ වැඩිහිටියන් වේ."),
      q(t, "කාන්තා අධ්‍යාපනය හා රැකියා නියුක්තිය ඉහළ යාම ජනගහන වර්ධන වේගය කෙරෙහි සෘජුවම බලපාන්නේ කෙසේද?",
        "විවාහ වන වයස ඉහළ ගොස් දැනුවත් පවුල් සැලසුම් තීරණ ගැනීම නිසා උපත් අනුපාතය පහත වැටීම", "කාන්තා සාක්ෂරතාවය වැඩි වීමත් සමඟ සෑම පවුලකම සාමාන්‍ය දරු උපත් සංඛ්‍යාව දෙගුණයකින් ඉහළ යාම", "රෝහල් ප්‍රසව පහසුකම් අඩු වී ළදරු මරණ අනුපාතය නැවතත් ඉහළ මට්ටමකට පැමිණීම", "කාන්තාවන්ගේ ආයු අපේක්ෂාව කෙටි වී වැඩිහිටි ජනගහන ප්‍රතිශතය සීඝ්‍රයෙන් අඩු වී යාම",
        "ශ්‍රී ලංකාව කාන්තා අධ්‍යාපනය ඉහළ නැංවීමෙන් ඉක්මනින් අඩු උපත් අනුපාතයකට ළඟා වූ හොඳම උදාහරණයකි."),
      q(t, "වියළි හෝ හුණුගල් ප්‍රදේශයක උල්පතක්, ක්ෂේම භූමියක් හෝ ගංගාවක් අසල පිහිටුවන ජනාවාසය හඳුන්වනු ලබන්නේ කුමන නමින්ද?",
        "ජල මූලාශ්‍ර ස්ථාන ජනාවාසය (Wet-Point Site)", "වියළි ගොඩැලි ස්ථාන ජනාවාසය (Dry-Point Site)", "ආරක්ෂක කඳු මුදුන් ජනාවාසය (Defensive Site)", "වරාය හා වෙළඳ මංසන්ධි ජනාවාසය (Port Site)",
        "ගංවතුරෙන් හා වගුරුවලින් බේරී උස් ගොඩැල්ලක පිහිටුවන ජනාවාස වියළි ස්ථාන ජනාවාස නම් වේ."),
      q(t, "සතුරු ආක්‍රමණවලින් ආරක්ෂා වීම සඳහා අතීතයේදී උස් පර්වත හෝ ගංගාවකින් තුන් පැත්තක් වටවූ ස්ථානවල බිහිවූ ජනාවාසවලට උදාහරණ මොනවාද?",
        "සීගිරිය, මහනුවර, ඇතැන්ස්හි ඇක්‍රොපොලිස් සහ එඩින්බරෝ", "මැදපෙරදිග කාන්තාර මධ්‍යයේ ඉදි කළ නවීන තෙල් කැණීම් කඳවුරු", "පැතලි ගංගා ඩෙල්ටා තැනිතලා මධ්‍යයේ විවෘතව පිහිටි වී ගොවි ගම්මාන", "වෙරළබඩ සෘජු වැලි කඳු තීරය මත ඉදි කළ සෘතුමය ධීවර වාඩි",
        "භෞතික භූ විෂමතාව සතුරු ආක්‍රමණ වැළැක්වීමේ ස්වාභාවික ආරක්ෂක පවුරක් ලෙස යොදා ගැනිණි."),
      q(t, "ගංගාවක් පටු වන ස්ථානයක පාලම් හෝ තොටුපළ ආශ්‍රිතව ආරම්භ වී පසුව මහා නගර බවට පත්වූ නගර යුගලය කුමක්ද?",
        "ලන්ඩන් (තේම්ස් ගඟ හරහා) සහ පැරිස් (සේන් ගඟ හරහා)", "මක්කම (කාන්තාර නිම්නය) සහ ජෙරුසලම (කඳු සානුව)", "සිංගප්පූරුව (මුහුදු දූපත) සහ මාලේ (කොරල් දූපත)", "නුවරඑළිය (කඳු සානුව) සහ බණ්ඩාරවෙල (කඳු වැටිය)",
        "ගඟක් පහසුවෙන් තරණය කළ හැකි ස්ථානයක වෙළඳ මාර්ග හමුවීම නිසා ජනාවාස වේගයෙන් දියුණු වේ."),
      q(t, "ජනගහනයේ 'සක්‍රීය ශ්‍රම බලකාය' ලෙස ජාත්‍යන්තරව ගණන් ගනු ලබන්නේ කුමන වයස් කාණ්ඩයද?",
        "වයස අවුරුදු 15 සිට 64 දක්වා වැඩ කරන වයසේ ජනගහනය", "වයස අවුරුදු 0 සිට 14 දක්වා පාසල් හා ළමා ජනගහනය", "වයස අවුරුදු 65 ට වැඩි විශ්‍රාමික වැඩිහිටි ජනගහනය", "වයස අවුරුදු 5 සිට 12 දක්වා ප්‍රාථමික අධ්‍යාපන වයස් කාණ්ඩය",
        "යැපුම් ජනගහනයේ බර දරා ආර්ථික නිෂ්පාදනය සිදු කරනු ලබන්නේ මෙම වයස් කාණ්ඩය විසිනි."),
      q(t, "විදේශගත ශ්‍රමිකයන් විසින් මව් රටට එවන ප්‍රේෂණ (Remittances) සංවර්ධනය වෙමින් පවතින රටවලට වැදගත් වන්නේ ඇයි?",
        "රටට විදේශ විනිමය ලැබීම, පවුල් ආදායම ඉහළ යාම සහ අධ්‍යාපන හා සෞඛ්‍ය පහසුකම් වැඩිදියුණු වීම", "වනාන්තර හෙළි කර කෘෂි ඉඩම් ප්‍රමාණය සීඝ්‍රයෙන් වැඩි කිරීමට ඍජුවම දායක වන බැවින්", "රටේ සියලුම ජාත්‍යන්තර ආනයන හා අපනයන වෙළඳ කටයුතු සම්පූර්ණයෙන්ම නතර කළ හැකි බැවින්", "රටේ මුළු ජනගහනය හා උපත් අනුපාතය කඩිනමින් අඩු කර ගැනීමට එකම මාර්ගය වන බැවින්",
        "ශ්‍රී ලංකාව, පිලිපීනය, නේපාලය හා ඉන්දියාව වැනි රටවල විදේශ ප්‍රේෂණ ප්‍රධාන විදේශ විනිමය මාර්ගයකි."),
      q(t, "නාගරික ආර්ථිකයේ 'අවිධිමත් අංශය' (Informal Sector) යන්නෙන් හඳුන්වනු ලබන්නේ කුමන රැකියා ක්ෂේත්‍රයද?",
        "වීදි වෙළඳාම, දෛනික කුලී වැඩ හා කුඩා ගෘහ කර්මාන්ත වැනි ස්ථිර වැටුප් හෝ විශ්‍රාම ආරක්ෂණය අඩු රැකියා", "මහ බැංකුව හා රාජ්‍ය භාණ්ඩාගාරය යටතේ සේවය කරන ස්ථිර විධායක පරිපාලන රැකියා", "ජාත්‍යන්තර බහුජාතික සමාගම්වල ඉහළ වැටුප් ලබන ඉංජිනේරු හා කළමනාකරණ රැකියා", "රජයේ විශ්වවිද්‍යාල පද්ධතියේ හා පර්යේෂණ ආයතනවල ස්ථිර මහාචාර්ය හා විද්‍යාඥ රැකියා",
        "සංවර්ධනය වෙමින් පවතින රටවල නාගරික ශ්‍රම බලකායෙන් සැලකිය යුතු පිරිසක් අවිධිමත් අංශයේ නියැලී සිටී."),
      q(t, "ශ්‍රී ලංකාවේ බස්නාහිර පළාතේ නාගරික සැලසුම් ව්‍යාපෘති මගින් විසඳීමට අපේක්ෂා කළ ප්‍රධාන ගැටලු මොනවාද?",
        "මාර්ග තදබදය, නාගරික ගංවතුර, කසළ කළමනාකරණය, නිවාස හිඟය සහ සැලසුම් කළ ව්‍යාපාර කලාප ඇති කිරීම", "රටේ ප්‍රධාන ආහාර බෝගය වන තෙත් කලාපීය වී ගොවිතැන සම්පූර්ණයෙන් නතර කිරීම", "කොළඹ හා ගාල්ල ප්‍රධාන වරායන් සියල්ල වසා දමා නාවික වෙළඳාම අවසන් කිරීම", "මධ්‍යම කඳුකරයේ පිහිටි සියලුම තේ වතු ඉවත් කර ඒවා නේවාසික නගර බවට පත් කිරීම",
        "කොළඹ, ගම්පහ හා කළුතර දිස්ත්‍රික්ක ඒකාබද්ධ මහා නාගරික කලාපයක් ලෙස සැලසුම් කිරීම මෙහි අරමුණ විය."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයේ ක්‍රියාත්මක කළ 'ගොවි ජනපද ව්‍යාපාර' (මින්නේරිය, ගල් ඔය, මහවැලි) ඇති කළ ප්‍රධාන ජනගහන බලපෑම කුමක්ද?",
        "ජනාකීර්ණ තෙත් කලාපයේ ජනතාව වියළි කලාපයේ නව වාරි ජනාවාසවල පදිංචි කර ජනගහන ව්‍යාප්තිය තුලනය කිරීම", "වියළි කලාපයේ වෙසෙන සියලුම ගොවි පවුල් රැකියා සඳහා විදේශ රටවල පදිංචියට යැවීම", "වියළි කලාපයේ ග්‍රාමීය ජනතාව සියල්ල කොළඹ නගර මධ්‍යයට ගෙනැවිත් පදිංචි කරවීම", "පුරාණ වාරි වැව් සියල්ල වසා දමා වියළි කලාපය කාර්මික කලාපයක් බවට පමණක් පත් කිරීම",
        "ගොවි ජනපද ව්‍යාපාර වියළි කලාපයේ නව නගර හා ශක්තිමත් කෘෂි ආර්ථිකයක් ගොඩනැගීය."),
      q(t, "'ජනගහන පිපිරුම' (Population Explosion) යන යෙදුම භාවිත කරනු ලබන්නේ 20 වන සියවසේ කුමන සංසිද්ධිය විස්තර කිරීමටද?",
        "වෛද්‍ය විද්‍යාවේ හා ආහාර සැපයුමේ දියුණුව නිසා ලෝක ජනගහනය ඉතා කෙටි කලකින් බිලියන 2 සිට බිලියන 8 ඉක්මවීම", "සක්‍රීය ගිනිකඳු එකවර පිපිරී යාමෙන් නගර රැසක් අළු යට වැළලී යාමේ භූ විද්‍යාත්මක සිදුවීම", "ලෝක යුද්ධ හේතුවෙන් ප්‍රධාන කාර්මික නගර විශාල ප්‍රමාණයක් විනාශ වී ජනගහනය අඩුවීම", "ධ්‍රැවීය ග්ලැසියර දියවීම නිසා වෙරළබඩ ජනාවාස මුහුදු ජලයෙන් යටවී යාමේ සංසිද්ධිය",
        "1927 දී බිලියන 2 ක් වූ ලෝක ජනගහනය 2022 වන විට බිලියන 8 ඉක්මවීය."),
      q(t, "එක්සත් ජාතීන්ගේ ජනගහන පුරෝකථන අනුව ඉදිරි දශක කිහිපයේදී වේගවත්ම ජනගහන වර්ධනයක් පෙන්වන මහාද්වීපය කුමක්ද?",
        "අප්‍රිකාව (විශේෂයෙන් උප-සහරා අප්‍රිකානු කලාපය)", "යුරෝපය (බටහිර හා නැගෙනහිර යුරෝපීය කලාපය)", "උතුරු ඇමරිකාව (කැනඩාව හා ඇමරිකා එක්සත් ජනපදය)", "ඕස්ට්‍රේලියාව හා නවසීලන්තය (ඕෂනියා කලාපය)",
        "යුරෝපයේ හා නැගෙනහිර ආසියාවේ ජනගහනය හැකිලෙන අතර අප්‍රිකාවේ තරුණ ජනගහනය වේගයෙන් ඉහළ යයි."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවල දක්නට ලැබෙන 'අධි-නාගරීකරණය' (Over-urbanization) හඳුනා ගන්නේ කෙසේද?",
        "නගරයේ රැකියා හා යටිතල පහසුකම් වර්ධනය වන වේගයට වඩා වැඩි වේගයකින් ග්‍රාමීය දිළිඳු ජනතාව නගරයට පැමිණීම", "නගරයේ සියලුම වැසියන්ට පරිසර හිතකාමී හරිත උද්‍යාන හා අධිවේගී දුම්රිය පහසුකම් හිමිවීම", "නාගරික නිවාස සියල්ල නවීන සුඛෝපභෝගී මහල් නිවාස බවට පත්වී පැල්පත් සම්පූර්ණයෙන් නැතිවීම", "නගරයේ වෙසෙන තරුණ ජනතාව විශාල වශයෙන් ග්‍රාමීය කෘෂි ගම්මාන වෙත පදිංචියට යාම",
        "මෙහිදී නගර ප්‍රමාණයෙන් විශාල වුවද සැබෑ ජීවන තත්ත්වය ඊට සමානුපාතිකව ඉහළ නොයයි."),
      q(t, "වෙරළබඩ නගරවල තදබදය අඩු කර රට අභ්‍යන්තරය සංවර්ධනය කිරීම සඳහා 20 වන සියවසේදී ඉදි කළ 'සැලසුම් කළ අගනුවරවල්' මොනවාද?",
        "බ්‍රසීලියා (බ්‍රසීලය), ඉස්ලාමාබාද් (පකිස්ථානය) සහ කැන්බරා (ඕස්ට්‍රේලියාව)", "ලන්ඩන් (එක්සත් රාජධානිය), පැරිස් (ප්‍රංශය) සහ බර්ලින් (ජර්මනිය)", "ටෝකියෝ (ජපානය), බීජිං (චීනය) සහ සෝල් (දකුණු කොරියාව)", "රෝමය (ඉතාලිය), ඇතැන්ස් (ග්‍රීසිය) සහ මැඩ්රිඩ් (ස්පාඤ්ඤය)",
        "රියෝ ද ජැනයිරෝ නගරයේ සිට රට අභ්‍යන්තරයේ බ්‍රසීලියා වෙත අගනුවර ගෙන යාම මීට ප්‍රසිද්ධ නිදසුනකි."),
      q(t, "ශ්‍රී ලංකාවේ 'ශ්‍රී ජයවර්ධනපුර කෝට්ටේ' පරිපාලන අගනුවර ලෙස තෝරා ගැනීමේ ප්‍රධාන භූගෝලීය අරමුණ කුමක්ද?",
        "කොළඹ වාණිජ නගරයේ තදබදය අඩු කර පරිපාලන හා පාර්ලිමේන්තු ආයතන තදාසන්න කලාපයකට විමධ්‍යගත කිරීම", "කොළඹ සාගර වරාය සම්පූර්ණයෙන්ම රට අභ්‍යන්තරයට ගෙන ගොස් නැව් ගමනාගමනය නැවැත්වීම", "කොළඹ දිස්ත්‍රික්කයේ සියලුම වාණිජ ගොඩනැගිලි ඉවත් කර උඩරට තේ වගාව ආරම්භ කිරීම", "මධ්‍යම කඳුකරයේ පිහිටි ජාත්‍යන්තර ගුවන්තොටුපළක් නව පරිපාලන අගනුවර මධ්‍යයට ගෙන ඒම",
        "කොළඹ ශ්‍රී ලංකාවේ වාණිජ අගනුවර ලෙසත්, ශ්‍රී ජයවර්ධනපුර කෝට්ටේ පරිපාලන අගනුවර ලෙසත් ක්‍රියා කරයි."),
      q(t, "ජනගහන ව්‍යාප්තිය සහ ජන ඝනත්වය දැක්වීම සඳහා තේමාත්මක සිතියම්කරණයේදී බහුලව භාවිත කරන සිතියම් වර්ග දෙක කුමක්ද?",
        "තිත් සිතියම් (Dot Maps) සහ චෝරොප්ලෙත් වර්ණ සිතියම් (Choropleth Maps)", "සමෝච්ච රේඛා සිතියම් (Contour Maps) සහ භූ ලක්ෂණ සිතියම්", "සාගර ගැඹුරු රේඛා සිතියම් (Bathymetric Maps) සහ කොරල් සිතියම්", "තාරකා මණ්ඩල සිතියම් (Star Charts) සහ චන්ද්‍ර භූ ලක්ෂණ සිතියම්",
        "තිත් සිතියම් මගින් ගංගා නිම්න හා නගරවල ජනතාව රැස් වී සිටින ආකාරය පැහැදිලිව පෙන්වයි."),
      q(t, "රටක ජාතික ජන සංගණනයකට අමතරව උප්පැන්න, මරණ හා විවාහ ලියාපදිංචි කිරීමේ පද්ධති වැදගත් වන්නේ ඇයි?",
        "සෑම වසරකම සිදුවන සජීවී උපත්, මරණ හා විවාහ සංඛ්‍යාව අඛණ්ඩව නිවැරදිව වාර්තා කර ගැනීමට හැකි බැවින්", "කලාපයේ වාර්ෂික වර්ෂාපතනය, උෂ්ණත්වය හා සුළං වේගය දිනපතා මැන වාර්තා කර ගැනීමට හැකි බැවින්", "රට තුළ සිදුවන භූමිකම්පා හා ගිනිකඳු පිපිරීම් පිළිබඳව කල්තියා අනතුරු ඇඟවීමට හැකි බැවින්", "ගොවීන්ගේ වී හා තේ අස්වැන්න පිළිබඳ වාර්ෂික අපනයන සංඛ්‍යාලේඛන ගණනය කිරීමට හැකි බැවින්",
        "වසර 10 කට වරක් කෙරෙන සංගණනයට අමතරව වාර්ෂික උපත් හා මරණ අනුපාත ගණනය කිරීමට මෙම දත්ත යොදා ගනී."),
      q(t, "1900 වසරේ සිට අද දක්වා ගෝලීය මානව 'ආයු අපේක්ෂාව' වෙනස් වී ඇති ආකාරය නිවැරදිව දැක්වෙන්නේ කෙසේද?",
        "ලෝක සාමාන්‍ය ආයු අපේක්ෂාව වසර 32 ක පමණ සිට වසර 73 ක් දක්වා දෙගුණයකටත් වඩා ඉහළ ගොස් ඇත", "කාර්මික දූෂණය හේතුවෙන් ලෝක සාමාන්‍ය ආයු අපේක්ෂාව වසර 60 සිට වසර 30 දක්වා අඩු වී ඇත", "වෛද්‍ය විද්‍යාව දියුණු වුවද සියවසක් පුරා ගෝලීය සාමාන්‍ය ආයු අපේක්ෂාව කිසිසේත් වෙනස් වී නොමැත", "වර්තමානයේ ලෝකයේ සෑම රටකම සාමාන්‍ය මානව ආයු අපේක්ෂාව වසර 150 ක් දක්වා ඉහළ ගොස් ඇත",
        "ප්‍රතිජීවක ඖෂධ, එන්නත්, පිරිසිදු ජලය හා ළදරු සෞඛ්‍ය සේවා මෙම විප්ලවීය දියුණුවට හේතු විය."),
      q(t, "අතීතයේ සිට සංවර්ධනය වෙමින් පවතින ග්‍රාමීය සමාජවල විශාල පවුල් අපේක්ෂා කිරීමට බලපෑ සමාජ-ආර්ථික හේතු මොනවාද?",
        "ගොවිපළ ශ්‍රමය සඳහා දරුවන්ගේ සහාය ලැබීම, ළදරු මරණ බහුල වීම හා මහලු වියේ රැකවරණය අපේක්ෂා කිරීම", "මහා නගරවල විනෝද සංචාර යාම සඳහා විශාල පවුල් කණ්ඩායමක් සිටීමේ සමාජ අවශ්‍යතාව පැවතීම", "නාගරික ප්‍රදේශවල හිස්ව පැවති විශාල මහල් නිවාස සංකීර්ණ ජනතාවගෙන් පිරවීමේ රාජ්‍ය නියමය", "රජය මගින් කුඩා පවුල් පවත්වාගෙන යාම නීතියෙන් තහනම් කර විශාල පවුල්වලට බල කිරීම",
        "සෞඛ්‍ය පහසුකම් හා සමාජ ආරක්ෂණ ක්‍රම දියුණු වූ පසු දෙමාපියන් කුඩා පවුල් කෙරෙහි යොමු වේ."),
      q(t, "'නාගරික භූමි පරිභෝජන ගැටුම්' ඇතිවීමට ප්‍රධාන උදාහරණයක් වන්නේ කුමන සිදුවීමද?",
        "නේවාසික ප්‍රදේශ අසල කර්මාන්තශාලා හෝ කසළ අංගණ පිහිටුවීමේදී ශබ්ද හා වායු දූෂණයට විරෝධතා මතුවීම", "ග්‍රාමීය කුඹුරු යායවල කන්න දෙකේම සාම්ප්‍රදායික වී ගොවිතැන හා එළවළු වගාව සිදු කිරීම", "පාසල් හා විශ්වවිද්‍යාල පරිශ්‍ර අසල පොදු පුස්තකාල හා පොත්හල් ඉදි කර සේවා සැපයීම", "නගරයේ පොදු උද්‍යාන හා මහාමාර්ග දෙපස සෙවණ දෙන දේශීය ගස් වර්ග සිටුවීම",
        "ජනතාව පොදු පහසුකම් අවශ්‍ය බව පිළිගත්තද තම නිවස අසල අප්‍රසන්න පහසුකම් ඉදිකිරීමට විරුද්ධ වේ."),
      q(t, "'ගම හා නගරය අතර අන්තර් රඳා පැවැත්ම' නිවැරදිව විස්තර කරන්නේ කුමන ප්‍රකාශයද?",
        "ගම නගරයට ආහාර, අමුද්‍රව්‍ය හා ශ්‍රමය සපයන අතර නගරය ගමට නිෂ්පාදිත භාණ්ඩ, බැංකු හා උසස් සේවා සපයයි", "ග්‍රාමීය හා නාගරික ප්‍රදේශ එකිනෙකින් සම්පූර්ණයෙන්ම ස්වාධීන වන අතර කිසිදු ආර්ථික සබඳතාවක් නොපවත්වයි", "නගරය විසින් ගමට සියලුම සහල් හා එළවළු සපයන අතර ගම විසින් නගරයට බැංකු සේවා සපයයි", "ග්‍රාමීය ප්‍රදේශ නගරයට ගුවන් යානා හා බහුජාතික මූල්‍ය සේවා සපයන අතර නගරය ගමට දර සපයයි",
        "සමබර ප්‍රාදේශීය සංවර්ධනයක් සඳහා ග්‍රාමීය-නාගරික ප්‍රවාහන හා ආර්ථික සබඳතා ශක්තිමත් විය යුතුය."),
      q(t, "ජනාවාසයක් 'තාරකා හැඩැති' (Radial / Star-like) රටාවක් ගන්නේ කවර භූගෝලීය ස්ථානයකදීද?",
        "මාර්ග කිහිපයක් එක් මධ්‍යම හන්දියකට හමුවන ස්ථානයක සෑම මාර්ගයක් දිගේම නිවාස විහිදෙන විට", "සෘජුකෝණාස්‍රාකාර සමතලා මුහුදු වෙරළ තීරයක් දිගේ ධීවර නිවාස පේළියක් පමණක් පිහිටන විට", "තනි ගංගා ඉවුරක් දිගේ දෙපසට විහිදෙන සෘජු පටු නිම්න ජනාවාසයක් පිහිටන විට", "විශාල හුදකලා ගොවිපළවල් මැද නිවාස එකිනෙකින් කිලෝමීටර ගණනක් දුරින් පිහිටන විට",
        "බොහෝ වෙළඳ හා ප්‍රවාහන මංසන්ධි නගර මෙවැනි තාරකා හැඩැති ව්‍යාප්තියක් පෙන්නුම් කරයි."),
      q(t, "ලොව පුරා විශාල නගර බොහොමයක් වෙරළබඩ කලාපවල පිහිටා තිබීමට බලපෑ ප්‍රධාන සාධක මොනවාද?",
        "සාගර ප්‍රවාහනය හා වරාය වෙළඳාම, ධීවර කර්මාන්තය, සෞම්‍ය දේශගුණය සහ සංචාරක ආකර්ෂණය", "වෙරළබඩ කලාපවල වසර පුරා අධික හිම පතනයක් පැවතීම නිසා ජල සැපයුම පහසු වීම", "සාගරය අසල වැලි කාන්තාර මැද කෘෂිකර්මය සඳහා ඉතා සාරවත් ගිනිකඳු පසක් පැවතීම", "මුහුදු ජලය ලවණ රහිත මිරිදිය ජලය වන බැවින් පිරිපහදු නොකර සෘජුවම පානයට ගත හැකි වීම",
        "නිව්යෝක්, ටෝකියෝ, ෂැංහයි, මුම්බායි හා කොළඹ වැනි නගර වෙරළබඩ නාගරීකරණයට සාක්ෂි දරයි."),
      q(t, "'මාතෘ මරණ අනුපාතය' රටක සමාජ සංවර්ධන මට්ටම පෙන්වන වැදගත් දර්ශකයක් වන්නේ ඇයි?",
        "ගර්භණී හා ප්‍රසව සේවාවන්හි ගුණාත්මකභාවය, රෝහල් ප්‍රවේශ්‍යතාව සහ කාන්තා සෞඛ්‍යය ඉන් පිළිබිඹු වන බැවින්", "රටේ නිෂ්පාදන කර්මාන්තශාලා සංඛ්‍යාව සහ කාර්මික අපනයන ආදායම එමගින් මනිනු ලබන බැවින්", "රටේ පිහිටි ප්‍රධාන වාරි ජලාශවල වාර්ෂික වර්ෂාපතන මට්ටම එමගින් පෙන්නුම් කරන බැවින්", "ජාතික මහාමාර්ග හා දුම්රිය ජාලයේ මුළු දිග ප්‍රමාණය එමගින් ගණනය කරන බැවින්",
        "ශ්‍රී ලංකාව දකුණු ආසියාවේ අඩුම මාතෘ හා ළදරු මරණ අනුපාතයක් වාර්තා කරන රටවලින් එකකි."),
      q(t, "'සාක්ෂරතා අනුපාතය' ඉහළ මට්ටමක පැවතීම රටක ජනගහනයේ ගුණාත්මකභාවය කෙරෙහි බලපාන්නේ කෙසේද?",
        "නිපුණ ශ්‍රම බලකායක් බිහිවීම, සෞඛ්‍ය දැනුවත්භාවය වැඩිවීම, ඵලදායිතාව හා දැනුවත් පවුල් සැලසුම් ඇතිවීම", "කෘෂිකාර්මික නිෂ්පාදනය සම්පූර්ණයෙන්ම අවසන් වී ආහාර ආනයනය මත පමණක් යැපීමට සිදුවීම", "ජනගහනය අතර බෝවන රෝග පැතිරීම වැඩි වී සාමාන්‍ය ආයු අපේක්ෂාව පහත වැටීම", "ජනගහනයේ රැකියා ව්‍යුහයට හෝ ආර්ථික සංවර්ධනයට එමගින් කිසිදු බලපෑමක් සිදු නොවීම",
        "ශ්‍රී ලංකාවේ සාක්ෂරතා අනුපාතය 92% ඉක්මවන ඉහළ මට්ටමක පවතී."),
      q(t, "නගරවල 'පැල්පත් හා අඩු පහසුකම් ජනාවාස පුනරුත්ථාපනය' සඳහා වඩාත් තිරසාර ප්‍රවේශය කුමක්ද?",
        "පිරිසිදු ජලය, සනීපාරක්ෂාව, විදුලිය, ඉඩම් අයිතිය සහ ආරක්ෂිත නිවාස පහසුකම් ප්‍රජාවට ලබා දීම", "පදිංචිකරුවන්ට කිසිදු විකල්ප නිවාසයක් නොදී සියලුම නිවාස යන්ත්‍ර මගින් කඩා ඉවත් කිරීම", "එම නාගරික පදිංචිකරුවන් සියලු දෙනා කිසිදු පහසුකමක් නොමැති වියළි කාන්තාර පෙදෙස්වලට පිටත් කිරීම", "නගරයේ පැල්පත් පෙදෙස්වලට පිවිසෙන සියලුම මාර්ග හා ජල සැපයුම් නළ සම්පූර්ණයෙන්ම වසා දැමීම",
        "ප්‍රජා සහභාගීත්වයෙන් යුත් නිවාස සංවර්ධන ව්‍යාපෘති නාගරික දිළිඳුකම අඩු කිරීමට උපකාරී වේ."),
      q(t, "නගර ඒවායේ 'ප්‍රධාන කාර්යයන්' අනුව අධ්‍යාපන නගර, ආගමික නගර හා කාර්මික නගර ලෙස වර්ග කරන්නේ කුමන පදනම මතද?",
        "නගරයේ ආර්ථිකයට හා සමාජයට එම නගරය ඉටු කරන ප්‍රමුඛතම ක්‍රියාකාරී සේවාව අනුව", "නගරයේ පිහිටා ඇති සාප්පු සංකීර්ණවල උස හා විශාලත්වය පදනම් කරගත් ඉදිකිරීම් අනුව", "නගරය අවට වනාන්තරවල පිහිටි උසම වෘක්ෂලතා හා ගංගාවල ගැඹුර මැන බැලීම අනුව", "නගරයට වසරක් තුළ ලැබෙන මුළු වර්ෂාපතනය සහ වැසි දින සංඛ්‍යාව ගණනය කිරීම අනුව",
        "බොහෝ මහා නගර පරිපාලන, වාණිජ, සංස්කෘතික හා ප්‍රවාහන යන බහු කාර්යයන් ඉටු කරයි."),
      q(t, "'පාරිසරික සරණාගතයන්' යනුවෙන් හඳුන්වනු ලබන්නේ අනාගතයේදී වේගයෙන් වැඩි විය හැකි කුමන ජන කණ්ඩායමක්ද?",
        "මුහුදු මට්ටම ඉහළ යාම, දීර්ඝ නියඟ, කාන්තාරකරණය හා දරුණු ගංවතුර නිසා නිජබිම් අතහැර යන ජනතාව", "ශීත ඍතු හිම ක්‍රීඩා හා කඳු නැගීමේ විනෝද චාරිකා සඳහා විදේශගත වන සංචාරකයන්", "පර්යේෂණ මධ්‍යස්ථානවල සේවය සඳහා ධ්‍රැවීය ප්‍රදේශවලට ගමන් කරන විද්‍යාඥයන් පිරිස", "ජාත්‍යන්තර බහුජාතික සමාගම්වල පුහුණු කළමනාකරුවන් ලෙස ස්වේච්ඡාවෙන් විදේශගත වන වෘත්තිකයන්",
        "මාලදිවයින, ටුවාලු හා බංග්ලාදේශයේ පහත් බිම් වෙරළබඩ ජනතාව මෙම අවදානමට මුහුණ දී සිටී."),
      q(t, "ශ්‍රී ලංකාවේ කොළඹ වැනි ප්‍රධාන නගරවල දහවල් ජනගහනය රාත්‍රී ජනගහනයට වඩා බෙහෙවින් වැඩි වන්නේ ඇයි?",
        "අවට දිස්ත්‍රික්කවලින් දිනපතා රැකියා, ව්‍යාපාර, පාසල් හා රෝහල් සඳහා විශාල පිරිසක් පැමිණ සවස ආපසු යන බැවින්", "නගරයේ සියලුම පදිංචිකරුවන් රාත්‍රී කාලයේදී ධීවර බෝට්ටුවලින් ගැඹුරු සාගරයට පිටත් වන බැවින්", "කොළඹ නගරය තුළ දහවල් කාලයේදී පමණක් ගොඩනැගිලි විවෘතව තබා රාත්‍රියේදී නේවාසික නිවාස වසා දමන බැවින්", "සවස් කාලයේදී කාලගුණික උෂ්ණත්වය අධික වන බැවින් ජනතාව කඳුකර නගරවලට තාවකාලිකව ගමන් කරන බැවින්",
        "දෛනික ගමනාගමනය නිසා කොළඹ නගරයේ දහවල් කාලයේ ජල, විදුලි හා ප්‍රවාහන පීඩනය ඉහළ යයි."),
      q(t, "ග්‍රාමීය ප්‍රදේශවල 'ජනගහනය අඩුවීම' (Rural Depopulation) නිසා ගම්මානවලට ඇතිවන ප්‍රධාන ඍණාත්මක බලපෑම කුමක්ද?",
        "තරුණ ශ්‍රම බලකාය නගරයට යාමෙන් වැඩිහිටියන් පමණක් ඉතිරි වීම, සේවා වැසී යාම සහ කෘෂි ඉඩම් පුරන් වීම", "ගමේ කෘෂිකාර්මික ගොවිපළවල් ස්වයංක්‍රීයව දියුණු වී අස්වැන්න දෙගුණයකින් ඉහළ යාම", "ගමේ ජන ඝනත්වය දස ගුණයකින් වැඩි වී නව මහල් නිවාස සංකීර්ණ ඉදි කිරීමට සිදුවීම", "ග්‍රාමීය මහාමාර්ගවල රථවාහන තදබදය හා කාර්මික වායු දූෂණය අධික ලෙස ඉහළ යාම",
        "ජපානයේ හා යුරෝපයේ දුරස්ථ ගම්මාන රැසක් මෙම ජනශූන්‍ය වීමේ අර්බුදයට මුහුණ දී සිටී."),
      q(t, "ප්‍රධාන මහා නගරයක් අසල 'චන්ද්‍රිකා නගර' (Satellite Towns) ඉදි කිරීමේ නාගරික සැලසුම් අරමුණ කුමක්ද?",
        "මව් නගරයේ තදබදය හා නිවාස හිඟය සමනය කිරීමට නගරයෙන් පිටත ස්වයංපෝෂිත නව නගර බිහි කිරීම", "පැරණි මව් නගරයේ පිහිටි සියලුම ආර්ථික හා වාණිජ ආයතන සම්පූර්ණයෙන්ම වසා විනාශ කර දැමීම", "නාගරික ප්‍රදේශවල සිදු කෙරෙන සියලුම කෘෂිකාර්මික හා පශු සම්පත් කටයුතු නීතියෙන් තහනම් කිරීම", "පෞද්ගලික මෝටර් රථ භාවිතය දෙගුණ කර මහාමාර්ග තදබදය නගර මධ්‍යයට යොමු කිරීම",
        "ලන්ඩන් වටා මිල්ටන් කේන්ස් හා ශ්‍රී ලංකාවේ හෝමාගම-කඩුවෙල වැනි සංවර්ධන කලාප මීට නිදසුන් වේ."),
      q(t, "මහා නගර සඳහා දුම්රිය හා අධිවේගී බස් වැනි 'පොදු ප්‍රවාහන පද්ධති' අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "පෞද්ගලික වාහන භාවිතය අඩු කර අඩු ඉඩකින් වැඩි මගීන් පිරිසක් ප්‍රවාහනය කර තදබදය හා දූෂණය අවම කිරීමට", "නාගරික මහාමාර්ගවල රථවාහන තදබදය වැඩි කර පෞද්ගලික මෝටර් රථ අලෙවිය ඉහළ නැංවීමට", "රටේ ආනයනික ඛනිජ තෙල් හා ඩීසල් පරිභෝජනය දෙගුණයකින් ඉහළ දමා ඉන්ධන වියදම වැඩි කිරීමට", "නගරයේ පදික වේදිකා හා බයිසිකල් මංතීරු සම්පූර්ණයෙන් ඉවත් කර ඒවා මෝටර් රථවලට ලබා දීමට",
        "පොදු ප්‍රවාහනය කාර්යක්ෂම කිරීම තිරසාර නගරයක මූලික ලක්ෂණයකි."),
      q(t, "ජනගහන ඝනත්ව සංඛ්‍යාලේඛනවලදී මොනාකෝ සහ සිංගප්පූරුව ඉතා ඉහළ ජන ඝනත්වයක් පෙන්වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "ඉතා කුඩා භූමි ප්‍රමාණයක් සහිත සම්පූර්ණ නාගරික රාජ්‍යයන් වීම", "රටේ භූමියෙන් බහුතරය වගා නොකළ විශාල වැලි කාන්තාරවලින් සමන්විත වීම", "විශාල යාන්ත්‍රික තිරිඟු ගොවිපළවල් හා තණබිම් රට පුරා පැතිරී පැවතීම", "ධ්‍රැව ආසන්න ශීතල කලාපයේ පිහිටා තිබීම නිසා ජනතාව එක් ස්ථානයක ගොනු වීම",
        "භූමි ප්‍රමාණය ඉතා කුඩා නගර රාජ්‍යයන්හි වර්ග කි.මී. ට ජන ඝනත්වය 8,000 සිට 25,000+ දක්වා ඉහළ අගයක් ගනී."),
      q(t, "බංග්ලාදේශය ලෝකයේ විශාල රටවල් අතර ඉහළම ජන ඝනත්වයක් ඇති රටක් බවට පත්වීමට භූගෝලීය හේතුව කුමක්ද?",
        "රටේ බහුතර භූමිය සාරවත් ගංගා-බ්‍රහ්මපුත්‍ර ඩෙල්ටා තැනිතලාව වීම නිසා ඉහළ කෘෂි ධාරිතාවක් පැවතීම", "රටේ මුළු භූමියම උස් හිමාල කඳු වැටි හා ගල් පර්වතවලින් සමන්විත වීම", "රටේ මධ්‍යම කොටසේ විශාල වියළි කාන්තාරයක් හා ලුණු තැනිතලාවක් පැවතීම", "වසර පුරාම ගොඩබිම අයිස් තට්ටුවකින් වැසී තිබීම නිසා වෙරළට පමණක් ජනයා රැස් වීම",
        "මේ නිසා බංග්ලාදේශයේ ඩෙල්ටා ජනගහනය සුළි කුණාටු හා ගංවතුර ආපදාවලට දැඩි ලෙස නිරාවරණය වේ."),
      q(t, "නිව්යෝක්, ලන්ඩන්, ටොරොන්ටෝ හා සිංගප්පූරුව වැනි 'බහු-සංස්කෘතික නගර' බිහිවන්නේ කුමන ක්‍රියාවලිය නිසාද?",
        "විවිධ රටවලින් හා සංස්කෘතීන්ගෙන් පැමිණෙන ජාත්‍යන්තර සංක්‍රමණිකයන් නගරයේ ජීවත් වීම හා වැඩ කිරීම", "සියලුම විදේශීය ශ්‍රමිකයන්ට හා සංචාරකයන්ට නගරයට ඇතුළු වීම නීතියෙන් තහනම් කිරීම", "ග්‍රාමීය හුදකලා බව හා සම්ප්‍රදායික ගොවි ජනාවාස රටාවන් නොවෙනස්ව පවත්වා ගෙන යාම", "නගරයේ පිහිටි ජාත්‍යන්තර වරායවල් හා ගුවන්තොටුපළ සම්පූර්ණයෙන්ම වසා දමා හුදකලා වීම",
        "විවිධත්වය නිසා මෙවැනි නගරවල විවිධ ජනවාර්ගික අසල්වැසි ප්‍රදේශ හා ගෝලීය වාණිජ ජාල බිහිවේ."),
      q(t, "ජනගහන අධ්‍යයනයේදී රටක 'ස්වාභාවික වර්ධන අනුපාතය' ඍණ අගයක් ගන්නේ කවර තත්ත්වයක් යටතේද?",
        "රටක වාර්ෂික මරණ සංඛ්‍යාව සජීවී උපත් සංඛ්‍යාව ඉක්මවා යන විට", "රටක වාර්ෂික උපත් සංඛ්‍යාව මරණ සංඛ්‍යාවට වඩා බෙහෙවින් වැඩි වන විට", "වෙනත් රටවලින් විශාල සංක්‍රමණිකයන් පිරිසක් රට තුළට පැමිණ පදිංචි වන විට", "සෞඛ්‍ය පහසුකම් දියුණු වී ජනතාවගේ ආයු අපේක්ෂාව වේගයෙන් වැඩි වන විට",
        "බල්ගේරියාව, ඉතාලිය හා ජපානය සෘණ ස්වාභාවික වර්ධනයක් අත්විඳින රටවලට උදාහරණ වේ."),
      q(t, "'ශුන්‍ය ජනගහන වර්ධනය' (Zero Population Growth) යනුවෙන් අදහස් කරන්නේ කුමන තත්ත්වයද?",
        "උපත් හා ආගමන සංඛ්‍යාව, මරණ හා විගමන සංඛ්‍යාවට සමාන වී මුළු ජනගහනය ස්ථාවරව පැවතීම", "රටක ජීවත් වන මුළු ජනගහනය ශුන්‍ය අගයකට පැමිණ රට සම්පූර්ණයෙන්ම ජනශූන්‍ය වීම", "වසරක් තුළ කිසිදු දරු උපතක් සිදු නොවී පාසල් පද්ධතිය සම්පූර්ණයෙන්ම වැසී යාම", "ජාත්‍යන්තර හා අභ්‍යන්තර සංක්‍රමණ සියල්ල රජය විසින් නීතිමය ලෙස තහනම් කර තැබීම",
        "ස්ථාවර සම්පත් පරිභෝජනය හා තිරසාර සංවර්ධනය සඳහා ජනගහනය ස්ථාවර වීම වැදගත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ නිරිතදිග තෙත් කලාපයේ හා මධ්‍යම කඳුකරයේ ජන ඝනත්වය වියළි කලාපයට වඩා ඉහළ වීමට හේතුව කුමක්ද?",
        "වසර පුරා ලැබෙන විශ්වාසදායක වර්ෂාපතනය, විවිධ වගාවන් සහ වාණිජ හා කාර්මික පහසුකම් බහුල වීම", "වියළි කලාපයේ පානීය ජලය කිසිසේත් නොමැති වීම සහ සියලුම ගංගා වියළී යාම", "මධ්‍යම කඳුකරයේ ශීත කාලයේදී අධික හිම පතනයක් පැවතීම හා සංචාරකයන් රැඳී සිටීම", "නිරිතදිග තෙත් කලාපයේ කිසිදු කර්මාන්තශාලාවක් හෝ මාර්ගයක් නොමැතිව ගොවිතැන පමණක් පැවතීම",
        "කොළඹ, ගම්පහ, කළුතර සහ මහනුවර වැනි දිස්ත්‍රික්ක රටේ ඉහළම ජන ඝනත්වයක් දරයි."),
      q(t, "සාම්ප්‍රදායික ග්‍රාමීය ජනාවාසවල නිවාස ඉදිකිරීමේ ද්‍රව්‍ය (මැටි, කබොක්, හුණුගල්, දැව) තීරණය වූයේ කුමන සාධකය මතද?",
        "ප්‍රදේශයේ දේශගුණය සහ අවට පරිසරයෙන් පහසුවෙන් සපයා ගත හැකි දේශීය අමුද්‍රව්‍ය", "වෙනත් මහාද්වීපවලින් ගෙන්වන ලද මිල අධික විදේශීය වාස්තු විද්‍යාත්මක සැලසුම්", "අන්තර්ජාලය හරහා ලබා ගන්නා නවීන කොන්ක්‍රීට් හා වීදුරු ගොඩනැගිලි සැලසුම්", "කලාපයේ සාගර උදම් රළවල උස සහ දෛනික චන්ද්‍ර ගුරුත්වාකර්ෂණ බලපෑම්",
        "ශ්‍රී ලංකාවේ වියළි කලාපයේ වරිච්චි බිත්ති හා ඉලුක් සෙවිලි කළ නිවාස දහවල් රස්නය පාලනය කළේය."),
      q(t, "නාගරික ඝන අපද්‍රව්‍ය හා කසළ කළමනාකරණය ලොව සෑම මහා නගරයකම දැවෙන ගැටලුවක් බවට පත්ව ඇත්තේ ඇයි?",
        "ඉහළ ජන ඝනත්වය හා පරිභෝජන රටා නිසා දිනපතා විශාල කසළ ප්‍රමාණයක් ජනනය වීමත් රඳවන භූමි හිඟ වීමත්", "නගරවල ජීවත් වන ජනතාව කාබනික පොහොර වෙනුවට ප්ලාස්ටික් ද්‍රව්‍ය භාවිත නොකරන නිසා", "නාගරික කසළ කෙටි කාලයකින් ස්වාභාවිකව වාෂ්ප වී වායුගෝලයට එකතු වන නිසා", "මහා නගර තුළ කසළ බැහැර කිරීම සඳහා භාවිත කළ හැකි හිස් කෘෂි ඉඩම් වැඩිපුර පවතින නිසා",
        "කසළ වෙන් කිරීම, ප්‍රතිචක්‍රීකරණය, කොම්පෝස්ට් නිෂ්පාදනය හා බලශක්ති ජනනය මීට තිරසාර විසඳුම් වේ."),
      q(t, "මහා නගරවල සිරස් වර්ධනය (බහුමහල් නිවාස සංකීර්ණ) නාගරික සැලසුම්කරණයේදී වැදගත් වන්නේ කෙසේද?",
        "කුඩා බිම් කඩක විශාල පවුල් සංඛ්‍යාවකට නිවාස ලබා දී හරිත අවකාශ හා කෘෂි ඉඩම් ඉතිරි කර ගැනීමට හැකිවීම", "නගරය අවට පිහිටි සාරවත් කෘෂිකාර්මික ඉඩම් වැඩි ප්‍රමාණයක් නිවාස සඳහා යොදා ගැනීමට", "නාගරික ප්‍රවාහන මාර්ග පද්ධතිය තවත් කිලෝමීටර සිය ගණනකින් පිටතට දිගු කිරීමට", "නගරය හරහා හමා යන ස්වාභාවික සුළං ප්‍රවාහ සම්පූර්ණයෙන්ම නතර කර උෂ්ණත්වය ඉහළ දැමීමට",
        "සිංගප්පූරුවේ මහල් නිවාස පද්ධතිය සිරස් නාගරික නිවාසකරණයට ලෝක ප්‍රසිද්ධ ආදර්ශයකි."),
      q(t, "ජනගහන භූගෝල විද්‍යාවේ 'තරුණ ජනගහන ප්‍රසාරණය' (Youth Bulge) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "රටේ මුළු ජනගහනයෙන් වයස අවුරුදු 15–29 අතර තරුණ ජනගහන ප්‍රතිශතය ඉතා ඉහළ මට්ටමක පැවතීම", "මුළු ජනගහනයෙන් වයස අවුරුදු 80 ට වැඩි වැඩිහිටි පුරවැසියන්ගේ ප්‍රතිශතය වැඩි වීම", "රටේ සියලුම වැඩිහිටියන් විදේශගත වී වයස අවුරුදු 5 ට අඩු ළදරුවන් පමණක් ඉතිරි වීම", "සෑම වයස් කාණ්ඩයකම ජනගහන සංඛ්‍යාව සම්පූර්ණයෙන්ම සමාන ප්‍රතිශතයකින් පැවතීම",
        "නිසි අධ්‍යාපන හා රැකියා අවස්ථා සැපයුවහොත් මෙය රටට විශාල ආර්ථික ශක්තියක් බවට පත්වේ."),
      q(t, "'සංචාරක එඬේර ජනාවාස' (Nomadic Settlements) ලෝකයේ තවමත් දක්නට ලැබෙන්නේ කුමන භූගෝලීය පරිසරවලද?",
        "මධ්‍යම ආසියානු ස්ටෙප්ස් තණබිම්, සහරා-අරාබි කාන්තාර සහ ආක්ටික් ටුන්ඩ්‍රා කලාප", "කොළඹ හා ගම්පහ වැනි වෙරළබඩ අධි ඝනත්ව වාණිජ නාගරික කලාප", "ටෝකියෝ හා ලන්ඩන් වැනි දියුණු කාර්මික හා මූල්‍ය මහා නගර මධ්‍යය", "දකුණු ආසියාවේ වසර පුරාම ජලය පවතින තෙත් වී කුඹුරු තැනිතලා",
        "සතුන්ට තණකොළ හා ජලය සොයා ඍතු අනුව ගමන් කිරීමට පහසු සැහැල්ලු කූඩාරම් නිවාස භාවිත කෙරේ."),
      q(t, "ජනගහන පිරමීඩයක එක් වයස් තීරුවක හදිසි හැකිලීමක් හෙවත් කැපීමක් දක්නට ලැබේ නම් ඉන් පැහැදිලි වන්නේ කුමක්ද?",
        "එම වයස් කාණ්ඩය උපන් හෝ ජීවත් වූ කාලයේ සිදු වූ යුද්ධයක්, සාගතයක් හෝ මහා විගමනයක්", "ජන සංගණනය පවත්වන ලද පරිගණක දත්ත පද්ධතියේ ඇති වූ තාක්ෂණික දෝෂයක්", "රටේ සියලුම ජනතාව එම කාලපරිච්ඡේදයේදී ඉහළ ආර්ථික සමෘද්ධියක් අත්කර ගත් බව", "එම වසර කිහිපය තුළ රටේ මෝසම් වර්ෂාපතනය සාමාන්‍ය අගයට වඩා තරමක් අඩු වූ බව",
        "දෙවන ලෝක යුද්ධය හා විශාල සාගත කාලපරිච්ඡේද ජනගහන පිරමීඩවල පැහැදිලිව සටහන් වී ඇත."),
      q(t, "'ජනගහන ගම්‍යතාව' (Population Momentum) යනු ජන විකාශනයේදී සිදුවන කුමන සංසිද්ධියක්ද?",
        "සාඵල්‍යතාව අඩු කළ පසුවත් දැනටමත් සිටින විශාල තරුණ පිරිස නිසා ජනගහනය තවදුරටත් වැඩි වීම", "පවුල් සැලසුම් ක්‍රම හඳුන්වා දුන් වහාම රටේ මුළු ජනගහන වර්ධනය එකවර නතර වීම", "සෞඛ්‍ය සේවා පිරිහීම හේතුවෙන් වැඩිහිටි හා ළදරු මරණ අනුපාතය සීඝ්‍රයෙන් වැඩි වීම", "වැඩ කරන වයසේ තරුණ ශ්‍රමිකයන් සියලු දෙනා විදේශ රටවලට සංක්‍රමණය වීම",
        "එබැවින් ජනගහන ප්‍රතිපත්තිවල සම්පූර්ණ බලපෑම පරම්පරා කිහිපයකට පසුව දක්නට ලැබේ."),
      q(t, "ගෝලීය සාමාන්‍යය අනුව ස්ත්‍රී පුරුෂ භාවය සැලකීමේදී සාමාන්‍යයෙන් වැඩි ආයු අපේක්ෂාවක් හිමි වන්නේ කුමන කණ්ඩායමටද?",
        "කාන්තාවන්ට (පිරිමින්ට වඩා සාමාන්‍යයෙන් වසර 4–6 ක් පමණ වැඩියෙන්)", "පිරිමින්ට (කාන්තාවන්ට වඩා සාමාන්‍යයෙන් වසර 15–20 ක් වැඩියෙන්)", "කාන්තාවන්ට හා පිරිමින්ට සෑම රටකම කිසිදා වෙනස් නොවන සමාන ආයු අපේක්ෂාවක්", "නාගරික කර්මාන්තශාලාවල සේවය කරන තරුණ කම්කරුවන්ට පමණක් ඉහළ ආයු කාලයක්",
        "ජීව විද්‍යාත්මක සාධක මෙන්ම පිරිමින් අනතුරුදායක රැකියාවලට වැඩියෙන් නිරාවරණය වීම මීට හේතු වේ."),
      q(t, "ජනාවාස ධුරාවලියේ පහළම මට්ටමේ සිට ඉහළම මට්ටම දක්වා නිවැරදි අනුපිළිවෙල දැක්වෙන වරණය කුමක්ද?",
        "හුදකලා නිවස → ගම්මානය → කුඩා නගරය → ප්‍රධාන නගරය → මහා නගරය", "මහා නගරය → කුඩා නගරය → ගම්මානය → හුදකලා නිවස → ප්‍රධාන නගරය", "ප්‍රධාන නගරය → ගම්මානය → මහා නගරය → කුඩා නගරය → හුදකලා නිවස", "ගම්මානය → මහා නගරය → කුඩා නගරය → හුදකලා නිවස → ප්‍රධාන නගරය",
        "ධුරාවලියේ ඉහළට යත්ම ජනාවාස සංඛ්‍යාව අඩු වන නමුත් ඒවායේ ජනගහනය හා සේවා පරාසය ඉහළ යයි."),
      q(t, "'නිදන නගර' හෙවත් 'ගමනාගමන තදාසන්න නගර' (Dormitory Towns) යනුවෙන් හඳුන්වන්නේ කුමන ජනාවාසද?",
        "ප්‍රධාන මහා නගරයක රැකියා කරන ජනතාව රාත්‍රියේ නැවතී සිටීමට භාවිත කරන තදාසන්න නේවාසික නගර", "ප්‍රධාන වශයෙන් බර කර්මාන්තශාලා හා ගබඩා පමණක් පිහිටුවා ඇති කාර්මික කලාප", "සෘතුමය විදේශ සංචාරකයන් පමණක් රැඳී සිටින වෙරළබඩ සංචාරක දූපත් හා හෝටල් කලාප", "පුරාණ වැව් බැඳි කෘෂි ආර්ථිකය මත පදනම් වූ දුරස්ථ ග්‍රාමීය වී ගොවි ගම්මාන",
        "කොළඹ අවට මහරගම, කඩවත, පානදුර වැනි පෙදෙස්වලින් විශාල පිරිසක් දිනපතා කොළඹට පැමිණේ."),
      q(t, "'ආර්ථික සංක්‍රමණිකයන්' සහ 'සරණාගතයන්' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?",
        "ආර්ථික සංක්‍රමණිකයන් වඩා හොඳ රැකියා සොයා ස්වේච්ඡාවෙන් යන අතර සරණාගතයන් ජීවිතාරක්ෂාව පතා පලා යයි", "ආර්ථික සංක්‍රමණිකයන් හා සරණාගතයන් යන දෙපිරිසම සන්නද්ධ යුද ගැටුම් නිසා පමණක් රටින් පිටව යයි", "ආර්ථික සංක්‍රමණිකයන්ට රැකියා හෝ මුදල් අවශ්‍ය නොවන අතර සරණාගතයන් ව්‍යාපාර ආරම්භ කිරීමට යයි", "ජාත්‍යන්තර සංක්‍රමණ නීතිය යටතේ මෙම කණ්ඩායම් දෙක අතර කිසිදු නෛතික හෝ හේතුමය ප්‍රභේදයක් නොමැත",
        "ජාත්‍යන්තර නීතිය යටතේ සරණාගතයන්ට විශේෂ රැකවරණ හිමිකම් පවතී."),
      q(t, "'චක්‍රීය සංක්‍රමණය' (Circular Migration) යනු රටවල් අතර සිදුවන කුමන ශ්‍රම චලනයක්ද?",
        "ශ්‍රමිකයෙකු මව් රට හා විදේශීය රට අතර කිහිප වරක් ගමන් කරමින් දැනුම හා ප්‍රාග්ධනය හුවමාරු කිරීම", "එක් වරක් විදේශගත වූ පසු නැවත කිසි දිනෙක තම මව් රටට නොපැමිණ ස්ථිරව පදිංචි වීම", "නගරයේ එක් වීදියක සිට තවත් වීදියකට දෛනිකව ඇවිද යාමේ නාගරික ගමනාගමන ක්‍රියාවලිය", "වනජීවීන් සෘතු වෙනස් වීමත් සමඟ වනාන්තර කොරිඩෝ ඔස්සේ සිදු කරන ස්වාභාවික සංචරණය",
        "මෙම ක්‍රියාවලිය බුද්ධි ගලනය බුද්ධි ප්‍රතිලාභයක් බවට පත් කිරීමට උපකාරී වේ."),
      q(t, "සංවර්ධිත රටවල වයස්ගත වන ජනගහනය නිසා ඉහළම වර්ධනයක් පෙන්වන රැකියා හා සේවා අංශ මොනවාද?",
        "සෞඛ්‍ය සේවා, හෙද සේවා, වැඩිහිටි රැකවරණ මධ්‍යස්ථාන සහ ඖෂධ නිෂ්පාදන කර්මාන්ත", "ළදරු ආහාර නිෂ්පාදනය හා කුඩා ළමුන් සඳහා වන සෙල්ලම් බඩු නිෂ්පාදන කර්මාන්ත", "විශාල වශයෙන් නව ප්‍රාථමික පාසල් හා පෙර පාසල් ගොඩනැගිලි ඉදිකිරීමේ ඉදිකිරීම් අංශය", "තරුණ පාසල් සිසුන් ඉලක්ක කරගත් අමතර පන්ති හා ක්‍රීඩා පුහුණු මධ්‍යස්ථාන සේවා",
        "ජනගහන වයස් ව්‍යුහය වෙනස් වීමත් සමඟ රටේ ආර්ථික හා වෙළඳපොළ ඉල්ලුමද ඊට අනුරූපව වෙනස් වේ."),
      q(t, "ග්‍රාමීය පෙදෙස්වල 'කුඩා නිවාස පොකුරක්' (Hamlet) සහ 'ගම්මානයක්' (Village) වෙන්කර හඳුනාගන්නේ කෙසේද?",
        "නිවාස සංඛ්‍යාව සහ එහි පවතින පාසල්, වෙළඳසැල් හා තැපැල් කාර්යාල වැනි මූලික සේවා ප්‍රමාණය අනුව", "ජනාවාසය වටා පිහිටා ඇති වනාන්තරයේ උසැති දැව ගස් සංඛ්‍යාව ගණන් කිරීම අනුව", "ගම ආසන්නයේ පිහිටි වාරි වැවේ ජල මට්ටම හා ජලයේ වර්ණය පරීක්ෂා කිරීම අනුව", "ප්‍රදේශයේ ස්ථාපිත කර ඇති විදුලි සංදේශ කුළුණු සංඛ්‍යාව මැන බැලීම අනුව",
        "කුඩා නිවාස පොකුරක නිවාස කිහිපයක් පමණක් ඇති අතර පොදු සේවා නොතිබිය හැකිය."),
      q(t, "ශ්‍රී ලංකාවේ උතුරු හා නැගෙනහිර පළාත්වල යුද ගැටුම් අවසන් වීමෙන් පසු ජනගහන භූගෝල විද්‍යාවේ දක්නට ලැබුණු ප්‍රධාන ප්‍රවණතාව කුමක්ද?",
        "අවතැන් වූ ජනතාව නැවත පදිංචි වීම, යටිතල පහසුකම් ගොඩනැගීම සහ නාගරික වෙළඳ කටයුතු ප්‍රකෘතිමත් වීම", "කලාපයේ වෙසෙන සියලුම ජනතාව ස්ථිරව ඉවත් වී වෙනත් පළාත්වලට සම්පූර්ණයෙන්ම සංක්‍රමණය වීම", "සාම්ප්‍රදායික වී හා ළූණු කෘෂිකර්මය සම්පූර්ණයෙන්ම නතර වී ඉඩම් පුරන් වී යාම", "වෙරළබඩ සමුද්‍රීය හා කලපු ධීවර කර්මාන්තය දිගටම තහනම් කර ජනතාව ඉන් ඉවත් කිරීම",
        "යාපනය, කිලිනොච්චි, මන්නාරම, මඩකලපුව හා ත්‍රිකුණාමලය නගර වේගයෙන් ප්‍රතිසංවර්ධනය වෙමින් පවතී."),
      q(t, "පරිසරයේ 'දරාගැනීමේ ධාරිතාව' (Carrying Capacity) යන භූගෝලීය සංකල්පයෙන් අදහස් කරන්නේ කුමක්ද?",
        "පරිසරයට ස්ථිර හානියක් නොවන පරිදි සම්පත් මගින් නිශ්චිත භූමියකට නඩත්තු කළ හැකි උපරිම ජනගහනය", "නගරයක පොදු ප්‍රවාහන පද්ධතිය තුළ දිනපතා ධාවනය කළ හැකි මගී බස් රථ සංඛ්‍යාව", "ප්‍රධාන ගංගාවක් හරහා ඉදිකළ වානේ පාලමකට ඔරොත්තු දිය හැකි උපරිම වාහන බර ප්‍රමාණය", "රටේ ප්‍රධාන වාණිජ වරායක එකවර නැංගුරම් ලා තැබිය හැකි බහාලුම් නැව් සංඛ්‍යාව",
        "තාක්ෂණික දියුණුව නිසා කෘෂි අස්වැන්න වැඩි වන විට මානව දරාගැනීමේ ධාරිතාවද ඉහළ ගොස් ඇත."),
      q(t, "අධික ජනගහනයක් සිටින දිළිඳු රටකට වඩා ධනවත් කාර්මික රටක 'පාරිසරික පියසටහන' ඉතා ඉහළ අගයක් ගන්නේ ඇයි?",
        "සංවර්ධිත රටවල එක් පුද්ගලයෙකුගේ බලශක්ති හා භාණ්ඩ පරිභෝජනය සංවර්ධනය වෙමින් පවතින රටකට වඩා බෙහෙවින් වැඩි බැවින්", "ධනවත් කාර්මික රටවල් සෑම එකකම මුළු ජනගහනය බිලියන දහයකට වඩා වැඩි අගයක් ගන්නා බැවින්", "සංවර්ධිත රටවල පුරවැසියන් පොදු ප්‍රවාහනය හා පයින් ගමන් කිරීම වැඩිපුර භාවිත කරන බැවින්", "කාර්මික රටවල් සිය භූමියෙන් අඩකට වඩා ස්වාභාවික වනාන්තර ලෙස වගා කර සංරක්ෂණය කරන බැවින්",
        "සම්පත් පරිභෝජන අර්බුදය ජනගහන සංඛ්‍යාව මත පමණක් නොව ඒක පුද්ගල පරිභෝජන රටාව මතද රඳා පවතී."),
      q(t, "සංවර්ධිත රටවල මරණ අනුපාතයට බලපාන ප්‍රධාන රෝග රටාව කුමක්ද?",
        "හෘද රෝග, පිළිකා හා දියවැඩියාව වැනි බෝ නොවන නිදන්ගත රෝග ප්‍රධාන වීම", "වසූරිය, කොලරාව හා මහාමාරිය වැනි බෝවන වසංගත රෝග ප්‍රධාන මරණ හේතුව වීම", "වනාන්තර ආශ්‍රිතව සිදුවන විෂඝෝර සර්ප දෂ්ටන හා වනසත්ත්ව ප්‍රහාර ප්‍රධාන වීම", "ආහාර හිඟය හේතුවෙන් ඇතිවන උග්‍ර මන්දපෝෂණය හා කුසගින්න පමණක් ප්‍රධාන වීම",
        "සෞඛ්‍ය හා සනීපාරක්ෂාව දියුණු වත්ම බෝවන රෝග පාලනය වී ජීවන රටා ආශ්‍රිත රෝග ප්‍රධාන වේ."),
      q(t, "ලොව ඇතැම් කලාපවල ජනගහනයේ පිරිමි ප්‍රතිශතය කාන්තා ප්‍රතිශතයට වඩා ඉහළ යාමට බලපෑ සමාජ හේතුව කුමක්ද?",
        "ඇතැම් සමාජවල පුතුන් කෙරෙහි ඇති සංස්කෘතික කැමැත්ත සහ ගැහැනු දරුවන්ට සෞඛ්‍ය අවධානය අඩු වීම", "කාන්තාවන් විශාල වශයෙන් උසස් අධ්‍යාපනය ලබා අභ්‍යවකාශ ගවේෂණ සඳහා පිටත් වී යාම", "රටේ පානීය ජල මූලාශ්‍රවල ලවණතාව ඉහළ යාම නිසා ගැහැනු දරු උපත් සම්පූර්ණයෙන් අඩු වීම", "ජීව විද්‍යාත්මකව ගැහැනු දරු උපත්වලට වඩා පිරිමි දරු උපත් ස්වාභාවිකව පස් ගුණයකින් වැඩි වීම",
        "කාන්තා අධ්‍යාපනය හා නීතිමය රැකවරණය මගින් මෙම ස්ත්‍රී-පුරුෂ අසමතුලිතතාවය නිවැරදි කිරීමට පියවර ගෙන ඇත."),
      q(t, "ශ්‍රී ලංකාවේ නිල සංඛ්‍යාලේඛනවල 'නාගරික ජනගහන ප්‍රතිශතය' සැබෑ තත්ත්වයට වඩා අඩුවෙන් පෙන්වීමට හේතුව කුමක්ද?",
        "මහ නගර සභා හා නගර සභා සීමා පමණක් නාගරික ලෙස සලකා නාගරික ලක්ෂණ ඇති ප්‍රාදේශීය සභා ග්‍රාමීය ලෙස ගැනීම", "ශ්‍රී ලංකාව තුළ කිසිදු නාගරික වාණිජ මධ්‍යස්ථානයක් හෝ මහ නගර සභාවක් පිහිටුවා නොමැති වීම", "කොළඹ මහ නගර සභා බල ප්‍රදේශය පවා නිල ජන සංගණනයේදී ග්‍රාමීය ගොවි ගම්මානයක් ලෙස ගණන් ගැනීම", "සංගණනයේදී නාගරික ප්‍රදේශවල වෙසෙන පදිංචිකරුවන් සංඛ්‍යාව ගණනය කිරීම සම්පූර්ණයෙන් අතහැර දැමීම",
        "නිල නාගරික ප්‍රතිශතය ~18% වුවද, සැබෑ නාගරික හා අර්ධ-නාගරික ජීවන රටාවක් ඇති ජනතාව 35% ඉක්මවයි."),
      q(t, "'නාගරික ගංවතුර' ග්‍රාමීය ගංවතුරට වඩා වේගවත් හා දරුණු වීමට ප්‍රධාන භූගෝලීය හේතුව කුමක්ද?",
        "තාර, කොන්ක්‍රීට් හා වහලවල් වැඩි නිසා වැසි ජලය පසට උරා නොගෙන ක්ෂණිකව මතුපිටින් ගලා යාම", "නගර මධ්‍යයට පතිත වන වාර්ෂික වර්ෂාපතනය අවට ග්‍රාමීය පෙදෙස්වලට වඩා දස ගුණයකින් වැඩි වීම", "නාගරික ප්‍රදේශවල ස්වාභාවික වනාන්තර හා ඝන තෘණ ආවරණය අධික ලෙස වැඩී පැවතීම", "මහා සාගරය නගරය මධ්‍යයේ පිහිටා ඇති බැවින් වඩදිය ජලය දිනපතාම නගර මධ්‍යයට ගලා ඒම",
        "තෙත් බිම් හා කුඹුරු ගොඩකිරීමත්, අවහිර වූ කාණු පද්ධතිත් නාගරික ක්ෂණික ගංවතුර උග්‍ර කරයි."),
      q(t, "ග්‍රාමීය ජනාවාසවලින් 'නාගරික ජනාවාස වෙත' තරුණ පිරිස ඇදී යාමට බලපාන ප්‍රධාන 'ආකර්ෂණ සාධක' (Pull Factors) මොනවාද?",
        "විවිධ රැකියා අවස්ථා, උසස් අධ්‍යාපන ආයතන, නවීන සෞඛ්‍ය සේවා හා වැඩි ජීවන පහසුකම්", "කෘෂිකාර්මික නියඟය, අස්වනු පාඩුව, ගමේ ගංවතුර හා ඉඩම් හිඟය", "ග්‍රාමීය පාසල් වැසී යාම, වගා පාළු වීම හා ස්වාභාවික ආපදා ඇතිවීම", "ගමේ රැකියා අවස්ථා අඩු වීම, පොහොර මිල ඉහළ යාම හා වාරි ජල හිඟය",
        "තරුණ ජනතාව ගම හැර යාම නිසා ග්‍රාමීය සංවර්ධන ව්‍යාපෘති මගින් ගමේම ව්‍යවසායකත්ව අවස්ථා ඇති කිරීමට උත්සාහ කෙරේ."),
      q(t, "රටක නගර පද්ධතිය තුළ 'ප්‍රමුඛ නගරයක්' (Primate City) බිහිවීමේදී දක්නට ලැබෙන ප්‍රධාන ජනාවාස ලක්ෂණය කුමක්ද?",
        "රටේ විශාලතම නගරයේ ජනගහනය හා ආර්ථික බලය දෙවන නගරයට වඩා කිහිප ගුණයකින් ඉහළ වීම", "රටේ සියලුම නගරවල ජනගහනය හා පරිපාලන බලය එකම සමාන මට්ටමකින් බෙදී පැවතීම", "රටේ කුඩා ග්‍රාමීය ජනාවාස සියල්ල වෙරළ තීරයේ පමණක් පේළියට පිහිටා තිබීම", "දෙවන හා තෙවන නගරවල ජනගහනය අගනුවර ජනගහනය මෙන් දෙගුණයකට වඩා වැඩි වීම",
        "බැංකොක් හා කොළඹ වැනි නගර රටේ පරිපාලන, වාණිජ හා ප්‍රවාහන කටයුතුවල ප්‍රධාන කේන්ද්‍රස්ථාන ලෙස ක්‍රියා කරයි."),
      q(t, "රටක් ආර්ථික හා සමාජයීය වශයෙන් සංවර්ධනය වන විට ජනතාවගේ 'සංක්‍රමණ රටා' වෙනස් වන්නේ කෙසේද?",
        "ග්‍රාමීය ප්‍රදේශවලින් නගර වෙත යන සංක්‍රමණ සිට නගර හා තදාසන්න පෙදෙස් අතර සංචලනය දක්වා මාරු වීම", "සියලු නාගරික ජනතාව ගොවිතැන සඳහා දුරස්ථ වනාන්තර ප්‍රදේශ වෙත ස්ථිරව ආපසු ගමන් කිරීම", "රටේ සියලු දෙනා සංක්‍රමණය සම්පූර්ණයෙන් නවතා එකම ගමක ජීවිත කාලය පුරා රැඳී සිටීම", "මුහුදුබඩ නගරවල සිටින ජනතාව පමණක් උස් කඳු මුදුන්වල කූඩාරම් ගසා පදිංචි වීම",
        "සංවර්ධිත සමාජවල ප්‍රවාහන පහසුකම් දියුණු වීමත් සමඟ නගරාන්තර හා ජාත්‍යන්තර රැකියා සංචලනය ඉහළ යයි."),
      q(t, "දුර බැහැර සංක්‍රමණිකයන් රැකියා සොයා වැඩි වශයෙන්ම ගමන් කිරීමට නැඹුරු වන්නේ කුමන ප්‍රදේශ වෙතද?",
        "ප්‍රධාන වාණිජ, කාර්මික හා රැකියා අවස්ථා බහුල විශාල ආර්ථික නගර වෙත", "මිනිස් වාසයෙන් තොර දුරස්ථ වනාන්තර හා කඳුකර රක්ෂිත කලාප වෙත", "සේවා පහසුකම් හා ප්‍රවාහනය අවම කුඩා හුදකලා ගොවි ගම්මාන වෙත", "ජල සම්පත අඩු ශුෂ්ක කාන්තාර හා අර්ධ කාන්තාර මධ්‍ය ප්‍රදේශ වෙත",
        "කෙටි දුර සංක්‍රමණ ගමේ සිට අසල නගරයට සිදුවන නමුත් දිගු දුර සංක්‍රමණිකයන් ප්‍රධාන ආර්ථික මධ්‍යස්ථාන තෝරා ගනී."),
      q(t, "රටක 'මධ්‍ය වයස' (Median Age) වසර 20 සිට වසර 42 දක්වා ඉහළ ගොස් තිබේ නම් ඉන් පෙන්නුම් කරන්නේ කුමක්ද?",
        "රටේ උපත් අනුපාතය අඩු වී ආයු අපේක්ෂාව ඉහළ යාමත් සමඟ ජනගහනය වයස්ගත වී ඇති බවයි", "රටේ සමස්ත ජනගහනයෙන් අඩකට වඩා වයස අවුරුදු පහළොවට අඩු ළමුන් බවයි", "රටේ ළදරු මරණ අනුපාතය ඉතා ඉහළ මට්ටමකට ළඟා වී ඇති බවයි", "රටේ වාර්ෂික උපත් සංඛ්‍යාව මරණ සංඛ්‍යාව මෙන් දස ගුණයකින් ඉහළ ගොස් ඇති බවයි",
        "නයිජර් වැනි රටවල මධ්‍ය වයස අවුරුදු 15 ක් පමණ වන අතර ජපානයේ හා ජර්මනියේ එය අවුරුදු 46–49 පමණ වේ."),
      q(t, "නාගරික භූගෝල විද්‍යාවේ 'ග්‍රාමීය-නාගරික සීමා තීරය' (Rural-Urban Fringe) යනුවෙන් හඳුන්වන්නේ කුමන ප්‍රදේශයද?",
        "නගරයේ තදාසන්න නිවාස පෙදෙස් හා අවට ග්‍රාමීය කෘෂිකාර්මික ඉඩම් එකිනෙක මිශ්‍ර වෙමින් පවතින සංක්‍රාන්ති කලාපයයි", "නගරයේ වඩාත්ම කාර්යබහුල මහල් ගොඩනැගිලි පිහිටි මධ්‍යම ව්‍යාපාරික දිස්ත්‍රික්කයයි", "මිනිස් ජනාවාසවලින් සම්පූර්ණයෙන්ම තොර ගැඹුරු සාගර පතුලේ මහාද්වීපික තටාක ප්‍රදේශයයි", "මධ්‍යම කඳුකරයේ වනජීවී දෙපාර්තමේන්තුව යටතේ පාලනය වන දැඩි ස්වභාව රක්ෂිත කලාපයයි",
        "නව නිවාස යෝජනා ක්‍රම, ගබඩා සංකීර්ණ, කර්මාන්ත උද්‍යාන සහ එළවළු/මල් වගා ගොවිපළවල් මෙම තීරයේ එකට පවතී."),
      q(t, "නගරවල 'පදික කලාප' (Pedestrian Zones) හා 'බයිසිකල් මංතීරු' (Cycling Lanes) පුළුල් කිරීමෙන් ලැබෙන නාගරික ප්‍රතිලාභ මොනවාද?",
        "වාහන දුම හා ශබ්ද දූෂණය අඩු වීම, මාර්ග අනතුරු අවම වීම සහ මහජන සෞඛ්‍යය දියුණු වීම", "නගර මධ්‍යයේ මෝටර් රථ තදබදය හා ඉන්ධන නාස්තිය කිහිප ගුණයකින් ඉහළ යාම", "නගරයේ වෙළඳසැල් වෙත පැමිණෙන පාරිභෝගිකයන් හා පදිකයන් සංඛ්‍යාව සම්පූර්ණයෙන් අඩු වීම", "පොදු ප්‍රවාහන සේවා අඩපණ වී ග්‍රාමීය මාර්ග සියල්ල ජලයෙන් යටවී විනාශ වීම",
        "කෝපන්හේගන් සහ ඇම්ස්ටර්ඩෑම් නගර ලොව හොඳම බයිසිකල් හිතකාමී නාගරික ප්‍රවාහන ආදර්ශ සපයයි."),
      q(t, "ශ්‍රී ලංකාවේ 'මහනුවර' නගරය ආරම්භයේදී සාර්ථකව වර්ධනය වීමට බලපෑ ප්‍රධාන 'ස්ථානීය' (Site) සාධකය කුමක්ද?",
        "මහවැලි ගඟෙන් තුන් පැත්තක් ආවරණය වීම සහ හන්තාන හා නකල්ස් කඳු වළල්ලෙන් වටවූ නිම්නයක පිහිටීම", "මහා සාගරයට කෙලින්ම විවෘත වූ ගැඹුරු ස්වාභාවික නාවික වරායක් එහි පිහිටා තිබීම", "පොළොව යට විශාල ඛනිජ තෙල්, ගල් අඟුරු හා ස්වාභාවික වායු නිධි බහුලව පැවතීම", "වර්ෂාවෙන් තොර පැතලි අර්ධ ශුෂ්ක තැනිතලාවක හා වැලි කඳු අතර ආරක්ෂිතව පිහිටා තිබීම",
        "සතුරු ආක්‍රමණවලින් ආරක්ෂා වීමට මෙම භූගෝලීය පිහිටීම සෙන්කඩගල රාජධානියට ඉතා වාසිදායක විය."),
      q(t, "ශ්‍රී ලංකාවේ 'ගාල්ල' සහ 'ත්‍රිකුණාමලය' යන නගර බිහිවීමට හා වර්ධනය වීමට පදනම් වූ ප්‍රධාන භූගෝලීය සාධකය කුමක්ද?",
        "ස්වාභාවික බොකු ආශ්‍රිත වරායන් සහ ජාත්‍යන්තර සාගර වෙළඳ මාර්ගවල උපායමාර්ගික පිහිටීම", "මුහුදු මට්ටමෙන් මීටර් දෙදහසකට වඩා උස් සිසිල් කඳු මුදුන්වල පිහිටා තිබීම", "තේ හා රබර් වගාවට පමණක් සුදුසු අධික බෑවුම් සහිත මධ්‍යම කඳුකර භූමිය වීම", "වසර පුරා හිම පතනය ලැබෙන ග්ලැසියර නිම්න ආශ්‍රිත ශීත දේශගුණයක් පැවතීම",
        "ගාල්ල ලන්දේසි කොටුව හා වරායද, ත්‍රිකුණාමලය කොඩ්ඩියාර් බොක්කද ඉන්දියන් සාගරයේ වැදගත් නාවික මධ්‍යස්ථාන විය."),
      q(t, "'අභ්‍යන්තර සංක්‍රමණ' (Internal Migration) අතර 'ගමෙන් ගමට සංක්‍රමණය' (Rural-to-Rural Migration) බහුලව සිදුවන්නේ කුමන අවස්ථාවලදීද?",
        "විවාහ වී වෙනත් ගමක පදිංචි වීම, නව ගොවි ජනපද වෙත යාම හෝ කෘෂි කන්න රැකියා සඳහා යාම", "විදේශීය විශ්වවිද්‍යාලවල උසස් අධ්‍යාපනය ලැබීමට ගුවන් මගින් වෙනත් රටකට ගමන් කිරීම", "පෞද්ගලික මෝටර් රථයෙන් අගනුවර ප්‍රධාන කාර්යාලයකට දිනපතා රැකියාවට පැමිණ ආපසු යාම", "යුද ගැටුම් හේතුවෙන් මහාද්වීපයක් හරහා සරණාගතයන් ලෙස අසල්වැසි රටකට පලා යාම",
        "ශ්‍රී ලංකාවේ මහවැලි සංවර්ධන කලාප වෙත සිදුවූ ජන සංක්‍රමණය මීට ප්‍රධාන උදාහරණයකි."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවලට වඩා සංවර්ධිත රටවල නාගරික ජනගහන ප්‍රතිශතය 80% ඉක්මවා ඇත්තේ ඇයි?",
        "කෘෂිකර්මය යාන්ත්‍රිකරණය වීම නිසා ගොවිබිම්වල අඩු ශ්‍රමයක් අවශ්‍ය වීමත් කර්මාන්ත හා සේවා නගරවල ඒකරාශී වීමත්", "සංවර්ධිත රටවල කිසිදු ආහාර බෝගයක් වගා නොකර සම්පූර්ණයෙන්ම ආනයනය මත යැපෙන බැවින්", "ග්‍රාමීය ප්‍රදේශවල ජනතාවට පදිංචි වීමට නීතියෙන් සම්පූර්ණයෙන්ම තහනම් කර ඇති බැවින්", "සංවර්ධිත රටවල මුළු භූමි ප්‍රමාණයෙන් සියයට සියයක්ම ගොඩනැගිලිවලින් වැසී ඇති බැවින්",
        "කෙසේ වෙතත් 21 වන සියවසේ වේගවත්ම නාගරික ජනගහන වර්ධනය සිදුවන්නේ ආසියාවේ හා අප්‍රිකාවේ නගරවලය."),
      q(t, "විදේශීය නගරවල 'දාම සංක්‍රමණය' (Chain Migration) හරහා සංක්‍රමණික ප්‍රජා ජාල ගොඩනැගෙන්නේ කෙසේද?",
        "පළමුව නගරයකට ගිය සංක්‍රමණිකයෙකුගේ මගපෙන්වීම හා උපකාර මත ඔහුගේ ඥාතීන් හා ගම්වැසියන්ද එහි පදිංචි වීම", "රජය විසින් සියලු විදේශිකයන් බලහත්කාරයෙන් එකම වසා දැමූ කඳවුරක රඳවා තැබීම මගින්", "ගුවන් ගමන් අතරමගදී දිශාව වැරදීම නිසා අහඹු ලෙස එකම කුඩා නගරයකට ගොඩබැසීම මගින්", "සංක්‍රමණිකයන් කිසිවෙකු සමඟ සම්බන්ධ නොවී හුදකලාව රට පුරා විසිරී ජීවත් වීම මගින්",
        "Chain Migration නිසා නව සංක්‍රමණිකයන්ට නිවාස, රැකියා හා සංස්කෘතික සහයෝගය පහසුවෙන් හිමිවේ."),
      q(t, "ජනගහන අධ්‍යයනයේදී 'ප්‍රතිස්ථාපන මට්ටමේ සාඵල්‍යතාව' (Replacement Level Fertility ~2.1) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "සංක්‍රමණ නොමැති විට වර්තමාන ජනගහන ප්‍රමාණය දිගු කාලීනව ස්ථාවරව පවත්වා ගැනීමට එක් කාන්තාවකට සිටිය යුතු සාමාන්‍ය දරුවන් ගණනයි", "සෑම පවුලකටම අනිවාර්යයෙන්ම දරුවන් දස දෙනෙකු බැගින් සිටිය යුතු බව පවසන ජාතික නීතියයි", "වසරකට රටේ සිදුවන මුළු විදේශ සංක්‍රමණිකයන් සංඛ්‍යාව උපත් සංඛ්‍යාවෙන් අඩු කළ විට ලැබෙන අගයයි", "වැඩිහිටි ජනගහනය සියයට සියයක් දක්වා ඉහළ ගොස් තරුණ ශ්‍රම බලකාය සම්පූර්ණයෙන්ම අවසන් වීමයි",
        "ශ්‍රී ලංකාවේ මුළු සාඵල්‍යතා අනුපාතයද (TFR) මෑත කාලයේදී ප්‍රතිස්ථාපන මට්ටමට ආසන්න හෝ ඊට මදක් අඩු අගයක පවතී."),
      q(t, "'නාගරික ක්ෂය වීම' (Urban Decay) ඇතැම් පැරණි කාර්මික නගරවල (උදා: ඩෙට්‍රොයිට්, ලිවර්පූල්) දක්නට ලැබුණේ ඇයි?",
        "සාම්ප්‍රදායික කර්මාන්ත වැසී යාම, රැකියා අහිමි වීම, මධ්‍යම පාන්තිකයන් තදාසන්න පෙදෙස්වලට යාම හා නඩත්තුව අඩුවීම", "නගර මධ්‍යයේ නවීන තාක්ෂණික කර්මාන්තශාලා දස ගුණයකින් වැඩි වී ආදායම ඉහළ යාම", "නගරයට විශාල ජාත්‍යන්තර ගුවන්තොටුපළක් හා සුඛෝපභෝගී හෝටල් ඉදි කිරීම නිසා සංචාරකයන් වැඩිවීම", "නගරයේ පොදු උද්‍යාන හා පදික මංතීරු ප්‍රමාණය ඉහළ ගොස් වායු ගුණාත්මකභාවය වැඩිදියුණු වීම",
        "මෙවැනි නගර යළි පණ ගැන්වීමට 'නාගරික පුනර්ජීවන' (Urban Regeneration) ව්‍යාපෘති ක්‍රියාත්මක කෙරේ."),
      q(t, "'මිශ්‍ර ඉඩම් පරිභෝජනය' (Mixed Land Use) නූතන තිරසාර නගර සැලසුම්කරණයේදී ප්‍රවර්ධනය කරන්නේ ඇයි?",
        "නිවාස, කාර්යාල, කඩසාප්පු, පාසල් හා උද්‍යාන පයින් යා හැකි දුරින් පිහිටුවා දිගු වාහන ගමන් අඩු කිරීමට", "අධික විෂ දුම් පිට කරන රසායනික කර්මාන්තශාලා පාසල් හා රෝහල් අසලම පිහිටුවීමට", "නගරයේ සියලු පොදු බස් හා දුම්රිය මාර්ග සම්පූර්ණයෙන්ම වසා දමා ගමනාගමනය නතර කිරීමට", "නගර මධ්‍යයේ ඇති සියලුම උද්‍යාන කපා දමා වාහන නැවැත්වීමේ කොන්ක්‍රීට් අංගණ තැනීමට",
        "මිශ්‍ර ඉඩම් පරිභෝජනය පදිකයන්ගේ ජීවන පහසුව හා කාබන් විමෝචනය අඩු කිරීම කෙරෙහි අවධානය යොමු කරයි."),
      q(t, "ජනාවාස භූගෝල විද්‍යාවේ සේවාවක 'අවම එළිපත්ත ජනගහනය' (Threshold Population) යනු කුමක්ද?",
        "යම් සේවාවක් හෝ වෙළඳසැලක් ආර්ථිකව ලාභදායීව පවත්වාගෙන යාමට අවශ්‍ය අවම ගනුදෙනුකරුවන් හෝ ජනගහන ප්‍රමාණයයි", "නගරයේ ඉදිකිරීමට නීතියෙන් අවසර දී ඇති මහල් ගොඩනැගිලිවල උපරිම උස සීමාවයි", "ග්‍රාමීය ජනාවාසයක නිවාස අතර තිබිය යුතු අවම මාර්ග පළල හා ඉඩම් ප්‍රමාණයයි", "නගර සභා බල ප්‍රදේශයක් තුළ වසරකට වරක් සිදු කරන ජල හා විදුලි පරිභෝජන මිනුමයි",
        "ප්‍රාථමික පාසලකට වඩා විශ්වවිද්‍යාලයකට හෝ මහ රෝහලකට ඉතා ඉහළ එළිපත්ත ජනගහනයක් අවශ්‍ය වේ."),
      q(t, "සේවා මධ්‍යස්ථාන පිහිටීමේදී 'භාණ්ඩයක හෝ සේවාවක පරාසය' (Range of a Good or Service) යනුවෙන් අදහස් කරන්නේ කුමක්ද?",
        "නිශ්චිත භාණ්ඩයක් හෝ සේවාවක් ලබා ගැනීම සඳහා පාරිභෝගිකයන් ගමන් කිරීමට සූදානම් වන උපරිම දුර ප්‍රමාණයයි", "වෙළඳසැලක අලෙවි කරනු ලබන භාණ්ඩවල උපරිම හා අවම මිල ගණන් අතර පවතින වෙනසයි", "නගර මධ්‍යයේ පිහිටි සුපිරි වෙළඳසැලක සම්පූර්ණ බිම් වර්ගඵලය හා ගබඩා ධාරිතාවයි", "වෙළඳ ආයතනයක දෛනිකව සේවය කරනු ලබන ස්ථිර හා අනියම් සේවකයන්ගේ මුළු සංඛ්‍යාවයි",
        "පාන් හා කිරි වැනි දෛනික භාණ්ඩ සඳහා පරාසය කෙටි වන අතර විශේෂඥ රෝහල් සඳහා පරාසය ඉතා දිගු වේ."),
      q(t, "මහා සංවර්ධන ව්‍යාපෘති නිසා ඇතිවන 'සංවර්ධන අවතැන් වීම' (Development-Induced Displacement) යනු කුමක්ද?",
        "මහා ජලාශ, අධිවේගී මාර්ග හා වරාය ඉදිකිරීමේදී ඉඩම් යටවීම නිසා පදිංචිකරුවන් නව ගම්මානවල පදිංචි කිරීමයි", "සුළි කුණාටු හා ගංවතුර වැනි ස්වාභාවික ආපදා නිසා තාවකාලිකව පාසල් කඳවුරු වෙත යාමයි", "උසස් රැකියා හා වැඩි වැටුප් අපේක්ෂාවෙන් තරුණ පිරිස ස්වේච්ඡාවෙන් විදේශ රටවලට සංක්‍රමණය වීමයි", "විශ්වවිද්‍යාල සිසුන් අධ්‍යාපන කටයුතු සඳහා වසර කිහිපයකට නේවාසිකාගාරවල පදිංචි වීමයි",
        "කොත්මලේ ජලාශය ඉදිකිරීමේදී යටවූ ගම්මානවල ජනතාව කුණ්ඩසාලේ හා කොත්මලේ නව නගරයේ පදිංචි කරවන ලදී."),
      q(t, "ශ්‍රී ලංකාවේ 'නුවරඑළිය' දිස්ත්‍රික්කයේ ජනගහන හා ජනාවාස සැකැස්ම සෙසු දිස්ත්‍රික්කවලින් වෙනස් වන්නේ කෙසේද?",
        "මුළු ජනගහනයෙන් අඩකට ආසන්න ප්‍රතිශතයක් වතු අංශයේ ජීවත් වීම සහ කඳු බෑවුම්වල පේළි නිවාස පැවතීම", "දිස්ත්‍රික්කයේ මුළු ජනගහනයම මහල් නිවාස සහිත ප්‍රධාන නාගරික ප්‍රදේශවල පමණක් පදිංචි වී සිටීම", "මුහුදු වෙරළ තීරය දිගේ ධීවර ජනාවාස රේඛීයව පිහිටා තිබීම හා කලපු ආශ්‍රිත රැකියා ප්‍රමුඛ වීම", "ශුෂ්ක තැනිතලා භූමිවල වැව් ආශ්‍රිත ගංගොඩ ජනාවාස පමණක් බහුලව ව්‍යාප්ත වී තිබීම",
        "ශ්‍රී ලංකාවේ වැඩිම වතු ජනගහනයක් ජීවත් වන දිස්ත්‍රික්කය නුවරඑළිය වේ."),
      q(t, "ජනගහන භූගෝල විද්‍යාවේ 'අධි ජනගහනය' (Overpopulation) යන තත්ත්වය නිවැරදිව විග්‍රහ කරන්නේ කුමන ප්‍රකාශයද?",
        "ප්‍රදේශයක පවතින සම්පත්, ආහාර, ජලය හා රැකියා ප්‍රමාණයට වඩා ජනගහනය වැඩි වී ජීවන තත්ත්වය පහත වැටීමයි", "වර්ග කිලෝමීටරයකට වාසය කරන පුද්ගලයන් සංඛ්‍යාව සියය ඉක්මවීම පමණක් සැලකිල්ලට ගැනීමයි", "රටක මුළු භූමි ප්‍රමාණය විශාල වීම හේතුවෙන් ප්‍රවාහන ජාල ගොඩනැගීමට අපහසු වීමයි", "රට තුළ නාගරික ප්‍රදේශ කිහිපයක් පිහිටා තිබීම නිසා ග්‍රාමීය පරිසරය සම්පූර්ණයෙන් අතුරුදහන් වීමයි",
        "සිංගප්පූරුවේ ජන ඝනත්වය ඉතා ඉහළ වුවද සම්පත් හා ආර්ථික ධාරිතාව ඉහළ නිසා එය අධි ජනගහන රටක් ලෙස නොසැලකේ."),
      q(t, "'ඌන ජනගහනය' (Underpopulation) ඇති රටකට (උදා: කැනඩාව, ඔස්ට්‍රේලියාව) සංවර්ධන කටයුතුවලදී මුහුණ දීමට සිදුවන ප්‍රධාන ගැටලුව කුමක්ද?",
        "පවතින විශාල සම්පත් හා ඉඩම් ප්‍රයෝජනයට ගැනීමට ප්‍රමාණවත් ශ්‍රම බලකායක් හා වෙළඳපොළක් නොමැති වීම", "සියලුම වැසියන්ට ප්‍රමාණවත් ආහාර නිපදවීමට තරම් වගා බිම් හා ජල සම්පත කිසිසේත් නොමැති වීම", "නිවාස ඉදිකිරීම සඳහා ගොඩබිම් ඉඩම් හිඟ වීම නිසා සාගරය ගොඩකිරීමට සිදුවීම", "අධික ජන තදබදය නිසා මාර්ගවල රථවාහන ගමනාගමනය දිනපතා සම්පූර්ණයෙන් අඩපණ වීම",
        "එබැවින් මෙම රටවල් පුහුණු විදේශීය සංක්‍රමණිකයන්ට ස්ථිර පදිංචිය ලබා දීමට විශේෂ වැඩසටහන් ක්‍රියාත්මක කරයි."),
      q(t, "නාගරික භූගෝල විද්‍යාවේ 'නේවාසික වෙන්වීම' (Residential Segregation) ඇති වන්නේ කුමන සාධක පදනම් කරගෙනද?",
        "ආදායම් මට්ටම, සමාජ පන්තිය, ජනවාර්ගිකත්වය, භාෂාව හෝ ආගම මත එකම කණ්ඩායම් නගරයේ නිශ්චිත කොටස්වල ඒකරාශී වීම", "නගරයේ වැසියන් භාවිත කරන පෞද්ගලික මෝටර් රථවල වර්ණය හා නිෂ්පාදන වර්ෂය පදනම් කර ගැනීම", "පුද්ගලයන්ගේ ශරීර උස අඩු වැඩි බව හා වයස් පරතරය මත නිවාස බෙදා වෙන් කිරීම", "නගරයේ එක් එක් වීදියට ලැබෙන වාර්ෂික වර්ෂාපතන ප්‍රමාණය හා සුළං වේගය අනුව බෙදී යාම",
        "ධනවතුන්ගේ ආරක්ෂිත නිවාස සංකීර්ණ හා අඩු ආදායම් මුඩුක්කු පෙදෙස් අතර විශාල සමාජ පරතරයක් ඇතිවිය හැකිය."),
      q(t, "'ළමා යැපුම් අනුපාතය' (Youth Dependency Ratio) අඩු වන විට රටක රජයට ලැබෙන ප්‍රධාන ආර්ථික වාසිය කුමක්ද?",
        "ප්‍රාථමික පාසල් හා ළමා සුබසාධන වියදම් පීඩනය අඩු වී යටිතල පහසුකම් හා කර්මාන්ත සංවර්ධනයට ආයෝජනය කළ හැකි වීම", "රටේ සියලුම වැඩිහිටියන්ගේ විශ්‍රාම වැටුප් හා සෞඛ්‍ය වියදම් සම්පූර්ණයෙන්ම ශුන්‍ය බවට පත් වීම", "පාසල් පද්ධතිය සඳහා ගුරුවරුන් හා අධ්‍යාපන උපකරණ කිසිසේත් අවශ්‍ය නොවීම", "රජයට ලැබෙන සියලුම දේශීය බදු ආදායම් සම්පූර්ණයෙන්ම නැති වී යාම",
        "මෙය ආර්ථික සංවර්ධනය සඳහා ජන විකාශන කවුළුව (Demographic Window of Opportunity) විවෘත කරයි."),
      q(t, "'වැඩිහිටි යැපුම් අනුපාතය' (Old-Age Dependency Ratio) වේගයෙන් ඉහළ යන විට රාජ්‍ය මූල්‍ය පද්ධතියට ඇති වන ප්‍රධාන පීඩනය කුමක්ද?",
        "වැඩ කරන තරුණ පිරිස අඩු වන විට විශ්‍රාම වැටුප් හා වැඩිහිටි සෞඛ්‍ය සේවා වියදම් විශාල ලෙස ඉහළ යාම", "රට පුරා පෙර පාසල් හා ප්‍රාථමික පාසල් ගොඩනැගිලි හිඟ වී ළමා සුබසාධන වියදම් දෙගුණ වීම", "කුඩා දරුවන්ගේ සෙල්ලම් බඩු හා පාසල් පොත්පත් මිල ගණන් අසීමිතව ඉහළ යාම", "රැකියා සඳහා බඳවා ගන්නා අවම නීතිමය වයස් සීමාව අවුරුදු දහය දක්වා පහත හෙළීමට සිදුවීම",
        "ශ්‍රී ලංකාවද 2040 වන විට ජනගහනයෙන් ~25% ක් වයස 60 ට වැඩි වන බැවින් දායක විශ්‍රාම ක්‍රම ශක්තිමත් කළ යුතුය."),
      q(t, "ග්‍රාමීය ජනාවාසවල 'නියඟය හා වාරි පද්ධති බිඳවැටීම' ජනගහන සංක්‍රමණය කෙරෙහි බලපාන්නේ කෙසේද?",
        "කෘෂි අස්වනු පාඩු වීම නිසා ගොවි පවුල්වල සාමාජිකයන් රැකියා සොයා නාගරික කලාපවලට හෝ විදේශවලට යාම", "නගරවල කාර්යාල රැකියා කරන පිරිස විශාල වශයෙන් නියඟය පවතින ගම්මාන වෙත පදිංචියට පැමිණීම", "ජලය හිඟ වුවද වී වගා අස්වැන්න දෙගුණ වී ග්‍රාමීය ආදායම අධික ලෙස ඉහළ යාම", "ගමේ කිසිදු පුද්ගලයෙකු පිටතට නොයා ජනගහන ව්‍යාප්තිය සම්පූර්ණයෙන් නොවෙනස්ව පැවතීම",
        "දේශගුණික අස්ථාවරත්වය ග්‍රාමීය-නාගරික සංක්‍රමණයේ ප්‍රධාන තල්ලු සාධකයකි."),
      q(t, "මහා නගරවල උද්‍යාන, පදික චතුරශ්‍ර හා වෙරළ තීර වැනි 'පොදු අවකාශයන්' සංරක්ෂණය කිරීම වැදගත් වන්නේ ඇයි?",
        "මානසික සෞඛ්‍යය දියුණු කිරීම, සමාජ එකමුතුව වැඩි කිරීම, නාගරික උෂ්ණත්වය අඩු කිරීම හා වැසි ජලය උරා ගැනීම", "නගර මධ්‍යයේ වාහන නැවැත්වීමේ ගාස්තු අඩු කර ගැනීමට පමණක් ප්‍රයෝජනවත් ස්ථාන වීම", "නගරයේ සියලුම වාණිජ ඉඩම්වල ආර්ථික වටිනාකම සම්පූර්ණයෙන් බිංදුව දක්වා පහත හෙළීම", "නගර මධ්‍යයේ වන අලින්, දිවියන් හා වලසුන් වැනි වන සතුන් ඇති කිරීමට ඉඩ සැලසීම",
        "කොළඹ විහාරමහාදේවී උද්‍යානය, ගාලු මුවදොර පිටිය හා දියත උයන නාගරික ප්‍රජාවට ඉතා වැදගත් හරිත අවකාශයන් වේ."),
      q(t, "'ජාත්‍යන්තර සංක්‍රමණ සංවිධානය' (IOM) සහ 'UNHCR' ආයතනය අතර කාර්යභාරයේ ප්‍රධාන වෙනස කුමක්ද?",
        "IOM සියලු සංවර්ධන හා සේවා සංක්‍රමණ කළමනාකරණයට සහාය වන අතර UNHCR යුද හා පීඩන නිසා අවතැන් වූ සරණාගතයන් රකී", "IOM ආයතනය ජාත්‍යන්තර සංචාරක හෝටල් පාලනය කරන අතර UNHCR ආයතනය ගුවන් යානා නිපදවීම සිදු කරයි", "මෙම ආයතන දෙකම ලෝක ක්‍රිකට් හා පාපන්දු තරඟාවලි සංවිධානය කරන ජාත්‍යන්තර ක්‍රීඩා සංවිධාන වේ", "IOM ආයතනය සාගර වරායන් පාලනය කරන අතර UNHCR ආයතනය කාන්තාරවල තෙල් ළිං කැණීම් සිදු කරයි",
        "ආරක්ෂිත, ක්‍රමවත් හා නීත්‍යානුකූල සංක්‍රමණය තිරසාර සංවර්ධන ඉලක්කවල (SDG 10.7) කොටසකි."),
      q(t, "කලාපීය වශයෙන් 'ලිහිල් දේශසීමා ශ්‍රම සංචලනය' (උදා: යුරෝපා සංගමයේ ෂෙන්ගන් කලාපය) ජනගහන ව්‍යාප්තියට බලපාන්නේ කෙසේද?",
        "වීසා බාධකවලින් තොරව සාමාජික රටවල් අතර රැකියා, අධ්‍යාපනය හා පදිංචිය සඳහා ජනතාවට පහසුවෙන් ගමන් කිරීමට හැකිවීම", "සාමාජික රටවල් අතර සියලු දේශසීමාවල උස් කොන්ක්‍රීට් තාප්ප ඉදිකර ගමනාගමනය නතර කිරීම", "සාමාජික රටවල් අතර සියලු භාණ්ඩ හා සේවා වෙළඳ ගනුදෙනු සම්පූර්ණයෙන්ම තහනම් කිරීම", "සාමාජික රටවල් අතර නීත්‍යානුකූල සංක්‍රමණිකයන් සංඛ්‍යාව සම්පූර්ණයෙන් ශුන්‍ය අගයට අඩු කිරීම",
        "නැගෙනහිර යුරෝපයේ රටවලින් බටහිර යුරෝපයේ ආර්ථික මධ්‍යස්ථාන වෙත විශාල තරුණ ශ්‍රම සංචලනයක් මේ හරහා සිදු වී ඇත."),
      q(t, "ආර්ථික සංවර්ධනයත් සමඟ 'ග්‍රාමීය ජනාවාස ව්‍යුහයේ' සිදුවන ප්‍රධාන පරිවර්තනය කුමක්ද?",
        "කෘෂි රැකියා අඩු වී කෘෂි-සැකසුම්, සංචාරක, ප්‍රවාහන හා සේවා ගමට පැමිණීමෙන් ගම්මාන කුඩා නගර බවට පත් වීම", "ගම්මානවල තිබූ සියලුම පාරවල් ගලවා ඉවත් කර ප්‍රවාහනය සම්පූර්ණයෙන්ම අත්හැර දැමීම", "ග්‍රාමීය නිවාසවල විදුලි හා පානීය ජල සම්බන්ධතා විසන්ධි කර පැරණි ක්‍රමයට මාරු වීම", "සියලුම ග්‍රාමීය වැසියන් නිවාස අතහැර වනාන්තරවල ගල් ගුහාවල පදිංචියට යාම",
        "මෙය 'ග්‍රාමීය පරිවර්තනය' (Rural Transformation) ලෙස හැඳින්වේ."),
      q(t, "පැරණි බර කාර්මික නගරයක සිට නූතන 'දැනුම හා සේවා නගර' බවට පරිවර්තනය වූ නගරවලට උදාහරණ මොනවාද?",
        "ලන්ඩන්, පිට්ස්බර්ග්, සෝල් සහ ටෝකියෝ (මූල්‍ය, මෘදුකාංග හා පර්යේෂණ ක්ෂේත්‍ර ප්‍රමුඛ වීම)", "ඇමසන් නිවර්තන වැසි වනාන්තරයේ ගංගා නිම්න හා ස්වාභාවික වන රක්ෂිත කලාප", "උතුරු අප්‍රිකාවේ සහරා කාන්තාරයේ පිහිටි කුඩා ස්වාභාවික ක්ෂේම භූමි ජනාවාස", "උත්තර ධ්‍රැවයේ හා අයිස්ලන්තයේ ජනාවාස රහිත ග්ලැසියර කඳු මුදුන් ප්‍රදේශ",
        "නගරයේ පැරණි කර්මාන්තශාලා ගබඩා නවීන තාක්ෂණ උද්‍යාන හා විශ්වවිද්‍යාල කලාප බවට පත් කෙරේ."),
      q(t, "'කලාපීය සේවා මධ්‍යස්ථාන' ලෙස ප්‍රාදේශීය කුඩා නගර සංවර්ධනය කිරීම රටකට වැදගත් වන්නේ ඇයි?",
        "අධ්‍යාපන, සෞඛ්‍ය හා බැංකු පහසුකම් ගම අසලින්ම ලබා දී අගනුවර වෙත එන සංක්‍රමණ පීඩනය අඩු කිරීමට", "රටේ ප්‍රධාන අගනුවර ජනතාවගෙන් සම්පූර්ණයෙන් හිස් කර පාළු නගරයක් බවට පත් කිරීමට", "ග්‍රාමීය ප්‍රදේශවල ක්‍රියාත්මක වන සියලුම පාසල් හා රෝහල් වසා දමා නගරයට ගෙන ඒමට", "දිස්ත්‍රික්ක අතර ක්‍රියාත්මක වන සියලුම පොදු බස් හා දුම්රිය ප්‍රවාහන සේවා නතර කිරීමට",
        "ශ්‍රී ලංකාවේ කුරුණෑගල, අනුරාධපුර, රත්නපුර, බදුල්ල හා මාතර වැනි ප්‍රාදේශීය නගර දියුණු කිරීම මීට මනා නිදසුනකි."),
      q(t, "ජනගහනයේ 'වෘත්තීය ව්‍යුහය' (Occupational Structure) අනුව රටක් සංවර්ධිත මට්ටමක පවතින බව හඳුනා ගන්නේ කෙසේද?",
        "ශ්‍රම බලකායෙන් සුළු ප්‍රතිශතයක් ප්‍රාථමික අංශයේද බහුතරයක් තෘතීයික හා සේවා අංශවලද නියැලී සිටින විට", "මුළු ශ්‍රම බලකායෙන් සියයට අනූවකට වැඩි පිරිසක් සාම්ප්‍රදායික ගොවිතැනේ නියැලී සිටින විට", "රටේ සමස්ත ආර්ථිකය තුළ කිසිදු පුද්ගලයෙකු වෙළඳ හා සේවා අංශවල නිරත නොවන විට", "රටේ වැඩ කරන වයසේ පසුවන සියලුම පුරවැසියන් සම්පූර්ණයෙන්ම රැකියා විරහිතව සිටින විට",
        "ආර්ථික සංවර්ධනය සමඟ ශ්‍රම බලකාය කෘෂිකර්මයේ සිට කර්මාන්ත හා සේවා අංශ වෙත මාරු වේ."),
      q(t, "'සංක්‍රමණික ශ්‍රමිකයන්ගේ අයිතිවාසිකම්' සුරැකීම ජනගහන භූගෝල විද්‍යාවේ වැදගත් කරුණක් වන්නේ ඇයි?",
        "නීතිවිරෝධී මිනිස් ජාවාරම් වැළැක්වීම, සාධාරණ වැටුප්, සෞඛ්‍ය රැකවරණය හා පවුල් සුබසාධනය තහවුරු කිරීම සඳහා", "විදේශ ගමන් බලපත්‍ර හා වීසා ගාස්තු අසීමිත ලෙස ඉහළ දැමීමට පමණක් පියවර ගැනීම සඳහා", "රටේ ප්‍රධාන ජාත්‍යන්තර ගුවන් තොටුපළ හා මුහුදු වරායන් සියල්ල වසා දැමීම සඳහා", "රටවල් අතර සිදුවන සියලුම නීත්‍යානුකූල සංචාර හා සංක්‍රමණ සම්පූර්ණයෙන් තහනම් කිරීම සඳහා",
        "විශේෂයෙන් ගෘහ සේවිකාවන් හා ඉදිකිරීම් ශ්‍රමිකයන් ආරක්ෂා කිරීම සඳහා ද්විපාර්ශ්වික රාජ්‍ය ගිවිසුම් වැදගත් වේ."),
      q(t, "'වැඩිහිටි-හිතකාමී නගර' (Age-friendly Cities) සංකල්පය යටතේ නාගරික ජනාවාස සැලසුම් කළ යුත්තේ කෙසේද?",
        "ප්‍රවේශ පහසු පදික වේදිකා, බැස යාමට පහසු බස් රථ, ප්‍රජා සෞඛ්‍ය මධ්‍යස්ථාන හා උද්‍යාන ඉදිකිරීමෙන්", "සියලුම පොදු ගොඩනැගිලිවල පඩිපෙළවල් ඉතා උස්, බෑවුම් සහිත හා පටු ලෙස ඉදි කිරීමෙන්", "නගර මධ්‍යයේ තිබෙන සියලුම හරිත උද්‍යාන ඉවත් කර බර කර්මාන්තශාලා තැනීමෙන්", "වැඩිහිටි වෛද්‍ය සේවා හා රෝහල් පහසුකම් ගණන සැලකිය යුතු ලෙස අඩු කර දැමීමෙන්",
        "ලෝක සෞඛ්‍ය සංවිධානය (WHO) ජනගහන වයස්ගත වීමට මුහුණ දීම සඳහා මෙම සංකල්පය හඳුන්වා දී ඇත."),
      q(t, "ජන සංඛ්‍යා විද්‍යාවේදී 'ආයු අපේක්ෂාව' (Life Expectancy) ගණනය කිරීම සඳහා භාවිත කරන ප්‍රධාන මෙවලම කුමක්ද?",
        "එක් එක් වයස් කාණ්ඩයේ මියයාමේ හා ජීවත් වීමේ සම්භාවිතාව දක්වන ජීවිත වගුව (Life Table)", "රටේ මුළු භූමි වර්ගඵලය හා වනාන්තර ආවරණය මැන බලන භූගෝලීය සිතියම් පරිමාණය", "විවිධ කාලගුණික මධ්‍යස්ථානවලින් රැස් කරන ලද මාසික වර්ෂාපතන හා උෂ්ණත්ව වගුව", "ජාතික මැතිවරණවලදී ප්‍රකාශිත මුළු වලංගු ඡන්ද සංඛ්‍යාව සටහන් කරන ඡන්ද නාමලේඛනය",
        "රක්ෂණ සමාගම්, විශ්‍රාම අරමුදල් හා ජාතික සෞඛ්‍ය සැලසුම්කරණයේදී ජීවිත වගු අත්‍යවශ්‍ය මෙවලමකි."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවල නගරවල 'ඌන සේවා නියුක්තිය' (Underemployment) බහුල වන්නේ ඇයි?",
        "බොහෝ දෙනා සුදුසුකම්වලට හෝ කාලයට නොගැළපෙන අඩු වැටුප් අර්ධ-කාලීන රැකියාවල නිරත වීමට සිදුවීම නිසා", "රටේ තරුණ ශ්‍රම බලකායේ කිසිවෙකු කිසිදු රැකියාවක් කිරීමට කැමැත්තක් නොදක්වන නිසා", "සාමාන්‍ය කර්මාන්තශාලා රැකියා සඳහා ගෙවන දෛනික වැටුප් ඉතා ඉහළ මට්ටමක පවතින නිසා", "රටේ පවතින රැකියා අවස්ථා සංඛ්‍යාව වැඩ කරන ජනගහනය මෙන් දස ගුණයක් වන නිසා",
        "තරුණ උපාධිධාරීන්ගේ නිපුණතා ආර්ථිකයේ ඉල්ලුමට නොගැළපීම (Skills Mismatch) මෙම ගැටලුව තීව්‍ර කරයි."),
      q(t, "'ප්‍රවාහන මාරු මධ්‍යස්ථාන' (Break-of-Bulk Points) විශාල වාණිජ නගර බවට පත්වීමට හේතුව කුමක්ද?",
        "භාණ්ඩ නැවෙන් දුම්රියට හෝ ට්‍රක් රථයට මාරු කරන තැන්වල ගබඩා, බැංකු හා සැකසුම් කර්මාන්ත ගොඩනැගීම", "රටේ ප්‍රධාන මහාමාර්ගවල රථවාහන ගමන් කිරීම රජය විසින් සම්පූර්ණයෙන් තහනම් කිරීම", "රටේ සියලුම ගොඩබිම් හා ජල ප්‍රවාහන මාර්ග හදිසියේම අතරමගදී අවසන් වීම", "උස් කඳු වැටි හරහා කිසිදු මාර්ගයක් හෝ උමඟක් ඉදිකිරීමට නොහැකි වීම",
        "රොටර්ඩෑම්, සිංගප්පූරුව, චිකාගෝ හා කොළඹ ලොව ප්‍රධාන ප්‍රවාහන මාරු නගර වේ."),
      q(t, "'ගෝලීය නගර' (World Cities - උදා: නිව්යෝක්, ලන්ඩන්, ටෝකියෝ) අනෙකුත් විශාල නගරවලින් වෙනස් වන්නේ කෙසේද?",
        "ලෝක ආර්ථිකය, ජාත්‍යන්තර බැංකු, කොටස් වෙළඳපොළ හා බහුජාතික සමාගම් මූලස්ථාන එහි පිහිටා තිබීම", "ඒවා ඉතා කුඩා ජනගහනයක් සහිත හුදකලා ග්‍රාමීය කෘෂිකාර්මික ගම්මාන ලෙස පැවතීම", "ඒවායේ කිසිදු වාණිජ බැංකුවක් හෝ ජාත්‍යන්තර ගුවන්තොටුපළක් පිහිටා නොතිබීම", "එම නගරවල ආර්ථිකය සම්පූර්ණයෙන්ම ප්‍රාථමික වී ගොවිතැන හා මසුන් ඇල්ලීම මත රඳා පැවතීම",
        "ගෝලීය නගර ජාත්‍යන්තර මූල්‍ය, වෙළඳ හා තොරතුරු සන්නිවේදන ජාලවල කේන්ද්‍රස්ථාන ලෙස ක්‍රියා කරයි."),
      q(t, "'නාගරික තාප ආතතිය' (Urban Heat Stress) වැඩි වශයෙන්ම බලපාන සමාජ කණ්ඩායම් කවුරුන්ද?",
        "වැඩිහිටියන්, කුඩා දරුවන්, එළිමහන් කම්කරුවන් හා වායු සමීකරණ රහිත නිවාසවල ජීවත් වන්නන්", "සම්පූර්ණයෙන්ම වායු සමීකරණය කළ උස් ගොඩනැගිලි තුළ සේවය කරන කාර්යාල සේවකයන් පමණි", "වසර පුරා අධික හිම පතනයක් පවතින ධ්‍රැව කලාපීය අයිස් තට්ටු අසල වැසියන්", "ගැඹුරු සාගරයේ ධීවර කටයුතුවල නිරත වන විශාල නෞකාවල නාවිකයන්",
        "නගරවල සෙවණ දෙන ගස් සිටුවීම හා හරිත උද්‍යාන පිහිටුවීම නාගරික උෂ්ණත්වය අඩු කිරීමට වැදගත් වේ."),
      q(t, "වෙරළබඩ සංචාරක නගරවල 'නිත්‍ය පදිංචිකරුවන්' හා 'සෘතුමය සංචාරකයන්' වෙන්කර හඳුනා ගැනීම වැදගත් වන්නේ ඇයි?",
        "සංචාරක සමයේදී ජලය, විදුලිය, කසළ හා ප්‍රවාහන ඉල්ලුම ස්ථිර ජනගහනයට වඩා කිහිප ගුණයකින් ඉහළ යන බැවින්", "විදේශීය හා දේශීය සංචාරකයන් කිසිසේත්ම පානීය ජලය හෝ විදුලි බලය භාවිත නොකරන බැවින්", "සංචාරකයන් සෑම නගරයකම ස්ථිර නේවාසික නිවාස හා පාසල් ඉදි කිරීමට පියවර ගන්නා බැවින්", "සංචාරකයන් පැමිණීමෙන් නගරයේ යටිතල පහසුකම් හා සේවා සැපයුමට කිසිදු බලපෑමක් ඇති නොවන බැවින්",
        "හික්කඩුව, ඇල්ල, නුවරඑළිය හා ආරුගම් බේ වැනි නගරවල යටිතල පහසුකම් උච්ච සමය අනුව සැලසුම් කළ යුතුය."),
      q(t, "භූමිය ගිලා බැසීම හා මුහුදු මට්ටම ඉහළ යාම නිසා අගනුවර රට අභ්‍යන්තරයට මාරු කිරීමට තීරණය කළ ආසියානු රට කුමක්ද?",
        "ඉන්දුනීසියාව (ජකර්තා සිට බෝර්නියෝ දූපතේ නුසන්තාරා වෙත)", "හිමාලය කඳුකරයේ පිහිටි ගොඩබිමින් වටවූ නේපාලය", "දකුණු ආසියාවේ කඳුකර රාජ්‍යයක් වන භූතානය", "ගිනිකොනදිග ආසියාවේ මුහුදු වෙරළක් නොමැති ලාවෝසය",
        "භූගත ජලය අධික ලෙස පොම්ප කිරීම නිසා ගිලා බැසීම හා ජනගහන තදබදය ජකර්තා නගරයට දැඩි තර්ජනයක් විය."),
      q(t, "'දුරස්ථ ග්‍රාමීය ජනාවාසවල' ජීවන තත්ත්වය හා සේවා ප්‍රවේශය නැංවීමට වර්තමානයේ යොදා ගන්නා ප්‍රබල මෙවලම කුමක්ද?",
        "අධිවේගී අන්තර්ජාලය, දුරස්ථ වෛද්‍ය සේවා, මාර්ගගත අධ්‍යාපනය හා ජංගම බැංකු සේවා", "ගම්මානවල තිබෙන සියලුම පාසල් හා ප්‍රාදේශීය රෝහල් සම්පූර්ණයෙන්ම වසා දැමීම", "ප්‍රදේශයේ සන්නිවේදන කුළුණු ගලවා ඉවත් කර පැරණි ලිපි හුවමාරුවට පමණක් සීමා වීම", "නගරයට යන සියලු පොදු බස් රථ සේවා නවතා දමා ගමනාගමනය සීමා කිරීම",
        "ඩිජිටල් සම්බන්ධතාවය ග්‍රාමීය හුදකලා බව අඩු කර ගොවීන්ට සෘජු වෙළඳපොළ තොරතුරු ලබා දෙයි."),
      q(t, "ජනාවාසයක 'ප්‍රවේශ්‍යතාව' (Accessibility) ඉහළ යාමෙන් නගරය අවට ඉඩම් පරිභෝජනයට සිදුවන බලපෑම කුමක්ද?",
        "නව අධිවේගී මාර්ග හෝ දුම්රිය නැවතුම් අවට ඉඩම් මිල ඉහළ ගොස් වාණිජ හා නිවාස සංවර්ධනය වේගවත් වේ", "ප්‍රවේශ පහසුකම් වැඩි වූ විගස එම ප්‍රදේශයේ පදිංචි සියලු ජනතාව වහාම ඉන් ඉවත් වේ", "මාර්ග අසල පිහිටි සියලුම වාණිජ හා නේවාසික ඉඩම්වල වටිනාකම බිංදුව දක්වා පහත වැටේ", "එම මාර්ගය දෙපස ගොඩනැගිලි ඉවත් වී ඝන නිවර්තන වැසි වනාන්තරයක් ඉබේම නිර්මාණය වේ",
        "ශ්‍රී ලංකාවේ දක්ෂිණ අධිවේගී මාර්ගයේ පිවිසුම් අවට නාගරීකරණය මීට නිදසුනකි."),
      q(t, "නාගරික සැලසුම්කරණයේදී පදිකයන්ට ආරක්ෂිත පොදු පරිසරයක් නිර්මාණය කිරීම සඳහා ගනු ලබන ප්‍රධාන පියවර මොනවාද?",
        "හොඳ වීදි ආලෝකකරණය, විවෘත පොදු උද්‍යාන, සක්‍රීය වීදි මුහුණත් හා ප්‍රජා අධීක්ෂණය ඇති කිරීම", "සියලු නේවාසික නිවාසවල වීදිය දෙසට ඇති ජනෙල් හා බැල්කනි සම්පූර්ණයෙන් ගඩොල්වලින් වැසීම", "විදුලිය ඉතිරි කිරීම සඳහා රාත්‍රී කාලයේ නගරයේ සියලු වීදි ලාම්පු නිවා දැමීම", "මහජනතාවට ඇතුළු විය නොහැකි ලෙස සියලු පොදු උද්‍යාන උස් තාප්ප බැඳ වසා දැමීම",
        "සුරක්ෂිත හා සජීවී නාගරික අවකාශයන් සෑම පුරවැසියෙකුටම නිදහසේ ගමන් කිරීමට ඉඩ සලසයි."),
      q(t, "'ලෝක ජනගහන දිනය' (World Population Day) එක්සත් ජාතීන් විසින් සෑම වසරකම සමරනු ලබන්නේ කවදාද?",
        "ජූලි මස 11 වන දින (1987 ජූලි 11 ලෝක ජනගහනය බිලියන 5 ඉක්මවීම සිහිපත් කරමින්)", "ජනවාරි මස 01 වන දින නව වසරේ ආරම්භක ජාත්‍යන්තර දිනය ලෙසින්", "දෙසැම්බර් මස 25 වන දින වසර අවසාන ශීත සෘතු උත්සවයත් සමඟින්", "අප්‍රේල් මස 22 වන දින ජාත්‍යන්තර මිහිකත හා පරිසර සංරක්ෂණ දිනය ලෙසින්",
        "ජනගහන සංවර්ධනය, ප්‍රජනක සෞඛ්‍යය හා තිරසාර සම්පත් කළමනාකරණය පිළිබඳ දැනුවත් කිරීම මෙහි අරමුණයි."),
      q(t, "'ජනගහන වයස්ගත වීම' පිළිබඳව චීනය මෑතකදී තම ජනගහන ප්‍රතිපත්තිය වෙනස් කළේ කෙසේද?",
        "එක් දරු ප්‍රතිපත්තිය අහෝසි කර දරුවන් දෙදෙනෙකුට හා පසුව තිදෙනෙකුට ඉඩ දී උපත් දිරිමත් කළේය", "රටේ සියලු පවුල්වලට දරුවන් බිහි කිරීම නීතියෙන් සම්පූර්ණයෙන්ම තහනම් කරන ලදී", "වයස්ගත වීම පාලනය කිරීම සඳහා ජාතික මරණ අනුපාතය ඉහළ දැමීමේ පියවර ගන්නා ලදී", "නාගරික පවුල්වල වියදම් අඩු කිරීම සඳහා රටේ සියලු ප්‍රාථමික පාසල් වසා දමන ලදී",
        "එසේ වුවද නාගරික ජීවන හා අධ්‍යාපන වියදම් ඉහළ නිසා චීනයේ උපත් අනුපාතය තවමත් පහළ මට්ටමක පවතී."),
      q(t, "නුවරඑළිය, ඇල්ල හා ක්වීන්ස්ටවුන් වැනි 'සංචාරක නගර' (Tourism Towns) බිහිවන්නේ කුමන භූගෝලීය සාධක මතද?",
        "සිසිල් දේශගුණය, සුන්දර කඳු හෝ වෙරළ භූ දර්ශන, වනජීවී හා සංස්කෘතික උරුම ආකර්ෂණය මත", "භූගතව පිහිටි විශාල ගල් අඟුරු හා යපස් පතල් කැණීමේ කර්මාන්තශාලා පදනම් කරගෙන", "අධික දුම් හා රසායනික අපද්‍රව්‍ය පිට කරන බර කර්මාන්ත උද්‍යාන මධ්‍යයේ පිහිටා තිබීම මත", "කිසිදු ශාක වැස්මක් හෝ ජල සම්පතක් නොමැති ශුෂ්ක වැලි කාන්තාර පමණක් පැවතීම මත",
        "මෙම නගරවල අධික හෝටල් ඉදිකිරීම් පරිසරයට හා ස්වාභාවික සුන්දරත්වයට හානි නොවන පරිදි පාලනය කළ යුතුය."),
      q(t, "වර්තමාන ජනගහනය තුළ සෞඛ්‍ය අංශයේ 'ද්විත්ව රෝග බර' (Double Burden of Disease) ලෙස හඳුන්වන්නේ කුමක්ද?",
        "එකම රටක එක් පසෙකින් මන්දපෝෂණය හා බෝවන රෝගද අනෙක් පසින් තරබාරුකම හා දියවැඩියාවද පැවතීම", "රටේ සියලුම පුරවැසියන් එකම ආකාරයකින් අධික බර හා ස්ථූලතාවයෙන් පමණක් පීඩා විඳීම", "වෛද්‍ය තාක්ෂණය දියුණු වීම නිසා රට තුළ කිසිදු බෝවන හෝ බෝ නොවන රෝගයක් නැති වීම", "වැඩිහිටියන් කිසිවෙකු රෝගී නොවී කුඩා දරුවන් පමණක් සෘතුමය උණ රෝගවලට ගොදුරු වීම",
        "සෞඛ්‍ය හා පෝෂණ ප්‍රතිපත්ති සැලසුම් කිරීමේදී මෙම ද්විත්ව අභියෝගයට මුහුණ දීමට සිදුවේ."),
      q(t, "'රාජ්‍ය ආයතන හා කාර්යාල විමධ්‍යගත කිරීම' (Decentralization) මහා නගරවල ජීවන තත්ත්වය දියුණු කරන්නේ කෙසේද?",
        "අමාත්‍යාංශ හා ආයතන තදාසන්න නගරවලට ගෙන යාමෙන් මධ්‍යම නගරයේ වාහන තදබදය හා ඉඩම් පීඩනය අඩු කිරීම", "රටේ සියලුම රාජ්‍ය කාර්යාල අගනුවර මධ්‍යයේ එකම විශාල ගොඩනැගිල්ලක් තුළට එක්රැස් කිරීම", "මගී ප්‍රවාහනය සඳහා නගරයට පැමිණෙන සියලුම පොදු බස් රථ නගර සීමාවේ නතර කර තැබීම", "නගරයේ ප්‍රධාන වීදි පටු කර පෞද්ගලික මෝටර් රථ ගමනාගමනය පමණක් දිරිමත් කිරීම",
        "බත්තරමුල්ල හා පැලවත්ත ප්‍රදේශවලට රජයේ ආයතන ගෙන යාම කොළඹ කොටුවේ තදබදය අඩු කිරීමේ පියවරකි."),
      q(t, "ඇතැම් සංවර්ධිත රටවල 'දළ මරණ අනුපාතය' (CDR) තරුණ ජනගහනයක් ඇති රටකට වඩා තරමක් වැඩි අගයක් ගන්නේ ඇයි?",
        "සංවර්ධිත රටවල ආයු අපේක්ෂාව ඉහළ වුවද සමස්ත ජනගහනයෙන් විශාල කොටසක් වයස්ගත වැඩිහිටියන් වීම නිසා", "සංවර්ධිත යුරෝපීය රටවල නවීන රෝහල්, වෛද්‍යවරුන් හා ඖෂධ පහසුකම් කිසිසේත්ම නොමැති නිසා", "තරුණ ජනගහනයක් සිටින රටවල කිසිදු පුද්ගලයෙකු වයසට නොගොස් සදාකාලිකව ජීවත් වන නිසා", "සංවර්ධිත රටවල සෑම වසරකම දරුණු සිවිල් යුද ගැටුම් හා සාගත තත්ත්වයන් පවතින නිසා",
        "එබැවින් සෞඛ්‍ය තත්ත්වය සංසන්දනය කිරීමට CDR වෙනුවට ළදරු මරණ අනුපාතය හා ආයු අපේක්ෂාව භාවිත කෙරේ."),
      q(t, "'අවිධිමත් නාගරික ජනාවාසවල' (Slums / Shanties) ස්වාභාවික ආපදා අවදානම ඉහළ මට්ටමක පවතින්නේ ඇයි?",
        "ඒවා බොහෝ විට නායයෑම් අවදානම් බෑවුම්, ගංගා ඉවුරු හෝ පහත් බිම්වල දුර්වල ලෙස ඉදි කර ඇති බැවින්", "ඒවා නවීන ඉංජිනේරු ප්‍රමිතීන්ට අනුකූලව ශක්තිමත් කොන්ක්‍රීට් අත්තිවාරම් මත ඉදි කර ඇති නිසා", "ඒවා ආපදාවලින් තොර උස් ස්ථාවර සානු ප්‍රදේශවල විධිමත් සැලසුමකට අනුව පිහිටා ඇති නිසා", "එම ප්‍රදේශවල වාර්ෂික වර්ෂාපතනය හා සුළං වේගය අනෙක් පෙදෙස්වලට වඩා ඉතා අඩු මට්ටමක පවතින නිසා",
        "එබැවින් අධික වර්ෂාවකදී හෝ භූ කම්පනයකදී වැඩිම ජීවිත හා දේපළ හානිය මෙම ප්‍රජාවන්ට සිදුවේ."),
      q(t, "ශ්‍රී ලංකාවේ ග්‍රාමීය යටිතල පහසුකම් සංවර්ධන ව්‍යාපෘති මගින් අත්කර ගත් ප්‍රධාන භූගෝලීය වෙනස කුමක්ද?",
        "ග්‍රාමීය මාර්ග, විදුලිය, පානීය ජලය හා පාසල් දියුණු වී ගම හා නගරය අතර සේවා පරතරය අඩු වීම", "සංවර්ධන ව්‍යාපෘති නිසා රටේ තිබූ සියලුම ග්‍රාමීය ජනාවාස සම්පූර්ණයෙන්ම අතුරුදහන් වී යාම", "ග්‍රාමීය ප්‍රදේශවල සාම්ප්‍රදායික වී හා එළවළු ගොවිතැන රජය විසින් නීතියෙන් තහනම් කරනු ලැබීම", "වැව් හා ඇළ මාර්ග පිළිසකර කිරීම නිසා ප්‍රදේශයේ සියලු ප්‍රධාන ගංගා සම්පූර්ණයෙන් සිඳී යාම",
        "ග්‍රාමීය මාර්ග ජාලය දියුණු වීම නිසා කෘෂි නිෂ්පාදන වෙළඳපොළට ගෙන යාම ඉක්මන් හා ලාභදායී විය."),
      q(t, "19 වන සියවසේ සිදුවූ 'මහා යුරෝපීය ජන සංක්‍රමණ රළ' මගින් ලෝක ජනගහන භූගෝලය වෙනස් කළේ කෙසේද?",
        "මිලියන ගණනක් යුරෝපීයයන් ඇමරිකාවට හා ඔස්ට්‍රේලියාවට ගොස් එහි ජන සංයුතිය හා නගර වෙනස් කළේය", "යුරෝපයේ සිටි සියලුම වැසියන් ස්ථිර පදිංචිය සඳහා අයිස්වලින් වැසුණු ඇන්ටාක්ටිකා මහාද්වීපයට ගියේය", "මෙම සංක්‍රමණ හේතුවෙන් ආසියානු මහාද්වීපයේ මුළු ජනගහනය සම්පූර්ණයෙන්ම ජනශූන්‍ය තත්ත්වයට පත් විය", "යුරෝපයේ තිබූ ලන්ඩන් හා පැරිස් වැනි සියලුම පැරණි නගර පාළු වී සම්පූර්ණයෙන් විනාශ විය",
        "අද වන විටත් ඇමරිකාවේ, කැනඩාවේ හා ඔස්ට්‍රේලියාවේ සංස්කෘතික හා ජන විකාශන පදනම එම සංක්‍රමණ මගින් සැකසී ඇත."),
      q(t, "නගරයක 'රථවාහන තදබදය පාලනය කිරීමේදී' ලන්ඩන් හා සිංගප්පූරු නගර සාර්ථකව භාවිත කළ ක්‍රමවේදය කුමක්ද?",
        "නගර මධ්‍යයට පෞද්ගලික රථ ඇතුළු කිරීමට තදබද ගාස්තු අය කර පොදු බස් හා දුම්රිය සේවා නවීකරණය කිරීම", "නගරයේ සියලුම මහාමාර්ග හා පාලම් වසා දමා පුරවැසියන්ගේ ගමනාගමනය සම්පූර්ණයෙන්ම අත්හිටුවීම", "නගරය තුළ ක්‍රියාත්මක වන සියලුම පොදු දුම්රිය හා උමං මාර්ග සේවා අවලංගු කර ඉවත් කිරීම", "පෞද්ගලික මෝටර් රථ භාවිතය වැඩි කිරීම සඳහා රියදුරන්ට පෙට්‍රල් හා ඩීසල් නොමිලේ ලබා දීම",
        "මෙමගින් රථවාහන ධාවන වේගය වැඩි වූ අතර නාගරික වායු දූෂණය සැලකිය යුතු ලෙස පහත වැටුණි."),
      q(t, "'දැනුම මත පදනම් වූ ආර්ථිකයේ' (Knowledge Economy) ශ්‍රම බලකාය ගොඩනැගීමට රටක් ආයෝජනය කළ යුතු ප්‍රධාන ක්ෂේත්‍ර මොනවාද?",
        "විද්‍යා-තාක්ෂණ අධ්‍යාපනය, වෘත්තීය පුහුණුව, ඩිජිටල් සාක්ෂරතාව, පර්යේෂණ සහ නවෝත්පාදන", "කිසිදු යන්ත්‍ර සූත්‍රයකින් තොර සාම්ප්‍රදායික නුපුහුණු කායික කම්කරු ශ්‍රමය පමණක් දිරිමත් කිරීම", "නවීන තාක්ෂණය ඉවතලා ප්‍රාථමික ගල් ආයුධ හා සාම්ප්‍රදායික හස්ත කර්මාන්ත පමණක් ප්‍රචලිත කිරීම", "ළමුන්ගේ අධ්‍යාපන වියදම් අඩු කිරීම සඳහා පාසල් අධ්‍යාපනය වසර තුනකට පමණක් සීමා කිරීම",
        "මිනිස් ප්‍රාග්ධනය ගුණාත්මකව ඉහළ නැංවීම ස්වාභාවික සම්පත් අඩු රටවලට පවා ඉහළ සංවර්ධනයක් ලබා දෙයි."),
      q(t, "නගරවල ඉඩම් හිඟය මගහරවා ගන්නා 'නාගරික කෘෂිකර්මය' (Urban Agriculture) ජනාවාසවලට වැදගත් වන්නේ ඇයි?",
        "ගොඩනැගිලි වහල මත හා සිරස් හරිතාගාරවල එළවළු වගා කර ප්‍රවාහන දුර අඩු කර නැවුම් ආහාර සැපයීම", "නගරයේ වෙළඳපොළේ සහල් හා එළවළු මිල ගණන් දස ගුණයකින් ඉහළ දමා ලාභ ලැබීම", "නගරයේ පිහිටි සියලුම හරිත උද්‍යාන කොන්ක්‍රීට් අතුරා කඩ සාප්පු බවට පත් කිරීම", "ග්‍රාමීය ප්‍රදේශවල ගොවීන්ට නගරයට එළවළු ගෙන ඒම නීතියෙන් සම්පූර්ණයෙන්ම තහනම් කිරීම",
        "සිංගප්පූරුව 2030 වන විට සිය පෝෂණ අවශ්‍යතාවයෙන් 30% ක් දේශීයව හා නාගරික ගොවිපළවලින් නිපදවීමට ඉලක්ක කරයි."),
      q(t, "ඇන්ඩීස් හා ඉතියෝපියානු උස්බිම්වල ජනාවාස පහත් බිම්වලට වඩා ඉහළ කඳුකරයේ (මීටර් 2,000–3,600) පිහිටා ඇත්තේ ඇයි?",
        "සමක පහත් බිම් අධික උණුසුම හා රෝග බහුල වන විට උස් සානුවල සෞම්‍ය සිසිල් දේශගුණයක් පැවතීම", "මුහුදු මට්ටමට වඩා ඉතා උස් කඳු මුදුන්වල වායුගෝලීය ඔක්සිජන් ප්‍රතිශතය සියයට සියයක් පවතින නිසා", "නිවර්තන කලාපයේ පහත් බිම් තැනිතලා වසර පුරාම ඝන අයිස් හා හිම තට්ටුවලින් වැසී ඇති නිසා", "මිරිදිය ජලය හා මුහුදු වරායන් පිහිටා ඇත්තේ පහත් බිම්වල නොව උස් කඳු මුදුන්වල පමණක් වන නිසා",
        "බොගෝටා (කොලොම්බියාව), ක්විටෝ (ඉක්වදෝරය), ලා පාස් (බොලිවියාව) හා අඩිස් අබාබා මීට ප්‍රධාන උදාහරණ වේ."),
      q(t, "'ප්‍රජා සහභාගීත්ව සැලසුම්කරණය' (Community-Based Planning) ජනාවාස ව්‍යාපෘති සාර්ථක වීමට හේතු වන්නේ කෙසේද?",
        "පදිංචි ජනතාවගේ සැබෑ අවශ්‍යතා සැලසුම් කිරීමට ඔවුන්වම සම්බන්ධ කර ගැනීමෙන් ව්‍යාපෘතිවල තිරසාරභාවය රැකීම", "ප්‍රදේශයේ ජනතාවගෙන් නොවිමසා පිටස්තර නිලධාරීන්ගේ අදහස් පමණක් බලහත්කාරයෙන් ක්‍රියාත්මක කිරීම", "සංවර්ධන ව්‍යාපෘති පිළිබඳ මූල්‍ය හා තාක්ෂණික තොරතුරු ප්‍රදේශවාසීන්ගෙන් සම්පූර්ණයෙන් සඟවා තැබීම", "ගැටලු ඇති වීම වැළැක්වීම සඳහා ග්‍රාමීය හා නාගරික සියලුම සංවර්ධන සැලසුම් සම්පූර්ණයෙන් නවතා දැමීම",
        "සහභාගීත්ව සංවර්ධන ප්‍රවේශය මගින් ප්‍රජා අයිතිවාසිකම් හා වගකීම ශක්තිමත් වේ."),
      q(t, "'ජනගහනයේ සංස්කෘතික හා භාෂාමය විවිධත්වය' රටක සංවර්ධනයට ධනාත්මකව දායක කර ගන්නේ කෙසේද?",
        "සියලු ප්‍රජාවන්ට සමාන අවස්ථා ලබා දීමෙන් සමාජ සංහිඳියාව, සංචාරක ආකර්ෂණය හා ජාතික සංවර්ධනය ශක්තිමත් කිරීම", "සමාජයේ පවතින විවිධ භාෂා භාවිතය හා ඉගෙනීම නීතියෙන් සම්පූර්ණයෙන්ම තහනම් කර දැමීම", "සියලුම සාම්ප්‍රදායික ආගමික හා සංස්කෘතික උත්සව පැවැත්වීම රට පුරා නවතා දැමීම", "විවිධ ජන කොටස් වාසය කරන ප්‍රධාන වාණිජ නගර අතර ගමනාගමනය වසා දැමීම",
        "ස්විට්සර්ලන්තය, කැනඩාව, සිංගප්පූරුව හා ශ්‍රී ලංකාව වැනි බහු-සංස්කෘතික රටවල සමානාත්මතාවය ස්ථාවර සංවර්ධනයට පදනම වේ."),
      q(t, "ග්‍රාමීය ජනාවාසවල පිරිසිදු පානීය ජලය හා සනීපාරක්ෂාව (WASH) දියුණු කිරීමෙන් ජනගහන දර්ශකවලට ලැබෙන බලපෑම කුමක්ද?",
        "පාචනය හා කොලරාව වැනි ජලයෙන් බෝවන රෝග අඩු වී ළදරු මරණ අනුපාතය තියුණු ලෙස පහත වැටීම", "රටේ සමස්ත ජන ඝනත්වය හා නාගරික ජනගහනය බිංදුව දක්වා පහත වැටීම", "ජනගහනයේ වාර්ෂික උපත් අනුපාතය ක්‍රමයෙන් අඩු වී සම්පූර්ණයෙන් ශුන්‍ය වීම", "පිරිසිදු ජලය ලැබීම නිසා ග්‍රාමීය ප්‍රදේශවල කෘෂිකාර්මික කටයුතු සම්පූර්ණයෙන් නතර වීම",
        "එක්සත් ජාතීන්ගේ SDG 6 ඉලක්කය යටතේ සැමට පිරිසිදු ජලය හා සනීපාරක්ෂාව තහවුරු කිරීම ප්‍රමුඛ කාර්යයකි."),
      q(t, "'අර්ධ නාගරිකකරණය' (Peri-urbanization) තුළ කුඹුරු හා තෙත්බිම් ගොඩකිරීම නිසා ඇතිවන පාරිසරික ගැටලුව කුමක්ද?",
        "වැසි ජලය බැස යාමට ඉඩ නැතිව නාගරික ගංවතුර වැඩි වීම හා දේශීය ආහාර නිෂ්පාදනය අඩු වීම", "නගරය අවට ස්වාභාවික වනාන්තර ආවරණය හා වන සතුන් සංඛ්‍යාව කිහිප ගුණයකින් වැඩි වීම", "ගොවි බිම් අඩු වුවද ප්‍රදේශයේ වාර්ෂික වී නිෂ්පාදනය දෙගුණයකින් ඉහළ යාම", "කොන්ක්‍රීට් ඇතිරීම නිසා පොළොව යට භූගත ජල මට්ටම වෙනදාට වඩා ඉහළ මට්ටමකට පැමිණීම",
        "ශ්‍රී ලංකාවේ කඩුවෙල, හෝමාගම, මීගමුව හා ගාල්ල තදාසන්න පෙදෙස්වල කුඹුරු ගොඩකිරීම නීතියෙන් නියාමනය කිරීමට සිදුව ඇත."),
      q(t, "නවීන තාක්ෂණය හා ස්වයංක්‍රීයකරණය (Automation) වර්තමාන නාගරික රැකියා රටාවට බලපාන්නේ කෙසේද?",
        "සාමාන්‍ය දිනචර්යාත්මක රැකියා අඩු වී තොරතුරු තාක්ෂණ, නඩත්තු, සෞඛ්‍ය හා නිර්මාණශීලී සේවා ඉල්ලුම වැඩි වීම", "නාගරික උගත් තරුණ තරුණියන් සියලු දෙනා සාම්ප්‍රදායික ගොවිතැනට පමණක් ආපසු යාම", "නවීන යන්ත්‍ර සූත්‍ර පැමිණි නිසා පාසල් හා වෘත්තීය අධ්‍යාපනය කිසිසේත්ම අවශ්‍ය නොවීම", "රැකියා ආරක්ෂා කිරීම සඳහා සියලුම කාර්යාලවල පරිගණක භාවිතය නීතියෙන් තහනම් කර දැමීම",
        "එබැවින් ජීවිත කාලය පුරාම නව කුසලතා ඉගෙනීම නූතන ශ්‍රම බලකායට අත්‍යවශ්‍ය වේ."),
      q(t, "කුඩා ග්‍රාමීය නගරවල 'කෘෂිකාර්මික අගය එකතු කිරීම' (Agro-processing) ප්‍රවර්ධනය කිරීමෙන් සංක්‍රමණයට ඇතිවන බලපෑම කුමක්ද?",
        "කෘෂි බෝග ගමේදීම පිරිසැකසුම් කර ඇසුරුම් කිරීමෙන් ගම තුළම තරුණයන්ට ඉහළ ආදායම් රැකියා බිහි වේ", "අමුද්‍රව්‍ය මිල අඩු වී ග්‍රාමීය ගොවීන්ගේ වාර්ෂික ආදායම සම්පූර්ණයෙන්ම පහත වැටේ", "සැකසුම් කර්මාන්ත නිසා ගමේ වගා කරන එළවළු හා පලතුරු අස්වැන්න සම්පූර්ණයෙන් විනාශ වේ", "ගමේ සිට නගරයට භාණ්ඩ ගෙන යාමේ ප්‍රවාහන ගාස්තු අසීමිත ලෙස ඉහළ ගොස් වෙළඳාම නවතී",
        "පලතුරු යුෂ, කුළුබඩු සැකසීම, කිරි නිෂ්පාදන හා කාබනික ඇසුරුම් කර්මාන්ත ග්‍රාමීය ආර්ථිකය ශක්තිමත් කරයි."),
      q(t, "'ජනගහන ඝනත්වය' සහ 'ජනගහන ප්‍රමාණය' අතර වෙනස පැහැදිලි කරන නිවැරදි සංසන්දනය කුමක්ද?",
        "රුසියාවේ ජනගහනය විශාල වුවද භූමිය විශාල නිසා ඝනත්වය අඩු අතර සිංගප්පූරුවේ භූමිය කුඩා නිසා ඝනත්වය ඉහළය", "රුසියාව ලොව විශාලතම භූමිය හිමි රට බැවින් එහි ජන ඝනත්වය ලෝකයේ වැඩිම අගය වේ", "සිංගප්පූරුවේ ජන ඝනත්වය ඉහළ බැවින් එහි මුළු ජනගහනය බිලියනයකට වඩා වැඩි සංඛ්‍යාවක් ගනී", "රටක මුළු ජනගහන සංඛ්‍යාව සහ ජනගහන ඝනත්වය යන දෙකම සෑම විටම එකම සමාන අගයක් ගනී",
        "ජනගහන සංඛ්‍යාව පමණක් බැලීමෙන් භූමිය මත පවතින ජන පීඩනය හඳුනා ගත නොහැකි අතර ඒ සඳහා ජන ඝනත්වය ගණනය කළ යුතුය."),
      q(t, "'මුහුදුබඩ තැනිතලා' හා 'ගංගා ඩෙල්ටා' පුරාණ ශිෂ්ටාචාර හා විශාල ජනාවාස බිහි කළ ප්‍රධාන භූමි වූයේ ඇයි?",
        "පැතලි භූමියේ ඉදිකිරීම් පහසු වීම, සාරවත් දියළු පස ලැබීම සහ පානීය හා වාරි ජලය පහසුවෙන් ලැබීම", "උස් ගල් පර්වත හා තද බෑවුම් පැවතීම නිසා ගමනාගමනය හා කඳු නැගීම ඉතා පහසු වූ බැවින්", "වසර පුරාම අඛණ්ඩව ලැබෙන දැඩි හිම පතනය නිසා සිසිල් දේශගුණයක් හා අයිස් සම්පත පැවති බැවින්", "සක්‍රීය ගිනිකඳුවලින් විසිවන උණුසුම් ලාවා හා අළු පමණක් භූමිය පුරා තැන්පත් වී තිබූ බැවින්",
        "නයිල්, මෙසපොතේමියා, ඉන්දු හා හොවැංහෝ ගංගා නිම්න ශිෂ්ටාචාර මීට ඓතිහාසික සාක්ෂි සපයයි."),
      q(t, "නාගරික කාර්යයන් අනුව ශ්‍රී ලංකාවේ 'අනුරාධපුරය' සහ 'මහනුවර' නගර ප්‍රධාන වශයෙන් අයත් වන ප්‍රවර්ගය කුමක්ද?",
        "ඓතිහාසික, ආගමික හා සංස්කෘතික උරුම නගර (මෙන්ම පරිපාලන හා සංචාරක මධ්‍යස්ථාන)", "විශාල ආනයනික ඛනිජ තෙල් පිරිපහදු කරන හා නැව්වලට ඉන්ධන සපයන නාවික නගර", "යපස් උණු කර වානේ හා බර යන්ත්‍ර සූත්‍ර නිපදවන බර කාර්මික නගර", "අයිස් හා ධ්‍රැවීය කාලගුණික නිරීක්ෂණ සිදු කරන ජාත්‍යන්තර විද්‍යා පර්යේෂණ නගර",
        "යුනෙස්කෝ ලෝක උරුම ස්ථාන වීම නිසා මෙම නගරවල නවීන සංවර්ධනය පුරාවිද්‍යාත්මක උරුමයන් ආරක්ෂා වන පරිදි සැලසුම් කෙරේ.")
    )
  }
}
